// V0.9.7.8.11 — PWA: gli asset (immagini, audio) sono ora file separati in assets/ e audio/,
// caricati normalmente dal browser via <img>/<audio src="...">, non piu' base64 incorporato.
// Il gioco DATA invece serve subito e ovunque nel codice come oggetto JS gia' pronto: lo carichiamo
// con una XHR SINCRONA (unica eccezione, deliberata) cosi' il resto del file — migliaia di righe
// che oggi si aspettano DATA gia' popolato — non deve cambiare. Richiede di essere servito via
// http(s) (anche in locale), NON funziona aprendo il file direttamente col doppio click.
// V0.9.7.8.33: numero di versione mostrato al giocatore, centralizzato in un unico punto —
// prima era scritto a mano in 3 punti diversi e si era disallineato (mostrava ancora v0.9.5
// nonostante decine di aggiornamenti successivi). Aggiornare SOLO qui d'ora in poi.
const GAME_VERSION = 'v0.9.7.8.33';

// ============================================================
// V0.9.8.0 — ACCOUNT / LOGIN (Supabase + Google). Si gioca sempre anche senza account: il login
// serve per salvare i progressi sul cloud e, piu' avanti, per collegare gli acquisti premium a
// una persona vera invece che a un singolo telefono.
// ============================================================
const SUPABASE_URL = 'https://tumthmpnzbkgkztkakyo.supabase.co';
const SUPABASE_ANON_KEY = 'sb_publishable_RErcEwMWFrWluTHFxqZKsg_zDja9sQ3';
let supabaseClient = null;
let currentUser = null; // null = non loggato. altrimenti { id, email, name, avatarUrl }

function initSupabase(){
  if(typeof window.supabase==='undefined'){ console.warn('Libreria Supabase non caricata'); return; }
  if(supabaseClient) return supabaseClient;
  supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
  supabaseClient.auth.onAuthStateChange((event, session)=>{
    currentUser = session && session.user ? {
      id: session.user.id,
      email: session.user.email,
      name: session.user.user_metadata?.full_name || session.user.user_metadata?.name || session.user.email,
      avatarUrl: session.user.user_metadata?.avatar_url || null,
    } : null;
    // V0.9.8.1: il redirect di ritorno da Google genera un evento di navigazione che il gestore
    // del tasto/gesture indietro puo' scambiare per una vera pressione "indietro" dell'utente,
    // facendo apparire per errore la richiesta di conferma uscita. Segnaliamo per un attimo che
    // e' appena successo un login, cosi' quel gestore sa di doverlo ignorare.
    if(event==='SIGNED_IN'){
      window.__justHandledAuthRedirect = true;
      setTimeout(()=>{ window.__justHandledAuthRedirect = false; }, 3000);
    }
    if(typeof onAuthStateResolved==='function') onAuthStateResolved(event);
  });
  return supabaseClient;
}

async function signInWithGoogle(){
  if(!supabaseClient) initSupabase();
  if(!supabaseClient) return;
  // V0.9.9.16: FIX VERO — un semplice window.* NON sopravvive alla navigazione fisica verso Google
  // e ritorno (l'intera pagina si ricarica, window viene ricreato da zero, qualunque valore
  // impostato qui andrebbe perso). sessionStorage invece sopravvive, essendo legato alla scheda
  // del browser, non al singolo caricamento della pagina.
  try{ sessionStorage.setItem('rdAuthRedirectAt', String(Date.now())); }catch(e){ /* ignorato */ }
  await supabaseClient.auth.signInWithOAuth({
    provider: 'google',
    options: { redirectTo: window.location.href.split('?')[0] } // torna sulla stessa pagina, senza parametri residui
  });
}

async function signOutUser(){
  if(!supabaseClient) return;
  await supabaseClient.auth.signOut();
}

// V0.9.8.0: chiamata quando lo stato di login e' noto per la prima volta (al caricamento) o cambia
// (login/logout avvenuto). Per ora si limita ad aggiornare la UI se siamo sulla schermata titolo —
// il salvataggio cloud vero arriva in un passo successivo.
function onAuthStateResolved(event){
  if(currentUser && (event==='SIGNED_IN' || event==='INITIAL_SESSION')){
    if(typeof pullSaveFromCloud==='function') pullSaveFromCloud();
    if(typeof fetchPremiumStatus==='function') fetchPremiumStatus().then(()=>{
      // V0.9.9.164: BUG CORRETTO — segnalato da Gio (punti 8 e 11): lo stato premium non si vedeva
      // caricato al primo ingresso (serviva un refresh manuale), e dopo un codice premium le run
      // aggiuntive Daily non si sbloccavano subito. Causa: questo ri-render scattava SOLO se
      // l'utente era ancora su title/season-length nel momento esatto in cui la richiesta di rete
      // finiva — se nel frattempo era già passato altrove (es. hub Daily), l'interfaccia restava
      // congelata sui vecchi valori. Ora ricarica su QUALUNQUE schermata tranne lo splash iniziale
      // (dove romperebbe l'animazione di apertura, motivo per cui era stato escluso in origine).
      if(state && state.phase!=='studio-splash') render();
    });
    // V0.9.9.121: sincronizzazione statistiche pubbliche AL LOGIN — segnalato da Gio: senza
    // questo, chi ha progressi vecchi (da prima che esistesse il sistema amici) resta a zero
    // nella scheda finché non sblocca qualcosa di NUOVO, dato che prima la sincronizzazione
    // partiva solo sugli eventi futuri (trofeo/museo/obiettivo), mai su quanto già presente.
    if(typeof pushPublicStatsToCloud==='function') pushPublicStatsToCloud();
    if(typeof riscattaCodiceAmicoInSospesoSeCe==='function') riscattaCodiceAmicoInSospesoSeCe();
  }
  if(!currentUser) isPremiumUser = false; // logout: torna alla condizione gratuita finche' non si ri-loggano
  // V0.9.8.8: NON ri-renderizziamo durante 'studio-splash' — quella schermata non mostra nulla di
  // legato al login, e ricreare il markup li' riavviava l'animazione dello splash (sembrava un
  // glitch, "come se partisse due volte"). Il titolo invece mostra davvero lo stato di login,
  // quindi li' il re-render resta necessario.
  if(state && state.phase==='title'){
    if(typeof render==='function') render();
  }
}
const DATA = (function(){
  const xhr = new XMLHttpRequest();
  xhr.open('GET', 'data/data.json', false);
  xhr.send(null);
  if(xhr.status!==200 && xhr.status!==0){
    document.body.innerHTML = '<div style="padding:40px;color:#fff;font-family:sans-serif;text-align:center;">Impossibile caricare data/data.json (status '+xhr.status+').<br>Questa app va servita via http/https (anche in locale), non aperta col doppio click.</div>';
    throw new Error('Caricamento dati fallito');
  }
  return JSON.parse(xhr.responseText);
})();
// V0.9.3.1: piccola normalizzazione di coerenza costo/potenza/rischio sugli upgrade — non stravolge
// i valori originali (miscela 55/45), corregge solo gli scostamenti piu' evidenti dal modello atteso.
(function rebalanceUpgrades(){
  if(!DATA.upgrade || !DATA.upgrade.length) return;
  const BASE_PER_POINT = 1300000;
  DATA.upgrade.forEach(u=>{
    if(!u.guadagno || u.guadagno<=0) return;
    const riskDiscount = 1 - (u.probfallimento/100)*0.35;
    const modelCost = BASE_PER_POINT * u.guadagno * riskDiscount;
    u.costo = Math.round((0.55*u.costo + 0.45*modelCost)/100000)*100000;
  });
})();
