// funzione di lookup: ripiega sempre sul testo italiano originale se non trova una traduzione,
// non lascia mai un vuoto — anche se in futuro venissero aggiunti nuovi piloti con testi non
// ancora tradotti qui, il gioco continua a funzionare mostrando l'italiano invece di rompersi
function td(testoItaliano){
  if(!testoItaliano || currentLang==='it') return testoItaliano;
  const voce = PILOT_DATA_TRANSLATIONS[testoItaliano];
  return voce && voce[currentLang] ? voce[currentLang] : testoItaliano;
}
// V0.9.7.9.27: modalita' streamer — overlay pensato per OBS con Game Area/Cam Area dedicate.
function hasStreamerBeenAsked(){ try{ return localStorage.getItem('racingDynastyStreamerAskedV1')==='1'; }catch(e){ return false; } }
function markStreamerAsked(){ try{ localStorage.setItem('racingDynastyStreamerAskedV1','1'); }catch(e){} }
function isStreamerModeOn(){ try{ return localStorage.getItem('racingDynastyStreamerModeV1')==='1'; }catch(e){ return false; } }
function setStreamerMode(on){ try{ localStorage.setItem('racingDynastyStreamerModeV1', on?'1':'0'); }catch(e){} }
function getStreamerName(){ try{ return localStorage.getItem('racingDynastyStreamerNameV1')||''; }catch(e){ return ''; } }
function setStreamerName(name){ try{ localStorage.setItem('racingDynastyStreamerNameV1', name); }catch(e){} }

// V0.9.7.9.27: coordinate esatte (in percentuale) delle due zone dentro l'immagine cornice
// 1672x941, misurate per flood-fill dall'immagine fornita.
// V0.9.7.9.32: quando la modalita' streamer usa un iframe (per far si' che il gioco si adatti
// davvero, non solo si rimpicciolisca — vedi activateStreamerFrame), l'istanza DENTRO l'iframe
// deve sapere di esserlo, per non provare a sua volta a costruirsi una cornice annidata.
function isEmbeddedStreamerInstance(){
  try{ return new URLSearchParams(window.location.search).get('embed')==='1'; }catch(e){ return false; }
}
// V0.9.7.9.33: quando la modalita' e' attiva, l'utente interagisce con l'IFRAME (quello visibile),
// non con la pagina esterna — quindi se cambia nome li' dentro, la pagina esterna (dove vive la
// targhetta Twitch) deve accorgersene da sola. L'evento 'storage' scatta automaticamente sulle
// altre finestre della stessa origine quando l'iframe scrive in localStorage.
if(!isEmbeddedStreamerInstance()){
  window.addEventListener('storage', (e)=>{
    if(e.key==='racingDynastyStreamerNameV1'){
      const label = document.getElementById('streamerNameLabel');
      if(label) label.textContent = getStreamerName();
    }
    // V0.9.7.9.38: se la modalita' viene spenta/accesa dall'interno dell'iframe (dove l'utente
    // interagisce davvero mentre e' attiva), la pagina esterna deve accorgersene e reagire per
    // davvero — non solo aggiornare una scritta, ma attivare/disattivare la cornice sul serio.
    if(e.key==='racingDynastyStreamerModeV1'){
      syncStreamerFrameState();
    }
  });
}
const STREAMER_GAME_BOX = { left:0.3589, top:0.0510, width:0.3313, height:0.8927 };
const STREAMER_CAM_BOX  = { left:0.0556, top:0.1722, width:0.2518, height:0.3996 };
// V0.9.7.9.30: targhetta Twitch — coordinate esatte date da Gio (295,111 su immagine 1672x941),
// centro della targhetta, non angolo.
const STREAMER_TWITCH_TAG = { centerX:295/1672, centerY:111/941 };
const STREAMER_FUORISCALA_LOGO = { centerX:126/1672, centerY:886/941 };
// V0.9.9.211: banner link al gioco, RIPOSIZIONATO — Gio ha corretto: i due rettangoli neri sono
// riservati (webcam a sinistra, chat Twitch a destra), non spazio libero. Il posto giusto è sotto
// il riquadro logo "RACING DYNASTY" (che finisce a y≈706 su 941), sullo sfondo colorato a righe
// diagonali — confini misurati sui pixel reali. Stessa larghezza del riquadro logo sopra, per
// restare allineato, dimensione aumentata rispetto al primo tentativo su richiesta di Gio.
// V0.9.9.211: posizione ricalcolata su misure EMPIRICHE dirette (non solo teoriche) — lo spazio
// verticale reale tra il fondo del riquadro logo (y=706) e l'inizio dell'icona FUORISCALA (che ha
// dimensione fissa in pixel, quindi la sua posizione normalizzata varia leggermente con la scala)
// e' piu' stretto del previsto. Larghezza ridotta per stare comodo nello spazio vero disponibile,
// senza toccare ne' il riquadro sopra ne' l'icona sotto, verificato a più dimensioni finestra.
const STREAMER_GAME_LINK = { centerX:(85+522)/2/1672, centerY:0.849, widthPct:230/1672 };
const STREAMER_FRAME_RATIO = 1672/941;

function updateStreamerFrameLayout(){
  const container = document.getElementById('streamerFrame');
  const gameEl = document.getElementById('streamerGameSlot');
  const camEl = document.getElementById('streamerCamSlot');
  const twitchEl = document.getElementById('streamerTwitchTag');
  const frameImg = document.getElementById('streamerFrameImg');
  const logoEl = document.getElementById('streamerFuoriscalaLogo');
  const gameLinkEl = document.getElementById('streamerGameLinkBtn');
  if(!container || container.style.display==='none') return;
  const cw = container.clientWidth, ch = container.clientHeight;

  // V0.9.7.9.31: la cornice e' pensata per OBS in landscape largo — se la finestra diventa stretta
  // o piu' alta che larga (es. telefono in verticale, finestra ridimensionata a mano), forzare il
  // gioco dentro il riquadro fisso lo schiaccia male. Sotto questa soglia passiamo a un layout
  // "compatto": cornice decorativa nascosta, il gioco riprende tutto lo schermo e si comporta come
  // in modalita' normale (stesso adattamento fluido).
  const isCompact = cw < 760 || cw < ch;
  if(isCompact){
    if(frameImg) frameImg.style.display = 'none';
    if(camEl) camEl.style.display = 'none';
    if(twitchEl) twitchEl.style.display = 'none';
    if(logoEl) logoEl.style.display = 'none';
    if(gameLinkEl) gameLinkEl.style.display = 'none';
    if(gameEl){
      gameEl.style.left = '0px'; gameEl.style.top = '0px';
      gameEl.style.width = cw + 'px'; gameEl.style.height = ch + 'px';
      gameEl.style.borderRadius = '0';
    }
    return;
  }
  if(frameImg) frameImg.style.display = '';
  if(camEl) camEl.style.display = '';
  if(twitchEl) twitchEl.style.display = '';
  if(logoEl) logoEl.style.display = '';
  if(gameLinkEl) gameLinkEl.style.display = '';
  if(gameEl) gameEl.style.borderRadius = '';

  const containerRatio = cw/ch;
  let dispW, dispH, offX, offY;
  if(containerRatio > STREAMER_FRAME_RATIO){
    dispH = ch; dispW = ch*STREAMER_FRAME_RATIO; offX = (cw-dispW)/2; offY = 0;
  } else {
    dispW = cw; dispH = cw/STREAMER_FRAME_RATIO; offX = 0; offY = (ch-dispH)/2;
  }
  if(gameEl){
    gameEl.style.left = (offX + STREAMER_GAME_BOX.left*dispW) + 'px';
    gameEl.style.top = (offY + STREAMER_GAME_BOX.top*dispH) + 'px';
    gameEl.style.width = (STREAMER_GAME_BOX.width*dispW) + 'px';
    gameEl.style.height = (STREAMER_GAME_BOX.height*dispH) + 'px';
  }
  if(camEl){
    camEl.style.left = (offX + STREAMER_CAM_BOX.left*dispW) + 'px';
    camEl.style.top = (offY + STREAMER_CAM_BOX.top*dispH) + 'px';
    camEl.style.width = (STREAMER_CAM_BOX.width*dispW) + 'px';
    camEl.style.height = (STREAMER_CAM_BOX.height*dispH) + 'px';
  }
  if(twitchEl){
    twitchEl.style.left = (offX + STREAMER_TWITCH_TAG.centerX*dispW) + 'px';
    twitchEl.style.top = (offY + STREAMER_TWITCH_TAG.centerY*dispH) + 'px';
    // V0.9.9.169: BUG CORRETTO — segnalato da Gio: "l'etichetta nome streamer è troppo piccola".
    // Causa più profonda del previsto: il font restava FISSO in pixel (12px) indipendentemente da
    // quanto grande venisse mostrata la cornice — su un setup di streaming vero (OBS a piena
    // risoluzione, spesso molto più grande della finestra di sviluppo), il badge risultava
    // proporzionalmente minuscolo rispetto al resto della cornice, che invece scala correttamente
    // con la posizione. Ora il font/padding/icona scalano insieme alla cornice (riferimento: 1672px
    // di larghezza, la stessa usata per STREAMER_FRAME_RATIO), con anche una base più grande di
    // partenza (16px invece di 12px) per essere più leggibile anche alla dimensione "naturale".
    const scala = dispW / 1672;
    const nameLabel = document.getElementById('streamerNameLabel');
    if(nameLabel){ nameLabel.style.fontSize = (20*scala) + 'px'; nameLabel.style.maxWidth = (210*scala) + 'px'; }
    twitchEl.style.padding = `${5*scala}px ${14*scala}px ${5*scala}px ${9*scala}px`;
    twitchEl.style.gap = (7*scala) + 'px';
    const twitchIcon = twitchEl.querySelector('.streamer-twitch-icon');
    if(twitchIcon){ twitchIcon.style.width = (19*scala)+'px'; twitchIcon.style.height = (19*scala)+'px'; }
  }
  if(logoEl){
    logoEl.style.left = (offX + STREAMER_FUORISCALA_LOGO.centerX*dispW) + 'px';
    logoEl.style.top = (offY + STREAMER_FUORISCALA_LOGO.centerY*dispH) + 'px';
  }
  if(gameLinkEl){
    const scalaLink = dispW / 1672;
    gameLinkEl.style.left = (offX + STREAMER_GAME_LINK.centerX*dispW) + 'px';
    gameLinkEl.style.top = (offY + STREAMER_GAME_LINK.centerY*dispH) + 'px';
    gameLinkEl.style.width = (STREAMER_GAME_LINK.widthPct*dispW) + 'px';
    gameLinkEl.style.padding = `${6*scalaLink}px ${12*scalaLink}px`;
    if(!gameLinkEl.title) gameLinkEl.title = t('streamer_copy_link_hint'); // impostato una sola volta, il tooltip nativo del browser non serve rinfrescarlo ad ogni resize
  }
}
window.addEventListener('resize', updateStreamerFrameLayout);

function activateStreamerFrame(){
  if(isEmbeddedStreamerInstance()) return; // l'istanza dentro l'iframe non deve mai costruirsi una propria cornice
  const frame = document.getElementById('streamerFrame');
  const gameSlot = document.getElementById('streamerGameSlot');
  const appEl = document.getElementById('app');
  const nameLabel = document.getElementById('streamerNameLabel');
  if(!frame || !gameSlot || !appEl) return;
  // V0.9.7.9.34: rete di sicurezza — qualunque cosa stesse suonando sulla pagina esterna, la
  // fermiamo qui, a prescindere da quale percorso ci ha portato ad attivare la cornice. L'iframe
  // avra' la sua musica indipendente, non devono mai sovrapporsi.
  try{
    Object.values(__musicAudioEls).forEach(el=>{ if(el){ el.pause(); el.currentTime = 0; } });
    stopMusicFade();
    __musicCurrentZone = null;
  }catch(e){ /* ignorato */ }
  appEl.style.display = 'none'; // l'app esterna si mette in pausa visivamente, gira tutto nell'iframe
  frame.style.display = 'block';
  document.body.classList.add('streamer-mode-active');
  if(nameLabel) nameLabel.textContent = getStreamerName();
  let iframe = document.getElementById('streamerGameIframe');
  if(!iframe){
    iframe = document.createElement('iframe');
    iframe.id = 'streamerGameIframe';
    iframe.title = 'Racing Dynasty';
    // V0.9.7.9.36: senza questi permessi espliciti, i browser veri (Chrome in testa) possono
    // bloccare o comportarsi in modo imprevedibile quando uno script dentro l'iframe chiede il
    // fullscreen sul documento genitore — anche se e' la stessa origine.
    iframe.setAttribute('allow', 'fullscreen');
    iframe.allowFullscreen = true;
    // V0.9.7.9.32: l'iframe ha il suo viewport indipendente — dimensionandolo esattamente come il
    // riquadro Game Area, il gioco dentro "crede" di avere solo quello spazio e si dispone di
    // conseguenza (colonne che collassano, font che si adattano...), non solo si rimpicciolisce.
    iframe.src = 'index.html?embed=1';
    gameSlot.appendChild(iframe);
  }
  updateStreamerFrameLayout();
}
function deactivateStreamerFrame(){
  if(isEmbeddedStreamerInstance()) return;
  const frame = document.getElementById('streamerFrame');
  const appEl = document.getElementById('app');
  const iframe = document.getElementById('streamerGameIframe');
  if(!frame || !appEl) return;
  if(iframe) iframe.remove();
  appEl.style.display = '';
  frame.style.display = 'none';
  document.body.classList.remove('streamer-mode-active');
}
function syncStreamerFrameState(){
  if(isStreamerModeOn()) activateStreamerFrame();
  else deactivateStreamerFrame();
}
