// V0.9.9.83: DAILY SEASON — quanti tentativi ha già fatto oggi questo utente, per il controllo
// gratuito (1 sola volta) / premium (illimitato).
async function countDailyPlaysToday(){
  if(!currentUser || !supabaseClient) return 0;
  try{
    const { count, error } = await supabaseClient.from('daily_season_results')
      .select('id', { count:'exact', head:true })
      .eq('user_id', currentUser.id).eq('daily_date', todayDateStringUTC());
    if(error){ console.warn('Controllo tentativi Daily non riuscito:', error.message); return 0; }
    return count || 0;
  }catch(e){ console.warn('Controllo tentativi Daily non riuscito:', e); return 0; }
}
// V0.9.9.110: DAILY SEASON — max 3 tentativi al giorno per i premium (i non-premium restano a 1
// come sempre). Solo l'ULTIMO tentativo conta in classifica: iniziando uno nuovo, il precedente
// viene eliminato per sempre dal database, non solo nascosto — non e' possibile tornare indietro.
async function deleteDailyResultsForToday(){
  if(!currentUser || !supabaseClient) return false;
  try{
    const { error } = await supabaseClient.from('daily_season_results')
      .delete().eq('user_id', currentUser.id).eq('daily_date', todayDateStringUTC());
    if(error){ console.warn('Eliminazione risultato Daily precedente non riuscita:', error.message); return false; }
    return true;
  }catch(e){ console.warn('Eliminazione risultato Daily precedente non riuscita:', e); return false; }
}
// il MIGLIOR risultato di oggi di questo utente, con la sua posizione vera nella classifica del
// giorno (serve per colorare le 4 fasce trofeo oro/grigio) — usa la vista SQL gia' ordinata con lo
// spareggio corretto (punti -> budget -> componenti -> reroll -> chi ha finito prima).
async function loadDailyBestResultToday(){
  if(!currentUser || !supabaseClient){ dailyBestResultCache = null; return null; }
  try{
    const today = todayDateStringUTC();
    // V0.9.9.205: D7 (audit tecnico) — invece di scaricare l'INTERA classifica per poi trovare la
    // mia riga con indexOf() (costo che cresce con ogni nuovo giocatore, e "posizione non trovata"
    // se mai un limite di risposta tagliasse i risultati), chiediamo solo la MIA riga, poi due
    // conteggi separati e leggeri: quanti hanno un punteggio più alto di me, e quanti in totale.
    // Nessun cambiamento nel risultato finale mostrato al giocatore, solo nel modo di calcolarlo.
    const { data: mioArr, error: mioError } = await supabaseClient.from('daily_leaderboard_view')
      .select('user_id, points, budget_saved, components_sum, rerolls_left, completed_at, won_constructor, won_driver, driver_position, constructor_position, gap_from_rival, initial_rating, platinum_parts, attempt_number, final_score')
      .eq('daily_date', today).eq('user_id', currentUser.id).limit(1);
    if(!mioError && mioArr && mioArr.length>0 && mioArr[0].final_score!=null){
      const mio = mioArr[0];
      const { count: piuAlti } = await supabaseClient.from('daily_leaderboard_view')
        .select('user_id', { count:'exact', head:true })
        .eq('daily_date', today).gt('final_score', mio.final_score);
      const { count: totale } = await supabaseClient.from('daily_leaderboard_view')
        .select('user_id', { count:'exact', head:true })
        .eq('daily_date', today);
      dailyBestResultCache = { daily_date: today, rank: (piuAlti||0)+1, total: totale||1, ...mio };
      return dailyBestResultCache;
    }
    // ripiego: vista vecchia senza final_score (SQL non ancora eseguito) — percorso invariato,
    // usato solo se il tentativo efficiente sopra non trova un final_score valido
    console.warn('Lettura Daily col nuovo punteggio non riuscita o incompleta, riprovo con quello vecchio.');
    const retry = await supabaseClient.from('daily_leaderboard_view')
      .select('user_id, points, budget_saved, components_sum, rerolls_left, completed_at')
      .eq('daily_date', today)
      .order('points', { ascending:false }).order('budget_saved', { ascending:false })
      .order('components_sum', { ascending:false }).order('rerolls_left', { ascending:false })
      .order('completed_at', { ascending:true });
    const data = retry.data, error = retry.error;
    if(error || !data){ dailyBestResultCache = null; return null; }
    const mio = data.find(r=>r.user_id===currentUser.id);
    if(!mio){ dailyBestResultCache = null; return null; }
    const rank = data.indexOf(mio) + 1;
    dailyBestResultCache = { daily_date: today, rank, total: data.length, ...mio };
    return dailyBestResultCache;
  }catch(e){ console.warn('Caricamento risultato Daily non riuscito:', e); dailyBestResultCache = null; return null; }
}
const DAILY_MAX_PREMIUM_ATTEMPTS = 3;
async function enterDailySeasonFlow(){
  if(!isDailySeasonUnlocked()) return; // rete di sicurezza, la carta bloccata non dovrebbe nemmeno arrivare qui
  if(!currentUser){
    gameConfirm(t('daily_need_login_desc'), ()=>{ signInWithGoogle(); }, t('daily_need_login_title'));
    return;
  }
  if(dailyNicknameCache === undefined){
    await loadDailyNickname();
  }
  if(!dailyNicknameCache){
    state.phase = 'daily-nickname-setup';
    render();
    return;
  }
  const playsToday = await countDailyPlaysToday();
  if(playsToday >= 1 && !isPremiumUser){
    gameConfirm(t('daily_already_played_desc'), ()=>{}, t('daily_already_played_title'), ()=>{ startPremiumCheckout(); }, { yes:t('daily_come_back_tomorrow_btn'), no:t('daily_go_premium_btn') });
    return;
  }
  if(isPremiumUser && playsToday >= DAILY_MAX_PREMIUM_ATTEMPTS){
    gameConfirm(t('daily_max_attempts_desc'), ()=>{}, t('daily_max_attempts_title'));
    return;
  }
  if(isPremiumUser && playsToday >= 1){
    // 2° o 3° tentativo: serve conferma esplicita, il precedente viene eliminato per sempre e non
    // si può tornare indietro — come concordato con Gio.
    gameConfirm(t('daily_confirm_new_attempt_desc'), async ()=>{
      const cancellazioneRiuscita = await deleteDailyResultsForToday();
      if(!cancellazioneRiuscita){
        gameConfirm(t('daily_delete_failed'), ()=>{}, t('daily_confirm_new_attempt_title'));
        return;
      }
      startDailySeasonRun(undefined, playsToday + 1);
    }, t('daily_confirm_new_attempt_title'));
    return;
  }
  startDailySeasonRun(undefined, 1);
}
// V0.9.9.85: calcola SOLO quanti GP ha la Daily di oggi, senza avviarla davvero — serve per farlo
// vedere prima di entrare, cosi' il giocatore sa se ha tempo per finirla, come richiesto da Gio.
// V0.9.9.88: DAILY SEASON — reroll del giorno. Mai piu' di 7, a volte anche 0, ma sempre un numero
// diverso da quelli usati dalle difficoltà normali (facile:9 medio:6 difficile:3 hardcore:0) — 0
// resta comunque possibile perché richiesto esplicitamente da Gio, escludiamo solo 3 e 6 (gli altri
// valori "presi" da una difficoltà specifica all'interno del range 0-7). Stessa probabilità per
// ognuno, e mai lo stesso valore del giorno prima — VERO, non approssimato: ogni giorno esclude il
// valore VERO di ieri (calcolato ricorsivamente all'indietro fino a una data base fissa), non un
// suo calcolo indipendente che potrebbe divergere da quanto mostrato davvero ieri.
const DAILY_REROLL_POOL = [0,1,2,4,5,7];
const DAILY_REROLL_EPOCH = '2025-01-01'; // caso base della ricorsione: prima di questa data nessun vincolo
function dailyRerollValueForDate(dateStr, excludeValue){
  enterDailyRandomMode(dateStr+'-reroll'); // stream separato, non condiviso con circuiti/lunghezza
  let pool = DAILY_REROLL_POOL;
  if(excludeValue!==undefined && excludeValue!==null) pool = pool.filter(v=>v!==excludeValue);
  const val = pool[Math.floor(rnd()*pool.length)];
  exitDailyRandomMode();
  return val;
}
function previousDailyDateString(dateStr){
  const d = new Date(dateStr+'T00:00:00Z');
  d.setUTCDate(d.getUTCDate()-1);
  return d.toISOString().slice(0,10);
}
const __dailyRerollMemo = {};
function todaysDailyRerollCount(dateStr){
  dateStr = dateStr || todayDateStringUTC();
  if(__dailyRerollMemo[dateStr]!==undefined) return __dailyRerollMemo[dateStr];
  if(dateStr <= DAILY_REROLL_EPOCH){
    const val = dailyRerollValueForDate(dateStr);
    __dailyRerollMemo[dateStr] = val;
    return val;
  }
  const yesterdayTrueValue = todaysDailyRerollCount(previousDailyDateString(dateStr)); // ricorsione vera
  const val = dailyRerollValueForDate(dateStr, yesterdayTrueValue);
  __dailyRerollMemo[dateStr] = val;
  return val;
}

// V0.9.9.104: DAILY SEASON — 50 bot generati in modo deterministico per popolare la classifica fin
// da subito, richiesto da Gio. Stesso giorno = stessi bot per tutti (nessuna differenza tra
// dispositivi/giocatori), e compaiono gradualmente nell'arco delle 24h invece che tutti insieme a
// mezzanotte — cosi' la classifica sembra viva, non un elenco statico sparato tutto insieme.
const DAILY_BOT_COUNT = 50;
const DAILY_BOT_NICKNAMES = [
  'RossoVeloce','SprintKing','ApexHunter','PitLaneGhost','TurboNaz','DriftMaster','GripZone','RedlineRacer',
  'FastLap99','CircuitoBlu','VelocitaPura','NitroWolf','SlipstreamX','PoleSitter','ChequeredFlag','BoxBoxGo',
  'AeroDynamix','MidfieldHero','TrackDemon','RubberBurn','FormulaFox','GearJammer','CamberKing','DownforceDan',
  'PaddockPro','RaceCraft','OvertakeOwl','TyreWhisperer','FuelSaverX','SafetyCarFan','QualiKing','LastCorner',
  'SectorThree','DRSZone','KerbHopper','WingCommander','BrakeLaterX','ThrottleFull','CleanAirRacer','DirtyAirDodge',
  'PitCrewChief','StrategyMind','UndercutKing','OvercutQueen','GridWalker','FormationLap','SafetyFirst','RiskyMove',
  'ChampionChase','TitleHunter'
];
const DAILY_BOT_FLAGS = ['🇮🇹','🇬🇧','🇩🇪','🇫🇷','🇪🇸','🇳🇱','🇧🇪','🇦🇹','🇧🇷','🇦🇺','🇨🇦','🇯🇵','🇵🇹','🇫🇮','🇸🇪','🇩🇰','🇺🇸','🇲🇽','🇨🇭','🇵🇱'];
function generateDailyBots(dateStr){
  dateStr = dateStr || todayDateStringUTC();
  enterDailyRandomMode(dateStr+'-bots'); // stream separato, non condiviso col resto della Daily
  const bots = [];
  for(let i=0; i<DAILY_BOT_COUNT; i++){
    // distribuzione a livelli: 5 elite, 15 forti, 20 medi, 10 deboli — una classifica credibile,
    // non tutti allo stesso livello ne' tutti fortissimi (scoraggerebbe, non ispirerebbe)
    let livello;
    if(i < 5) livello = 'elite';
    else if(i < 20) livello = 'forte';
    else if(i < 40) livello = 'medio';
    else livello = 'debole';

    const range = {
      elite:  { punti:[190,255], driverPos:[1,3],  ctorPos:[1,2],  budget:[20,45], ratingFin:[420,480], ratingIni:[300,380], platino:[3,5] },
      forte:  { punti:[130,190], driverPos:[3,8],  ctorPos:[2,4],  budget:[10,28], ratingFin:[370,430], ratingIni:[280,360], platino:[1,3] },
      medio:  { punti:[70,130],  driverPos:[7,14], ctorPos:[4,7],  budget:[3,18],  ratingFin:[320,380], ratingIni:[260,340], platino:[0,2] },
      debole: { punti:[10,70],   driverPos:[13,20],ctorPos:[6,10], budget:[0,10],  ratingFin:[270,330], ratingIni:[240,320], platino:[0,1] },
    }[livello];
    const ri = (range2)=> range2[0] + Math.floor(rnd()*(range2[1]-range2[0]+1));
    const punti = ri(range.punti);
    const ratingFinale = ri(range.ratingFin);
    const ratingIniziale = Math.min(ratingFinale-10, ri(range.ratingIni));
    const gap = -30 + Math.floor(rnd()*61); // gap dal rivale: puo' essere sia positivo che negativo, indipendente dal livello

    bots.push({
      isBot: true,
      user_id: `bot-${dateStr}-${i}`,
      nickname: DAILY_BOT_NICKNAMES[i % DAILY_BOT_NICKNAMES.length] + (i>=DAILY_BOT_NICKNAMES.length ? (Math.floor(i/DAILY_BOT_NICKNAMES.length)+1) : ''),
      flag_code: DAILY_BOT_FLAGS[Math.floor(rnd()*DAILY_BOT_FLAGS.length)],
      points: punti,
      budget_saved: ri(range.budget),
      components_sum: ratingFinale,
      driver_position: ri(range.driverPos),
      constructor_position: ri(range.ctorPos),
      gap_from_rival: gap,
      initial_rating: ratingIniziale,
      platinum_parts: ri(range.platino),
      rerolls_left: Math.floor(rnd()*8),
      completed_at: dateStr+'T12:00:00Z',
      // orario di comparsa nell'arco delle 24h UTC di quel giorno — 0 = mezzanotte, 24 = fine giornata
      revealHourUTC: rnd()*24,
    });
  }
  exitDailyRandomMode();
  return bots;
}
// Stessa IDENTICA formula della vista SQL daily_leaderboard_view — necessaria qui perche' i bot
// non passano mai dal database, ma devono ordinarsi in classifica con lo stesso criterio esatto.
// V0.9.9.107: DAILY SEASON — punteggio ora su scala 0-10000 (10000 = run assolutamente perfetta),
// richiesto da Gio. 473 = massimo punti teorico (11 gare, entrambi i piloti sempre 1°-2° ogni gara,
// 25+18=43 punti a gara). I pesi sono calibrati mate maticamente: ogni punto vero vale ~21.1 sulla
// scala, il fattore secondario (tutti e 6 gli altri elementi insieme) puo' valere al massimo 20 —
// quindi anche UN SOLO punto di differenza vince sempre su qualunque combinazione degli altri 6
// fattori, la garanzia "chi fa più punti è sempre davanti" resta vera al 100% anche arrotondata.
const DAILY_SCORE_MAX = 10000;
const DAILY_SCORE_POINTS_MAX = 473;
const DAILY_SCORE_SECONDARY_MAX = 20;
function computeDailyFinalScore(r){
  const driverScore = Math.max(0, (21 - (r.driver_position ?? 20)) / 20 * 100);
  const ctorScore = Math.max(0, (11 - (r.constructor_position ?? 10)) / 10 * 100);
  const ratingScore = Math.min(100, (r.components_sum ?? 0) / 500 * 100);
  const gapScore = Math.max(0, Math.min(100, 50 + (r.gap_from_rival ?? 0) / 2));
  const budgetScore = Math.min(100, (r.budget_saved ?? 0) / 60 * 100);
  const platinoScore = (r.platinum_parts ?? 0) / 5 * 100;
  const ratingIniScore = Math.min(100, (r.initial_rating ?? 0) / 500 * 100);
  const secondario0a100 = 0.19*driverScore + 0.19*ctorScore + 0.19*ratingScore + 0.16*gapScore
    + 0.11*budgetScore + 0.11*platinoScore + 0.05*ratingIniScore;
  const puntiComponente = Math.min(1, (r.points ?? 0) / DAILY_SCORE_POINTS_MAX) * (DAILY_SCORE_MAX - DAILY_SCORE_SECONDARY_MAX);
  const secondarioComponente = (secondario0a100/100) * DAILY_SCORE_SECONDARY_MAX;
  // V0.9.9.110: leggera penalità per numero di tentativo (max 3 per i premium) — -1% per ogni
  // tentativo dopo il primo, così non conviene "spammare" tentativi senza conseguenze, ma la
  // differenza resta piccola (concordato con Gio).
  const numeroTentativo = r.attempt_number ?? 1;
  const fattorePenalita = 1 - Math.max(0, numeroTentativo-1) * 0.01;
  return Math.round((puntiComponente + secondarioComponente) * fattorePenalita);
}
// meccanismo che li fa apparire gradualmente nel corso della giornata invece che tutti insieme.
function visibleDailyBotsForDate(dateStr){
  const bots = generateDailyBots(dateStr);
  const oggi = todayDateStringUTC();
  if(dateStr < oggi) return bots; // giorno gia' passato: sono comparsi tutti, la giornata e' finita
  if(dateStr > oggi) return []; // giorno futuro: nessuno ancora
  const now = new Date();
  const oreTrascorseOggi = now.getUTCHours() + now.getUTCMinutes()/60 + now.getUTCSeconds()/3600;
  return bots.filter(b => b.revealHourUTC <= oreTrascorseOggi);
}
function todaysDailySeasonLength(dateStr){
  dateStr = dateStr || todayDateStringUTC();
  enterDailyRandomMode(dateStr);
  const seasonLength = 7 + Math.floor(rnd()*5); // stesso identico calcolo di startDailySeasonRun
  exitDailyRandomMode();
  return seasonLength;
}
function startDailySeasonRun(dateStr, attemptNumber){
  dateStr = dateStr || todayDateStringUTC();
  deleteDailyGameSave(); // V0.9.9.132: mai lasciare in giro il salvataggio di un tentativo precedente
  enterDailyRandomMode(dateStr);
  const seasonLength = 7 + Math.floor(rnd()*5); // 7-11 inclusi
  newRun('medio', 10, true, true); // consuma la sua parte di sequenza per circuiti/IA, sovrascritti subito dopo
  const dailyCircuits = DATA.circuiti.slice().sort(()=>rnd()-0.5).slice(0,seasonLength)
    .map(c=> ({ ...c, giri: computeRaceLaps(c) }));
  state.calendar = dailyCircuits;
  state.seasonLength = seasonLength;
  state.rerollsLeft = todaysDailyRerollCount(dateStr); // stream separato, sicuro chiamarlo qui
  state.isDailySeason = true;
  state.dailySeasonDate = dateStr;
  // V0.9.9.201: impostato QUI, DOPO newRun() — prima veniva impostato dal chiamante PRIMA di questa
  // funzione, ma newRun() riassegna interamente "state" da zero, cancellando qualunque valore
  // impostato in precedenza. Il risultato era che ogni tentativo (anche il 2°/3° Premium) veniva
  // sempre salvato come "tentativo 1", vanificando la penalità prevista per i tentativi successivi.
  state.dailySeasonAttemptNumber = attemptNumber || 1;
  exitDailyRandomMode(); // dal draft in poi si torna alla vera casualita' — vedi nota di design
  state.phase = 'naming'; // stesso punto di ingresso della run normale dopo newRun()
  render();
}
function startTutorialRun(){
  // V0.9.9.71: FIX robusto — invece di ricostruire lo state a mano (rischio di dimenticare campi,
  // gia' successo 2 volte con crash a fine gara), chiamiamo la vera newRun() per avere uno state
  // GARANTITO completo e corretto, poi sovrascriviamo solo i campi specifici del tutorial sopra.
  newRun('facile', 10, true, true);

  const tutorialCircuits = DATA.circuiti.slice(0,3).map(c=> ({ ...c, giri: computeRaceLaps(c) }));
  const aiTeamsRaw = DATA.scuderie.slice(0,9);
  const aiTeams = buildAIGrid(aiTeamsRaw, new Set(['DRV-249']), 'facile'); // teniamo fuori l'id di THE GOAT dal pool IA
  aiTeams.forEach(t=>{ t.virtualSponsor = SPONSOR_NAMES[0]; });

  state.phase = 'tutorial-intro';
  state.isTutorialRun = true; // controllato da achievement/token/museo/salvataggio per non scrivere nessun progresso vero
  state.seasonLength = 3;
  state.midSeasonSwapDone = true; // niente cambio pilota a meta' stagione nel tutorial, non serve
  state.calendar = tutorialCircuits;
  state.aiTeams = aiTeams;
  state.team = { pilotMain:null, pilotSecond:null, motore:null, telaio:null, aero:null, gomme:null, stratega:null, customName:TUTORIAL_TEAM_NAME, nation:'Italia' };
  state.usedIds = new Set(['DRV-249']);
  state.tutorialDraftStep = 0; // avanza attraverso le scelte guidate: motore, PILOTA (qui compare THE GOAT), telaio, aero, gomme, team principal, secondo pilota
  state.tutorialElioMsg = null; // messaggio di rifiuto mostrato quando si sceglie l'opzione sbagliata
  state.tutorialGoatFound = false; // finche' e' false, si parla con la voce fredda dell'Ingegnere — poi prende il posto Elio
  state.tutorialGoatRerollTarget = 2; // V0.9.9.74: THE GOAT compare garantito dopo ESATTAMENTE 2 reroll, come richiesto da Gio
  state.tutorialRerollCount = 0;
  state.tutorialWeakCategories = ['gomme','stratega']; // V0.9.9.74: 2 categorie lasciate deliberatamente sotto 85, da migliorare in Pit Lane

  // le classifiche delle 9 scuderie IA tutorial (diverse da quelle scelte da newRun())
  state.driverStandings = {}; state.constructorStandings = {};
  aiTeams.forEach(t=>{
    state.constructorStandings[t.id] = { teamId:t.id, nome:t.nome, isPlayerTeam:false, points:0 };
    t.drivers.forEach((d,slot)=>{
      const slotKey = t.id+'-'+slot;
      state.driverStandings[slotKey] = {
        slotKey, teamId:t.id, teamNome:t.nome, driverId:d.id, nome:d.nome, naz:d.naz, carNumber:null,
        isPlayerTeam:false, isFormer:false, points:0, wins:0, podiums:0, dnfs:0
      };
    });
  });
  render();
}
// V0.9.9.69: componente di dialogo di Elio — riusa il ritratto di THE GOAT gia' esistente nella
// Guida, cosi' non serve un nuovo asset. Tono: fenomeno alla guida, un po' altezzoso, sa di essere
// il migliore e non fa nulla per nasconderlo — ma alla fine ti sta davvero insegnando qualcosa.
// V0.9.9.70: la voce fredda e noiosa dell'Ingegnere del tutorial — usata SOLO prima che il
// giocatore trovi THE GOAT nel draft. Deliberatamente asettica: nessun ritratto, tono da manuale,
// in contrasto netto con Elio che arriva subito dopo con tutta la sua personalita'.
function ingegnereSaysHTML(text){
  return `
  <div class="elio-says ingegnere-says">
    <div class="ingegnere-says-icon">⚙</div>
    <div class="elio-says-bubble">
      <div class="elio-says-name">INGEGNERE DI PISTA</div>
      <div class="elio-says-text">${text}</div>
    </div>
  </div>`;
}
function elioSaysHTML(text, opts){
  opts = opts || {};
  const cls = opts.rejection ? 'elio-says elio-says-rejection' : 'elio-says';
  return `
  <div class="${cls}">
    <img class="elio-says-portrait" src="${GOAT_GUIDE_IMG_SRC}" alt="Elio">
    <div class="elio-says-bubble">
      <div class="elio-says-name">ELIO</div>
      <div class="elio-says-text">${text}</div>
    </div>
  </div>`;
}
// V0.9.9.69: le 6 tappe della scelta guidata (sembra libera, ma solo il valore più alto delle 3
// "passa" davvero) — un pool per categoria, sempre lo stesso ordine, cosi' il tutorial resta
// identico ad ogni replay come richiesto.
const TUTORIAL_DRAFT_STEPS = [
  { key:'motore', label:'Motore', pool:()=>DATA.motori },
  { key:'pilotMain', label:'Pilota Principale', pool:()=>DATA.piloti, isGoatStep:true },
  { key:'telaio', label:'Telaio', pool:()=>DATA.telai },
  { key:'aero', label:'Aerodinamica', pool:()=>DATA.aero },
  { key:'gomme', label:'Gomme', pool:()=>DATA.gomme },
  { key:'stratega', label:'Team Principal', pool:()=>DATA.strategi },
  { key:'pilotSecond', label:'Secondo Pilota', pool:()=>DATA.piloti.filter(p=>p.nome!=='THE GOAT') },
];
function tutorialDraftOptions(stepIdx){
  const step = TUTORIAL_DRAFT_STEPS[stepIdx];
  // V0.9.9.70: il passo pilota principale mostra SEMPRE THE GOAT come una delle 3 opzioni (quella
  // corretta) — non e' un pool casuale come gli altri, e' proprio quel momento a farlo comparire.
  if(step.isGoatStep){
    const goat = DATA.piloti.find(p=>p.nome==='THE GOAT');
    const others = DATA.piloti.filter(p=>p.nome!=='THE GOAT').sort((a,b)=> a.nome.localeCompare(b.nome));
    const byRating = others.slice().sort((a,b)=> a.rating-b.rating);
    const low = byRating[Math.floor(byRating.length*0.25)];
    const mid = byRating[Math.floor(byRating.length*0.55)];
    return { step, options: [low, mid, goat], correctId: goat.id };
  }
  const sorted = step.pool().slice().sort((a,b)=> a.nome.localeCompare(b.nome)); // ordine stabile
  const byRating = sorted.slice().sort((a,b)=> a.rating-b.rating);
  const low = byRating[Math.floor(byRating.length*0.25)];
  const mid = byRating[Math.floor(byRating.length*0.55)];
  const high = byRating[byRating.length-1];
  return { step, options: [low, mid, high], correctId: high.id };
}
function newRun(difficulty, seasonLength, aiutoInCoda, riflessiPartenza){
  difficulty = DIFFICULTY_REROLLS.hasOwnProperty(difficulty) ? difficulty : 'medio';
  seasonLength = (seasonLength===20) ? 20 : 10;
  aiutoInCoda = aiutoInCoda !== false; // default ON se non specificato
  riflessiPartenza = riflessiPartenza !== false; // default ON se non specificato
  const usedIds = new Set();
  const shuffledCircuits = DATA.circuiti.slice().sort(()=>rnd()-0.5).slice(0,seasonLength)
    .map(c=> ({ ...c, giri: computeRaceLaps(c) })); // V0.5.1: giri reali dalla lunghezza del circuito
  const aiTeamsRaw = DATA.scuderie.slice().sort(()=>rnd()-0.5).slice(0,9);
  const aiTeams = buildAIGrid(aiTeamsRaw, usedIds, difficulty); // riserva anche i 18 id piloti IA in usedIds
  // V0.9.9.8: sponsor virtuale invisibile per ogni squadra IA — stesso pool di effetti del
  // giocatore, cosi' anche gli avversari sviluppano in modo credibile e vario, non tutti uguali.
  // Mai mostrato in nessuna schermata: e' solo il "carattere" nascosto della squadra per la stagione.
  aiTeams.forEach(t=>{ t.virtualSponsor = SPONSOR_NAMES[Math.floor(rnd()*SPONSOR_NAMES.length)]; });
  const diffParams = DIFFICULTY_PARAMS[difficulty] || DIFFICULTY_PARAMS.medio;

  state = {
    phase:'title',
    difficulty,
    seasonLength,               // V0.7.5: 10 (Veloce) o 20 (Completa)
    aiutoInCoda,                 // V0.9.9.45: se attivo, il prezzo scouting scala con la posizione in classifica (1x-5x). Se disattivo, sempre 5x.
    riflessiPartenza,             // V0.9.9.68: se attivo, partenza coi paddle veri; se disattivo, partenza automatica (come il vecchio tasto Salta)
    midSeasonSwapDone: false,   // V0.7.5: la finestra di cambio pilota a meta' stagione completa e' unica
    rerollsLeft: DIFFICULTY_REROLLS[difficulty],
    rerollsTotal: DIFFICULTY_REROLLS[difficulty],
    budget: Math.round(START_BUDGET * diffParams.budgetMult * 10)/10,
    raceIndex: 0,
    calendar: shuffledCircuits,
    aiTeams: aiTeams,
    team: { pilotMain:null, pilotSecond:null, motore:null, telaio:null, aero:null, gomme:null, stratega:null, customName:null, nation:'Italia' },
    // V0.9.4.2.2: draft riscritto — ogni turno mostra un'offerta per ciascuna categoria ancora libera
    // (il Pilota resta aperto finche' non se ne scelgono 2), il giocatore ne prende UNA sola per turno.
    draftOpenCategories: ['motore','telaio','aero','gomme','stratega'],
    draftPilotsChosen: [],
    draftTurnOffers: {},
    draftPicksDone: 0,
    usedIds,
    grid: [],                 // V0.3: 20 slot di gara (2 per scuderia)
    driverStandings: {},      // V0.3: classifica piloti, chiave = slotKey (V0.6.1: puo' contenere anche record EX)
    exCounter: 0,              // V0.6.1: contatore per generare chiavi uniche ai piloti sostituiti
    constructorStandings: {}, // V0.3: classifica costruttori, chiave = teamId
    resultsByRace: [], // history
    log: [],
    lastRaceResult: null,
    pendingPitlane: null,
    storyEvents: [],  // V0.9: storia della stagione
    rivals: [], rivalHistory: [], pendingRivalNotice: null,   // V0.9.2.1: scuderie rivali
    recentlyDroppedRivals: [], rivalCooldownUntilRace: 0,        // V0.9.3.1: evita rimbalzi e notifiche a raffica
    playerInvestedLastRace: false,                                // V0.9.3.2: crescita rivale al tuo ritmo
    seasonTrophiesWon: [], lastTrophyUnlock: null,                 // V0.9.4: sala trofei
    // V0.9.7: tracciamento per gli obiettivi legati al comportamento durante la stagione
    playerRaceWinsCount: 0, initialTeamRatingAtDraft: null,
    everUsedMaxRiskOnly: true, everSwappedPilot: false, everUsedScouting: false, upgradesPurchasedCount: 0,
    sponsor: null, sponsorOffers: null, pendingPostSponsorPhase: null, // V0.9.7.8.8: sistema sponsor
    // V0.9.7.9: tracciamento esteso per i 50 obiettivi
    everUsedScoutingOnComponent: false,       // scouting SOLO sui componenti (fedele-alla-linea-di-partenza)
    everUsedEpicOrHigher: false,               // con-quello-che-c-e: mai Epic/Legendary/Immortal in squadra
    everLedDriverStandingsP1: false,           // lavoro-di-squadra: mai stato P1 in classifica Piloti
    midSeasonSwappedCats: new Set(),           // rivoluzione-a-meta-stagione: quali sedili sono stati cambiati
    everFinishedOffPodium: false,              // costanza-chirurgica: sempre a podio in stagione Hardcore
    everLostLeadInFinalPhase: false,           // terrore-della-griglia: mai ripreso nell'ultima fase di gara
    goatMalusTriggeredThisSeason: false,       // infallibile: mai subito il malus di THE GOAT in stagione
  };

  // Le due classifiche permanenti nascono con le 9 scuderie IA e i loro 18 piloti;
  // gli slot del giocatore vengono aggiunti da buildGrid() al termine del draft.
  aiTeams.forEach(t=>{
    state.constructorStandings[t.id] = { teamId:t.id, nome:t.nome, isPlayerTeam:false, points:0 };
    t.drivers.forEach((d,slot)=>{
      const slotKey = t.id+'-'+slot;
      state.driverStandings[slotKey] = {
        slotKey, teamId:t.id, teamNome:t.nome, driverId:d.id, nome:d.nome, naz:d.naz, carNumber:null,
        isPlayerTeam:false, isFormer:false, points:0, wins:0, podiums:0, dnfs:0
      };
    });
  });

  render();
}

/* ---------------- draft flow ---------------- */
// V0.9.4.2.2: definizioni delle 5 categorie "componente" (il Pilota e' gestito a parte, resta aperto
// finche' non se ne scelgono 2 in totale, indipendentemente da quando capitano nei vari turni).
const DRAFT_CATEGORY_DEFS = {
  motore:   { pool:DATA.motori, role:'Power Unit' },
  telaio:   { pool:DATA.telai, role:'Chassis' },
  aero:     { pool:DATA.aero, role:'Aero' },
  gomme:    { pool:DATA.gomme, role:'Tyres' },
  stratega: { pool:DATA.strategi, role:'Team Principal' }
};
Object.defineProperty(DRAFT_CATEGORY_DEFS.motore, 'label', { get: ()=> t('comp_engine') });
Object.defineProperty(DRAFT_CATEGORY_DEFS.telaio, 'label', { get: ()=> t('comp_chassis') });
Object.defineProperty(DRAFT_CATEGORY_DEFS.aero, 'label', { get: ()=> t('cat_aero_pack') });
Object.defineProperty(DRAFT_CATEGORY_DEFS.gomme, 'label', { get: ()=> t('cat_tire_supplier') });
Object.defineProperty(DRAFT_CATEGORY_DEFS.stratega, 'label', { get: ()=> t('comp_strategist') });
const DRAFT_TOTAL_PICKS = 7; // 2 piloti + 5 componenti

// ============================================================
// V0.9.7.9.1 — CARRIERA PILOTA (punto 1/8): tiering scuderie + prestigio simulato
// Modalita' parallela a Carriera Scuderia, salvataggio e stato completamente separati.
// ============================================================

// 3 Serie da 10 scuderie ciascuna, divise per ratingbase (forza strutturale, non cambia in game).
// Il Kart e' una fascia FISSA: le scuderie li' non salgono mai come organizzazione, solo il
// pilota (il giocatore) puo' uscirne individualmente con un'offerta migliore.
function computeDriverCareerTiers(){
  const sorted = [...DATA.scuderie].sort((a,b)=> b.ratingbase - a.ratingbase);
  const tiers = {};
  sorted.forEach((s,i)=>{
    tiers[s.id] = i<10 ? 'elite' : (i<20 ? 'minore' : 'kart');
  });
  return tiers;
}

// Una "stagione finta": un punteggio per scuderia (forza base + variazione casuale, rappresenta
// un'annata piu' o meno fortunata), usato SOLO per costruire prestigio storico — non e' la
// simulazione gara-per-gara completa (troppo lenta e inutile per uno sfondo che il giocatore
// non guarda direttamente).
function simulateFakeSeasonStandings(teamIds){
  return teamIds.map(id=>{
    const s = DATA.scuderie.find(x=>x.id===id);
    const score = s.ratingbase + (rnd()-0.5)*30;
    return { id, score };
  }).sort((a,b)=> b.score-a.score);
}

// Prestigio iniziale: 3 stagioni finte simulate su TUTTE e 30 le scuderie insieme (indipendente
// dalla Serie attuale — anche una scuderia oggi in Kart puo' aver avuto un passato migliore).
// Punti prestigio per piazzamento: 1a posizione vale 30, ultima vale 1.
const DRIVER_CAREER_FAKE_SEASONS = 3;
function initTeamPrestige(){
  const prestige = {};
  DATA.scuderie.forEach(s=> prestige[s.id] = 0);
  for(let i=0;i<DRIVER_CAREER_FAKE_SEASONS;i++){
    const standings = simulateFakeSeasonStandings(DATA.scuderie.map(s=>s.id));
    standings.forEach((entry, pos)=>{ prestige[entry.id] += (30 - pos); });
  }
  return prestige;
}

// Punto d'ingresso: costruisce tiers + prestigio insieme, pronto per essere salvato nello stato
// di una nuova Carriera Pilota.
function initDriverCareerWorld(){
  return { tiers: computeDriverCareerTiers(), prestige: initTeamPrestige() };
}

// ============================================================
// V0.9.7.9.5 — CARRIERA PILOTA (punto 3/8): Hub + stagione giocabile
// Riusa quasi verbatim il motore di simulazione di Carriera Scuderia (simulateFullRace,
// renderPregara, renderRaceLiveInit, renderRaceResult) costruendo un oggetto 'state' compatibile
// — stessa forma (team/grid/aiTeams/calendar/driverStandings), dati diversi. Le due modalita'
// restano completamente separate nei salvataggi, ma condividono lo stesso motore di gara a runtime.
const DRIVER_CAREER_TIER_DRAWS = { kart:1, minore:2, elite:4 };

// Assegna il giocatore a UNA scuderia scelta a caso nella Serie indicata, genera il compagno di
// scuderia e i 5 componenti condivisi, scalati per forza in base al livello (stesso meccanismo
// "pesca N, scegli il migliore" gia' usato per le scuderie IA di Carriera Scuderia).
function assignDriverCareerTeam(tierName, usedIds){
  const teamIds = Object.keys(driverCareerState.world.tiers).filter(id=> driverCareerState.world.tiers[id]===tierName);
  const teamId = teamIds[Math.floor(rnd()*teamIds.length)];
  const teamData = DATA.scuderie.find(s=>s.id===teamId);
  const n = DRIVER_CAREER_TIER_DRAWS[tierName] || 2;

  const teammate = pickBestOfNDistinct(DATA.piloti.filter(p=>p.rating<100), n, usedIds);
  usedIds.add(teammate.id);

  const components = {
    motore: pickBestOfNDistinct(DATA.motori.filter(x=>x.rating<100), n, usedIds),
    telaio: pickBestOfNDistinct(DATA.telai.filter(x=>x.rating<100), n, usedIds),
    aero: pickBestOfNDistinct(DATA.aero.filter(x=>x.rating<100), n, usedIds),
    gomme: pickBestOfNDistinct(DATA.gomme.filter(x=>x.rating<100), n, usedIds),
    stratega: pickBestOfNDistinct(DATA.strategi.filter(x=>x.rating<100), n, usedIds),
  };
  return { teamId, teamData, teammate, components };
}

// Griglia di 20 slot: le 10 scuderie della Serie del giocatore, 2 piloti ciascuna — stessa forma
// dati di state.grid in Carriera Scuderia (buildAIGrid), ma scoped alla Serie invece che a un
// campione casuale di 9 scuderie su 30.
function buildDriverCareerGrid(tierName, playerAssignment, usedIds){
  const teamIds = Object.keys(driverCareerState.world.tiers).filter(id=> driverCareerState.world.tiers[id]===tierName);
  const n = DRIVER_CAREER_TIER_DRAWS[tierName] || 2;
  const aiTeams = teamIds.filter(id=>id!==playerAssignment.teamId).map(id=>{
    const teamData = DATA.scuderie.find(s=>s.id===id);
    const d1 = pickBestOfNDistinct(DATA.piloti.filter(p=>p.rating<100), n, usedIds); usedIds.add(d1.id);
    const d2 = pickBestOfNDistinct(DATA.piloti.filter(p=>p.rating<100), n, usedIds); usedIds.add(d2.id);
    const components = {
      motore: pickBestOfNDistinct(DATA.motori.filter(x=>x.rating<100), n, usedIds),
      telaio: pickBestOfNDistinct(DATA.telai.filter(x=>x.rating<100), n, usedIds),
      aero: pickBestOfNDistinct(DATA.aero.filter(x=>x.rating<100), n, usedIds),
      gomme: pickBestOfNDistinct(DATA.gomme.filter(x=>x.rating<100), n, usedIds),
      stratega: pickBestOfNDistinct(DATA.strategi.filter(x=>x.rating<100), n, usedIds),
    };
    const t = { ...teamData, id, drivers:[d1,d2], components, tier: tierName };
    applyAITeamSynergyBonuses(t);
    return t;
  });

  const grid = [];
  let carNum = 1;
  grid.push({ slotKey:'PLAYER-1', teamId:'PLAYER', teamName:playerAssignment.teamData.nome, isPlayerTeam:true, role:'pilotMain', carNumber:carNum++ });
  grid.push({ slotKey:'PLAYER-2', teamId:'PLAYER', teamName:playerAssignment.teamData.nome, isPlayerTeam:true, role:'pilotSecond', carNumber:carNum++ });
  aiTeams.forEach(t=>{
    grid.push({ slotKey:t.id+'-1', teamId:t.id, teamName:t.nome, isPlayerTeam:false, role:0, carNumber:carNum++ });
    grid.push({ slotKey:t.id+'-2', teamId:t.id, teamName:t.nome, isPlayerTeam:false, role:1, carNumber:carNum++ });
  });
  return { grid, aiTeams };
}

// Costruisce lo state compatibile con Carriera Scuderia per una stagione di Carriera Pilota.
// Stagione fissa a 10 gare (formato Veloce) — piu' semplice per iniziare, si puo' rivedere.
const DRIVER_CAREER_SEASON_LENGTH = 10;
function startDriverCareerSeason(){
  const usedIds = new Set();
  const tierName = driverCareerState.currentTier || 'kart';
  const playerAssignment = assignDriverCareerTeam(tierName, usedIds);
  const { grid, aiTeams } = buildDriverCareerGrid(tierName, playerAssignment, usedIds);

  const shuffledCircuits = DATA.circuiti.slice().sort(()=>rnd()-0.5).slice(0,DRIVER_CAREER_SEASON_LENGTH)
    .map(c=> ({ ...c, giri: computeRaceLaps(c) }));

  driverCareerState.currentTeamId = playerAssignment.teamId;

  state = {
    phase: 'driver-hub',
    isDriverCareer: true, // V0.9.7.9.5: distingue questo state da una normale Carriera Scuderia
    difficulty: 'medio', // usato solo per DIFFICULTY_LABEL nella topbar, non incide sui rerolls (qui non ce ne sono)
    seasonLength: DRIVER_CAREER_SEASON_LENGTH,
    raceIndex: 0,
    calendar: shuffledCircuits,
    aiTeams,
    team: {
      pilotMain: driverCareerState.driver, pilotSecond: playerAssignment.teammate,
      motore: playerAssignment.components.motore, telaio: playerAssignment.components.telaio,
      aero: playerAssignment.components.aero, gomme: playerAssignment.components.gomme, stratega: playerAssignment.components.stratega,
      customName: playerAssignment.teamData.nome, nation: playerAssignment.teamData.paese,
    },
    grid,
    driverStandings: {}, exCounter: 0, constructorStandings: {},
    resultsByRace: [], log: [], lastRaceResult: null,
    rivals: [], rivalHistory: [], pendingRivalNotice: null, recentlyDroppedRivals: [], rivalCooldownUntilRace: 0,
    seasonTrophiesWon: [], lastTrophyUnlock: null, trophyUnlockDismissed: true,
    playerRaceWinsCount: 0, everFinishedOffPodium: false, everLostLeadInFinalPhase: false, goatMalusTriggeredThisSeason: false,
    everLedDriverStandingsP1: false, playerInvestedLastRace: false,
    sponsor: null, sponsorOffers: null, pendingPostSponsorPhase: null,
    budget: 0, pendingPitlane: null, pendingQualifying: null,
  };
  grid.forEach(slot=>{ state.driverStandings[slot.slotKey] = { points:0, wins:0, podiums:0, dnfs:0 }; });
  [...aiTeams.map(t=>t.id), 'PLAYER'].forEach(id=>{ state.constructorStandings[id] = { points:0 }; });

  render();
}

// ============================================================
// V0.9.7.9.7 — CARRIERA PILOTA (punto 4/8): fine stagione vera
// ============================================================

// Prestigio guadagnato in base al piazzamento finale e alle statistiche della stagione.
// Formula semplice, tarabile in futuro: posizione finale pesa di piu', vittorie e podi aggiungono.
function calcSeasonPrestige(finalPos, stats){
  return Math.round(Math.max(0, 21-finalPos)*2 + stats.wins*8 + stats.podiums*2);
}

// Il mondo si muove anche senza il giocatore: aggiungiamo una nuova "stagione finta" al prestigio
// di TUTTE e 30 le scuderie, poi promuoviamo/retrocediamo 2 scuderie tra Minore ed Elite in base al
// prestigio accumulato. Il Kart resta sempre fisso (nessuna scuderia sale da li' come organizzazione).
function evolveDriverCareerWorld(){
  const world = driverCareerState.world;
  const standings = simulateFakeSeasonStandings(DATA.scuderie.map(s=>s.id));
  standings.forEach((entry,pos)=>{ world.prestige[entry.id] += (30-pos); });

  const minoreIds = Object.keys(world.tiers).filter(id=>world.tiers[id]==='minore');
  const eliteIds = Object.keys(world.tiers).filter(id=>world.tiers[id]==='elite');
  const minoreSorted = minoreIds.slice().sort((a,b)=> world.prestige[b]-world.prestige[a]);
  const eliteSorted = eliteIds.slice().sort((a,b)=> world.prestige[a]-world.prestige[b]);

  const promossi = minoreSorted.slice(0,2);
  const retrocessi = eliteSorted.slice(0,2);
  promossi.forEach(id=> world.tiers[id]='elite');
  retrocessi.forEach(id=> world.tiers[id]='minore');

  return { promossi: promossi.map(id=>DATA.scuderie.find(s=>s.id===id).nome), retrocessi: retrocessi.map(id=>DATA.scuderie.find(s=>s.id===id).nome) };
}

const DRIVER_CAREER_RETIREMENT_AGE = 42;
function finalizeDriverCareerSeason(){
  const d = driverCareerState.driver;
  const arr = Object.values(state.driverStandings).slice().sort((a,b)=>b.points-a.points);
  const finalPos = arr.indexOf(state.driverStandings['PLAYER-1']) + 1;
  const stats = state.driverStandings['PLAYER-1'];
  const prestigeGained = calcSeasonPrestige(finalPos, stats);
  d.prestigio = (d.prestigio||0) + prestigeGained;
  d.eta += 1;

  const evolution = evolveDriverCareerWorld();
  // se la scuderia del giocatore e' stata coinvolta nel movimento, la Serie corrente si aggiorna di conseguenza
  driverCareerState.currentTier = driverCareerState.world.tiers[driverCareerState.currentTeamId];
  const retiring = d.eta >= DRIVER_CAREER_RETIREMENT_AGE;

  // V0.9.7.9.17: storico di carriera, stagione per stagione, per il riepilogo fine carriera
  if(!driverCareerState.careerHistory) driverCareerState.careerHistory = [];
  driverCareerState.careerHistory.push({
    age: d.eta-1, teamName: state.team.customName, tier: driverCareerState.currentTier,
    finalPos, points: stats.points, wins: stats.wins, podiums: stats.podiums,
  });
  if(!driverCareerState.careerTeams) driverCareerState.careerTeams = [];
  if(!driverCareerState.careerTeams.includes(state.team.customName)) driverCareerState.careerTeams.push(state.team.customName);
  driverCareerState.peakRating = Math.max(driverCareerState.peakRating||0, d.rating);
  driverCareerState.peakFama = Math.max(driverCareerState.peakFama||0, d.fama);
  driverCareerState.peakReputazione = Math.max(driverCareerState.peakReputazione||0, d.reputazione);
  driverCareerState.highestTierReached = ['kart','minore','elite'].indexOf(driverCareerState.currentTier) > ['kart','minore','elite'].indexOf(driverCareerState.highestTierReached||'kart') ? driverCareerState.currentTier : (driverCareerState.highestTierReached||'kart');

  driverCareerState.lastSeasonSummary = { finalPos, prestigeGained, stats: {...stats}, evolution, retiring, teamName: state.team.customName };
  state.phase = retiring ? 'driver-retirement' : 'driver-season-end';
  render();
}

// ============================================================
// V0.9.7.9.12 — CARRIERA PILOTA (punto 6/8): mercato piloti e contratti
// Documento design sezione 13: le squadre valutano il giocatore attraverso una combinazione di
// Rating, risultati, Reputazione, Fama — non un numero solo. Puoi essere scaricato se vai male.
// ============================================================
function evaluateDriverContractSituation(){
  const d = driverCareerState.driver;
  const currentTier = driverCareerState.currentTier;
  // punteggio di mercato: pesa soprattutto il Rating (la forza reale), poi Reputazione, poi Fama —
  // coerente col documento: "una squadra Elite non deve assumere automaticamente qualcuno solo
  // perche' famoso".
  const marketScore = Math.round(d.rating*0.5 + d.reputazione*0.3 + d.fama*0.2);

  const renewChance = Math.max(0.08, Math.min(0.95, 0.22 + (marketScore/100)*0.7));
  const renewed = rnd() < renewChance;

  const candidateTiers = [currentTier];
  if(currentTier==='kart' && marketScore>=52) candidateTiers.push('minore'); // rottura individuale dal Kart
  if(currentTier==='minore' && marketScore>=62) candidateTiers.push('elite');

  const numOffers = marketScore>=75 ? (rnd()<0.6?2:1) : marketScore>=45 ? (rnd()<0.5?1:0) : (rnd()<0.12?1:0);
  const offers = [];
  const usedTeamIds = new Set([driverCareerState.currentTeamId]);
  for(let i=0;i<numOffers;i++){
    const tier = candidateTiers[Math.floor(rnd()*candidateTiers.length)];
    const teamIds = Object.keys(driverCareerState.world.tiers).filter(id=>driverCareerState.world.tiers[id]===tier && !usedTeamIds.has(id));
    if(teamIds.length===0) continue;
    const teamId = teamIds[Math.floor(rnd()*teamIds.length)];
    usedTeamIds.add(teamId);
    offers.push({ teamId, tier, teamData: DATA.scuderie.find(s=>s.id===teamId) });
  }

  return { renewed, marketScore, offers, currentTier };
}

