// sceglie un bucket in base alle probabilita', tira lo shift esatto dentro il range del bucket,
// e ritorna ANCHE quale bucket e' uscito (indice), cosi' l'interfaccia puo' mostrarlo nel ballottaggio.
function pickDecisionOutcome(choiceKey){
  const buckets = DECISION_OUTCOME_BUCKETS[choiceKey] || [{ prob:1, label:'hold', min:0, max:0 }];
  const roll = rnd();
  let cum = 0, chosenIdx = buckets.length-1;
  for(let i=0;i<buckets.length;i++){ cum += buckets[i].prob; if(roll<cum){ chosenIdx=i; break; } }
  const b = buckets[chosenIdx];
  const span = b.max-b.min;
  const shift = span===0 ? b.min : b.min + Math.floor(rnd()*(span+1));
  return { shift, bucketIdx: chosenIdx, buckets };
}
function decisionShiftFn(choiceKey){
  switch(choiceKey){
    case 'box': return ()=> 1+Math.floor(rnd()*2);
    case 'stay': return ()=> (rnd()<0.5 ? -1 : 1);
    case 'restart': return ()=> (rnd()<0.45 ? -(1+Math.floor(rnd()*2)) : 2);
    case 'splitstrategy': return ()=> (rnd()<0.5 ? -1 : 1);
    case 'early': return ()=> (rnd()<0.6 ? -1 : 1);
    case 'late': return ()=> (rnd()<0.45 ? -1 : (rnd()<0.7?0:2));
    case 'aggressive': return ()=> (rnd()<0.55 ? -(1+Math.floor(rnd()*2)) : 1);
    case 'safe': return ()=> 0;
    case 'hold': return ()=> 0;
    case 'free': return ()=> (rnd()<0.5 ? -1 : (rnd()<0.75?0:2));
    case 'defend': return ()=> (rnd()<0.6 ? 0 : 2);
    case 'letpass': return ()=> 1;
    case 'push': return ()=> (rnd()<0.5 ? -1 : (rnd()<0.75?0:2));
    case 'nurse': return ()=> (rnd()<0.3 ? 1 : 0);
    default: return ()=> 0;
  }
}

// V0.9.9.21: quando una scelta darebbe posizioni ma sei gia' primo (o le toglierebbe ma sei gia'
// ultimo), quel vantaggio/svantaggio non deve sparire nel nulla — diventa un distacco reale in
// secondi, dato che ora abbiamo il tempo cumulato vero della simulazione.
const TIME_PER_CLAMPED_POSITION = 1.2;
// V0.9.9.55: pit stop VERO sotto Safety Car (non solo un esito narrativo scollegato) — costo reale
// in secondi (stessa formula del pit vero, 10-12s in base al Team Principal) propagato su tutte le
// fasi future, più azzeramento usura gomme come un pit stop vero. Proposta A+B discussa con Gio:
// prima "Entra ai box" durante la Safety Car era solo un esito di posizione casuale, senza nessun
// legame con la simulazione vera — ora sposta davvero le cose.
// V0.9.9.59: RISCRITTA — segnalato da Gio come bug serio: prima si limitava ad AGGIUNGERE il costo
// del pit sotto SC, senza annullare la sosta gia' programmata piu' avanti nella simulazione. Il
// giocatore si fermava DAVVERO due volte (una qui, una alla fase originale), pagando il costo due
// volte — "tutti gli eventi live che riguardano il pit stop mi sfanculiano la gara". Ora la sosta
// futura viene trovata e annullata per davvero (costo E reset gomme rimossi da dove sarebbe successa),
// prima di applicare il vero pit sotto SC al suo posto.
function cancelFuturePitStop(timeline, slotKey, tCurrent){
  let cancelPhase = null;
  for(let phase=tCurrent+1; phase<PHASES.length; phase++){
    if(timeline.pitByPhase[phase] && timeline.pitByPhase[phase].has(slotKey)){ cancelPhase = phase; break; }
  }
  if(cancelPhase===null) return; // nessuna sosta futura programmata da annullare (es. l'ha gia' fatta prima)
  timeline.pitByPhase[cancelPhase].delete(slotKey);

  // ricalcoliamo quanto costo era stato aggiunto in quella fase (stessa formula usata per applicarlo,
  // sapendo se ERA sotto Safety Car anche lei) e lo togliamo da tutte le fasi successive
  const comp = state.team;
  const pitSkillFrac = comp.stratega.pitstop/100;
  const wasUnderSC = cancelPhase===timeline.safetyCarPhase;
  const cancelledCost = wasUnderSC ? (12 - pitSkillFrac*2) : (24 - pitSkillFrac*2);
  for(let phase=cancelPhase; phase<PHASES.length; phase++){
    const cumSnap = timeline.cumTimeByPhase[phase];
    if(!cumSnap || cumSnap[slotKey]==null) continue;
    cumSnap[slotKey] -= cancelledCost;
    const order = timeline.phaseOrders[phase];
    if(!order) continue;
    const isRacingAt = k => timeline.retiredAtPhase[k]==null || phase < timeline.retiredAtPhase[k];
    const activeKeys = order.filter(isRacingAt);
    const retiredKeys = order.filter(k => !isRacingAt(k));
    activeKeys.sort((k1,k2)=> cumSnap[k1]-cumSnap[k2]);
    timeline.phaseOrders[phase] = [...activeKeys, ...retiredKeys];
  }

  // annulliamo anche il reset gomme che sarebbe successo li' — la gomma continua a consumarsi
  // dal punto vero, invece di ripartire una seconda volta da fresca. V0.9.9.60: FIX — il calcolo
  // precedente confrontava male le fasi (l'usura cresce naturalmente comunque fase su fase, quindi
  // il confronto dava sempre zero). Ora stimiamo il tasso di crescita "pulito" da un intervallo che
  // non è esso stesso un punto di reset, per capire quanto sarebbe DAVVERO salita l'usura li'.
  if(timeline.tireWearByPhase){
    const wSnap = timeline.tireWearByPhase;
    const wearAtCancel = wSnap[cancelPhase] ? (wSnap[cancelPhase][slotKey]||0.05) : 0.05;
    const wearBeforeCancel = wSnap[cancelPhase-1] ? (wSnap[cancelPhase-1][slotKey]||0) : 0;
    let growthRate = 0.04; // valore di riserva se non stimabile
    if(wSnap[cancelPhase+1] && wSnap[cancelPhase] && wSnap[cancelPhase+1][slotKey]!=null){
      const g = wSnap[cancelPhase+1][slotKey] - wSnap[cancelPhase][slotKey];
      if(g>0) growthRate = g;
    }
    const expectedWithoutReset = wearBeforeCancel + growthRate;
    const undoDrop = Math.max(0, expectedWithoutReset - wearAtCancel);
    for(let phase=cancelPhase; phase<wSnap.length; phase++){
      const snap = wSnap[phase];
      if(snap && snap[slotKey]!=null) snap[slotKey] = Math.min(1, snap[slotKey]+undoDrop);
    }
  }
}
// V0.9.9.61: generalizzata da applyRealPitUnderSC — riusabile per QUALUNQUE decisione live che
// comporti un vero pit stop (non solo sotto Safety Car), con isDiscounted a scegliere la formula
// di costo giusta e targetPhase a scegliere QUANDO succede davvero (utile per "ritarda la sosta",
// che sposta la sosta piu' avanti, non la applica subito al momento della decisione).
// Segnalato da Gio: "rivediamo tutte le azioni live che riguardano il pit stop".
// V0.9.9.61: ritarda una sosta futura invece di annullarla — sposta il costo/reset gomme piu'
// avanti nella gara (di default 3 fasi dopo quella cancellata, senza superare la penultima fase).
// Usata da "ritarda la sosta" (pit) e "resta fuori" (overcut) — nessun costo pagato ORA, solo
// gomme piu' consumate nel frattempo perche' la sosta arriva piu' tardi del previsto.
// V0.9.9.65: helper riusabile per applicare usura gomme extra VERA (non narrativa), propagata sulle
// fasi future — stessa logica gia' usata per "Spingi" (aggression), ora condivisa da tutte le nuove
// decisioni che comportano un rischio di usura reale (graining, gomme al limite, danno all'ala).
function applyExtraWearFromPhase(timeline, slotKey, tCurrent, minAmt, maxAmt){
  if(!timeline.tireWearByPhase) return;
  const extraWear = minAmt + rnd()*(maxAmt-minAmt);
  for(let phase=tCurrent; phase<timeline.tireWearByPhase.length; phase++){
    const snap = timeline.tireWearByPhase[phase];
    if(snap && snap[slotKey]!=null) snap[slotKey] = Math.min(1, snap[slotKey]+extraWear);
  }
}
function delayFuturePitStop(timeline, slotKey, tCurrent){
  let cancelPhase = null;
  for(let phase=tCurrent+1; phase<PHASES.length; phase++){
    if(timeline.pitByPhase[phase] && timeline.pitByPhase[phase].has(slotKey)){ cancelPhase = phase; break; }
  }
  if(cancelPhase===null) return; // nessuna sosta futura da ritardare
  let newPhase = Math.min(cancelPhase+3, PHASES.length-2);
  // V0.9.9.62: fix — se la nuova fase coincide con un'ALTRA sosta gia' esistente dello stesso
  // pilota (es. la seconda sosta originale), il Set non duplica la presenza ma il costo verrebbe
  // sommato una seconda volta li' senza che si veda dal conteggio fasi. Cerchiamo la prima fase
  // libera scendendo all'indietro fino a trovarne una senza collisione.
  while(newPhase>cancelPhase && timeline.pitByPhase[newPhase] && timeline.pitByPhase[newPhase].has(slotKey)){
    newPhase--;
  }
  if(newPhase===cancelPhase || (timeline.pitByPhase[newPhase] && timeline.pitByPhase[newPhase].has(slotKey))) return; // nessun posto libero per ritardare
  applyRealPitStop(timeline, slotKey, tCurrent, false, newPhase);
}
function applyRealPitStop(timeline, slotKey, tCurrent, isDiscounted, targetPhase){
  if(targetPhase===undefined) targetPhase = tCurrent;
  cancelFuturePitStop(timeline, slotKey, tCurrent); // prima annulliamo la sosta futura, se c'e'
  const comp = state.team;
  const pitSkillFrac = comp.stratega.pitstop/100;
  const cost = isDiscounted ? (12 - pitSkillFrac*2) : (24 - pitSkillFrac*2);
  for(let phase=targetPhase+1; phase<PHASES.length; phase++){
    const cumSnap = timeline.cumTimeByPhase[phase];
    if(!cumSnap || cumSnap[slotKey]==null) continue;
    cumSnap[slotKey] += cost;
    const order = timeline.phaseOrders[phase];
    if(!order) continue;
    const isRacingAt = k => timeline.retiredAtPhase[k]==null || phase < timeline.retiredAtPhase[k];
    const activeKeys = order.filter(isRacingAt);
    const retiredKeys = order.filter(k => !isRacingAt(k));
    activeKeys.sort((k1,k2)=> cumSnap[k1]-cumSnap[k2]);
    timeline.phaseOrders[phase] = [...activeKeys, ...retiredKeys];
  }
  if(timeline.tireWearByPhase){
    const wearNow = timeline.tireWearByPhase[targetPhase] ? (timeline.tireWearByPhase[targetPhase][slotKey]||0) : 0;
    const reduction = Math.max(0, wearNow - 0.05);
    for(let phase=targetPhase; phase<timeline.tireWearByPhase.length; phase++){
      const snap = timeline.tireWearByPhase[phase];
      if(snap && snap[slotKey]!=null) snap[slotKey] = Math.max(0.02, snap[slotKey]-reduction);
    }
  }
  if(!timeline.pitByPhase[targetPhase]) timeline.pitByPhase[targetPhase] = new Set();
  timeline.pitByPhase[targetPhase].add(slotKey);
  return cost;
}
function applyRealPitUnderSC(timeline, slotKey, tCurrent){
  return applyRealPitStop(timeline, slotKey, tCurrent, true);
}
// V0.9.9.72: combinazioni tipo+scelta che toccano DAVVERO il tempo cumulato (pit reale o ritardo
// sosta) — per queste, lo spostamento narrativo indipendente va saltato: il testo mostrato al
// giocatore deve riflettere il risultato VERO (derivato dalla posizione prima/dopo), non un tiro
// a parte che finisce sempre sovrastato dal costo reale (molto piu' grande in scala). Segnalato da
// Gio come bug pesante: "mi dice che guadagno posizioni ma mi trovo dietro".
const REAL_MECHANIC_CHOICES = new Set([
  'safetycar|box','weather|box','pit|early','pit|late','undercut|attempt','overcut|follow','overcut|stayout',
  'tyrecliff|box_now_cliff','frontwing|call_pits_wing','doublestack|stack','doublestack|priority',
  'pitpriority|priority_best','pitpriority|priority_tires','pitpriority|delay_both',
]);
function isRealMechanicChoice(type, choiceKey){ return REAL_MECHANIC_CHOICES.has(type+'|'+choiceKey); }
// V0.9.9.78: il risultato mostrato per le decisioni con meccanica reale va misurato a VALLE
// (qualche fase piu' avanti), non subito dopo — altrimenti non si vede ancora l'effetto vero della
// scelta (es. chi resta con le gomme sbagliate sotto la pioggia inizia a perdere terreno solo dopo,
// non nella fase immediatamente successiva). Segnalato da Gio: "deve segnarmi quante sono effettive
// a valle del pit... nei giri successivi", non l'istantanea del turno subito dopo.
function downstreamPhaseFor(t){ return Math.min(t+3, PHASES.length-1); }
function applyLiveDecision(type, choiceKey){
  const timeline = state.live.timeline;
  const t = state.live.phaseIndex;
  // V0.9.7.9.9: in Carriera Pilota le decisioni sono PERSONALI del pilota, non ordini di scuderia
  // che coinvolgono entrambe le vetture — il compagno di scuderia e' un'IA indipendente.
  const affectedSlots = state.isDriverCareer ? ['PLAYER-1'] : ['PLAYER-1','PLAYER-2'];
  const reveal = {}; // V0.9.7.9.20: esito del primo tiro per pilota, per il ballottaggio in UI

  function applyShiftAcrossPhases(slotKey, firstShift, laterShiftFn){
    let isFirst = true;
    let actualFirstShift = 0; // V0.9.9.18: lo spostamento VERO alla prima fase, dopo il limite ai bordi
    let firstPhaseTimeBonus = 0; // V0.9.9.21: secondi guadagnati/persi quando il limite "spreca" parte dello shift
    for(let phase=t+1; phase<PHASES.length; phase++){
      const order = timeline.phaseOrders[phase];
      const idx = order.indexOf(slotKey);
      if(idx<0) continue;
      const shift = isFirst ? firstShift : laterShiftFn();
      if(shift===0){ isFirst = false; continue; }
      const newIdx = Math.max(0, Math.min(order.length-1, idx+shift));
      const clampedAmount = shift - (newIdx-idx); // quanto dello shift richiesto non si e' potuto applicare (limite ai bordi)
      if(isFirst){ actualFirstShift = newIdx - idx; firstPhaseTimeBonus = clampedAmount * TIME_PER_CLAMPED_POSITION; }
      isFirst = false;
      order.splice(idx,1); order.splice(newIdx,0,slotKey);
      const cumSnap = timeline.cumTimeByPhase && timeline.cumTimeByPhase[phase];
      interpolateCumTimeForShift(cumSnap, order, slotKey, newIdx, timeline.retiredAtPhase);
      // V0.9.9.21: gia' primo (o gia' ultimo) — il guadagno/svantaggio che non puo' tradursi in
      // posizioni diventa distacco reale, invece di sparire nel nulla. Segno: clampedAmount negativo
      // = guadagno sprecato (es. -2 non applicato) => il tempo MIGLIORA (si sottrae); positivo =
      // perdita sprecata => il tempo PEGGIORA (si somma).
      if(clampedAmount!==0 && cumSnap && cumSnap[slotKey]!=null) cumSnap[slotKey] += clampedAmount * TIME_PER_CLAMPED_POSITION;
    }
    return { actualFirstShift, firstPhaseTimeBonus };
  }

  if(choiceKey==='splitstrategy'){
    const slots = state.isDriverCareer ? ['PLAYER-1'] : ['PLAYER-1','PLAYER-2'];
    const bucketChoice = { 'PLAYER-1':'box', 'PLAYER-2':'stay' };
    slots.forEach(slotKey=>{
      if(timeline.retiredAtPhase[slotKey]!==null) return;
      const isRealBox = (type==='safetycar' || type==='weather' || type==='doublestack') && bucketChoice[slotKey]==='box';
      const outcome = pickDecisionOutcome(bucketChoice[slotKey]);
      let actualFirstShift, firstPhaseTimeBonus, realPitCost = null;
      if(isRealBox){
        // V0.9.9.72: chi va DAVVERO ai box — niente spostamento narrativo indipendente, il
        // risultato mostrato riflette il vero prima/dopo (altrimenti il costo reale, molto piu'
        // grande in scala, lo sovrasta sempre e il testo mente sistematicamente).
        const order = timeline.phaseOrders[downstreamPhaseFor(t)] || timeline.phaseOrders[t] || [];
        const beforeRank = order.indexOf(slotKey);
        realPitCost = applyRealPitStop(timeline, slotKey, t, t===timeline.safetyCarPhase);
        const orderAfter = timeline.phaseOrders[downstreamPhaseFor(t)] || timeline.phaseOrders[t] || [];
        const afterRank = orderAfter.indexOf(slotKey);
        actualFirstShift = (beforeRank>=0 && afterRank>=0) ? (beforeRank - afterRank) : 0;
        firstPhaseTimeBonus = 0;
      } else {
        const shiftResult = applyShiftAcrossPhases(slotKey, outcome.shift, decisionShiftFn(bucketChoice[slotKey]));
        actualFirstShift = shiftResult.actualFirstShift;
        firstPhaseTimeBonus = shiftResult.firstPhaseTimeBonus;
      }
      const bucketIdxFinal = isRealBox ? closestBucketIdx(outcome.buckets, actualFirstShift) : outcome.bucketIdx;
      reveal[slotKey] = { bucketIdx:bucketIdxFinal, buckets:outcome.buckets, shift:actualFirstShift, timeBonus:firstPhaseTimeBonus, realPitCost };
    });
    return reveal;
  }

  // V0.9.9.72: cattura le posizioni di PARTENZA di tutti gli slot coinvolti, PRIMA che qualunque
  // meccanica reale parta — se entrambi i piloti vanno ai box nella stessa scelta, il pit del primo
  // non deve falsare la misurazione "prima" dell'altro (o viceversa per "dopo", vedi passaggio finale).
  const realMechanic = isRealMechanicChoice(type, choiceKey);
  const beforeRanks = {};
  if(realMechanic){
    const orderBefore = timeline.phaseOrders[downstreamPhaseFor(t)] || timeline.phaseOrders[t] || [];
    affectedSlots.forEach(slotKey=>{ beforeRanks[slotKey] = orderBefore.indexOf(slotKey); });
  }
  affectedSlots.forEach(slotKey=>{
    if(timeline.retiredAtPhase[slotKey]!==null) return; // gia' ritirato: la scelta non ha piu' effetto
    const outcome = pickDecisionOutcome(choiceKey);
    // V0.9.9.72: per le scelte che toccano DAVVERO il tempo cumulato (pit reale o ritardo sosta),
    // saltiamo lo spostamento narrativo indipendente — altrimenti il costo reale (molto piu' grande
    // in scala) lo sovrasta sempre e il testo mostrato al giocatore mente sistematicamente ("guadagni
    // posizioni" quando in realta' finisce dietro). Il risultato mostrato viene invece calcolato dal
    // vero prima/dopo, in un passaggio finale DOPO che tutti gli slot coinvolti hanno finito.
    let actualFirstShift = 0, firstPhaseTimeBonus = 0;
    if(!realMechanic){
      const shiftResult = applyShiftAcrossPhases(slotKey, outcome.shift, decisionShiftFn(choiceKey));
      actualFirstShift = shiftResult.actualFirstShift;
      firstPhaseTimeBonus = shiftResult.firstPhaseTimeBonus;
    }
    // V0.9.9.55/61: le scelte che comportano un vero pit stop (sotto Safety Car o normale) ora
    // muovono DAVVERO la simulazione — costo reale in secondi + gomme nuove — non solo un esito
    // narrativo scollegato. "Ritarda"/"resta fuori" spostano la sosta futura piu' avanti invece di
    // applicarne una subito.
    let realPitCost = null;
    if(type==='safetycar' && choiceKey==='box'){
      realPitCost = applyRealPitUnderSC(timeline, slotKey, t);
    } else if(type==='weather' && choiceKey==='box'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, t===timeline.safetyCarPhase);
    } else if(type==='pit' && choiceKey==='early'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, false);
    } else if(type==='pit' && choiceKey==='late'){
      delayFuturePitStop(timeline, slotKey, t);
    } else if(type==='undercut' && choiceKey==='attempt'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, false);
    } else if(type==='overcut' && choiceKey==='follow'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, false);
    } else if(type==='overcut' && choiceKey==='stayout'){
      delayFuturePitStop(timeline, slotKey, t);
    }
    // V0.9.9.63: due esiti ora hanno una conseguenza VERA, non solo narrativa — corretto durante
    // la revisione del foglio decisioni con Gio.
    const pickedLabel = outcome.buckets[outcome.bucketIdx].label;
    if(type==='mechanical' && choiceKey==='push' && pickedLabel==='retired'){
      // il pilota si ritira DAVVERO da questa fase in poi, come un ritiro naturale della simulazione
      timeline.retiredAtPhase[slotKey] = t;
    }
    if((type==='trackliminvestigation' && choiceKey==='push_limit' && pickedLabel==='lose_2') ||
       (type==='doubleyellow' && choiceKey==='risk_pace_yellow' && pickedLabel==='lose_2')){
      // penalità VERA (stato "PENALITÀ" mostrato in classifica), non solo perdita di posizioni
      if(!timeline.penaltyByPhase[t]) timeline.penaltyByPhase[t] = new Set();
      timeline.penaltyByPhase[t].add(slotKey);
    }
    // V0.9.9.63: "Spingi" (aggression/aggressive) ora comporta un vero aumento di usura gomme
    // propagato sulle fasi future — richiesto esplicitamente da Gio: spingere al limite deve
    // poter compromettere davvero il resto della gara, non solo l'esito immediato di questa fase.
    if(type==='aggression' && choiceKey==='aggressive' && timeline.tireWearByPhase){
      const extraWear = 0.09 + rnd()*0.06; // 9-15% di usura extra, effetto reale non simbolico
      for(let phase=t; phase<timeline.tireWearByPhase.length; phase++){
        const snap = timeline.tireWearByPhase[phase];
        if(snap && snap[slotKey]!=null) snap[slotKey] = Math.min(1, snap[slotKey]+extraWear);
      }
    }
    // V0.9.9.65: le 8 nuove decisioni selezionate dalle 30 proposte — agganciate alle stesse
    // meccaniche vere (pit stop reale, usura gomme extra) dove ha senso, non solo narrativa.
    if(type==='graining' && choiceKey==='push_through'){
      applyExtraWearFromPhase(timeline, slotKey, t, 0.08, 0.13);
    } else if(type==='tyrecliff' && choiceKey==='box_now_cliff'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, false);
    } else if(type==='tyrecliff' && choiceKey==='one_lap_cliff'){
      applyExtraWearFromPhase(timeline, slotKey, t, 0.10, 0.16);
    } else if(type==='tyrecliff' && choiceKey==='push_limit_cliff'){
      applyExtraWearFromPhase(timeline, slotKey, t, 0.15, 0.22);
    } else if(type==='frontwing' && choiceKey==='call_pits_wing'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, false);
    } else if(type==='frontwing' && choiceKey==='continue_wing'){
      applyExtraWearFromPhase(timeline, slotKey, t, 0.08, 0.14);
    } else if(type==='frontwing' && choiceKey==='compensate_wing'){
      applyExtraWearFromPhase(timeline, slotKey, t, 0.05, 0.09);
    } else if(type==='debris' && choiceKey==='maintain_debris'){
      applyExtraWearFromPhase(timeline, slotKey, t, 0.04, 0.09);
    } else if(type==='doublestack' && choiceKey==='stack'){
      realPitCost = applyRealPitStop(timeline, slotKey, t, false);
      // chi e' dietro nell'ordine attuale e' il "secondo" in coda, perde qualche secondo extra
      const order = timeline.phaseOrders[t] || [];
      const otherSlotDS = slotKey==='PLAYER-1' ? 'PLAYER-2' : 'PLAYER-1';
      if(order.indexOf(slotKey) > order.indexOf(otherSlotDS)){
        const queueCost = 3 + rnd()*3; // 3-6s extra per l'attesa in coda
        for(let phase=t+1; phase<PHASES.length; phase++){
          const cumSnap = timeline.cumTimeByPhase[phase];
          if(cumSnap && cumSnap[slotKey]!=null) cumSnap[slotKey] += queueCost;
        }
      }
    } else if(type==='doublestack' && choiceKey==='priority'){
      const order = timeline.phaseOrders[t] || [];
      const otherSlotDS = slotKey==='PLAYER-1' ? 'PLAYER-2' : 'PLAYER-1';
      const myPos = order.indexOf(slotKey), otherPos = order.indexOf(otherSlotDS);
      if(myPos>=0 && (otherPos<0 || myPos<otherPos)){
        realPitCost = applyRealPitStop(timeline, slotKey, t, false); // sono il meglio piazzato, mi fermo davvero
      }
    } else if(type==='pitpriority' && choiceKey==='priority_best'){
      const order = timeline.phaseOrders[t] || [];
      const otherSlotPP = slotKey==='PLAYER-1' ? 'PLAYER-2' : 'PLAYER-1';
      const myPos = order.indexOf(slotKey), otherPos = order.indexOf(otherSlotPP);
      if(myPos>=0 && (otherPos<0 || myPos<otherPos)){
        realPitCost = applyRealPitStop(timeline, slotKey, t, false);
      } else {
        delayFuturePitStop(timeline, slotKey, t);
      }
    } else if(type==='pitpriority' && choiceKey==='priority_tires'){
      const otherSlotPP = slotKey==='PLAYER-1' ? 'PLAYER-2' : 'PLAYER-1';
      const myWear = timeline.tireWearByPhase[t] ? (timeline.tireWearByPhase[t][slotKey]||0) : 0;
      const otherWear = timeline.tireWearByPhase[t] ? (timeline.tireWearByPhase[t][otherSlotPP]||0) : 0;
      if(myWear >= otherWear){
        realPitCost = applyRealPitStop(timeline, slotKey, t, false); // gomme peggiori delle mie, priorita' a me
      } else {
        delayFuturePitStop(timeline, slotKey, t);
      }
    } else if(type==='pitpriority' && choiceKey==='delay_both'){
      delayFuturePitStop(timeline, slotKey, t);
    }
    // V0.9.9.63: obiettivo Liberi di Lottare — contiamo ogni volta che si sceglie "free" in
    // teamorders (una volta per decisione, non per pilota coinvolto, altrimenti conterebbe doppio).
    if(type==='teamorders' && choiceKey==='free' && slotKey===affectedSlots[0]){
      const count = loadTeamBattleCount()+1;
      saveTeamBattleCount(count);
      if(count>=50) unlockAchievement('liberi-di-lottare');
    }
    // V0.9.9.18/21: il testo mostrato usa lo shift VERO (dopo il limite ai bordi), non quello
    // nominale della scelta. Se sei gia' primo/ultimo e il guadagno/perdita non puo' tradursi in
    // posizioni, diventa un distacco in secondi (timeBonus) invece di sparire nel nulla.
    reveal[slotKey] = { bucketIdx:outcome.bucketIdx, buckets:outcome.buckets, shift:actualFirstShift, timeBonus:firstPhaseTimeBonus, realPitCost };
  });
  // V0.9.9.72: passaggio FINALE, DOPO che tutti gli slot coinvolti hanno completato le loro
  // meccaniche reali — se entrambi i piloti vanno ai box nella stessa scelta, il pit del secondo
  // sposta ANCHE la posizione relativa del primo, quindi il "dopo" va misurato solo qui, a tutto
  // concluso, non dentro il ciclo di ciascuno slot (altrimenti il risultato mostrato al primo pilota
  // processato risultava sistematicamente sbagliato di 1 posizione).
// V0.9.9.79: trova il bucket la cui etichetta descrive meglio il risultato VERO di una scelta con
// meccanica reale — altrimenti l'animazione di rivelazione (quella che gira e si ferma su una
// scelta) resta legata al tiro narrativo indipendente, mai aggiornato dal fix del risultato vero:
// mostra "perdi 2 posizioni" mentre la classifica applica +6 o -11, un'incoerenza scoperta
// controllando la card vera a schermo, non solo il numero. I bucket usano "negativo=guadagno",
// il nostro shift usa "positivo=guadagno" — va invertito il segno prima del confronto.
function closestBucketIdx(buckets, actualShift){
  const target = -actualShift;
  let bestIdx = 0, bestDist = Infinity;
  buckets.forEach((b, i)=>{
    const dist = target < b.min ? b.min-target : (target > b.max ? target-b.max : 0);
    if(dist < bestDist){ bestDist = dist; bestIdx = i; }
  });
  return bestIdx;
}
  if(realMechanic){
    const orderAfter = timeline.phaseOrders[downstreamPhaseFor(t)] || timeline.phaseOrders[t] || [];
    affectedSlots.forEach(slotKey=>{
      if(!reveal[slotKey]) return;
      const afterRank = orderAfter.indexOf(slotKey);
      const beforeRank = beforeRanks[slotKey];
      reveal[slotKey].shift = (beforeRank>=0 && afterRank>=0) ? (beforeRank - afterRank) : 0;
      reveal[slotKey].timeBonus = 0;
      reveal[slotKey].bucketIdx = closestBucketIdx(reveal[slotKey].buckets, reveal[slotKey].shift);
    });
  }
  return reveal;
}

// V0.9.7.9.9: conseguenze personali (Fama/Reputazione/Rivalità col compagno) sopra il sistema di
// decisioni GIA' esistente — nessun secondo motore, solo un livello di significato aggiunto quando
// si gioca in Carriera Pilota. Le scelte "audaci" scalano con il Rating: un pilota fortissimo ha
// più probabilità di trasformare un rischio in un successo (spec punto 8/9 del documento di design).
const DRIVER_DECISION_CONSEQUENCES = {
  weather: { box:{fama:0,reputazione:1}, stay:{fama:2,reputazione:0}, splitstrategy:{fama:1,reputazione:0} },
  safetycar: { box:{fama:0,reputazione:1}, stay:{fama:1,reputazione:0}, restart:{fama:2,reputazione:-1} },
  pit: { early:{fama:0,reputazione:1}, late:{fama:1,reputazione:0} },
  aggression: { aggressive:{fama:3,reputazione:-1}, safe:{fama:0,reputazione:2} },
  teamorders: { hold:{fama:0,reputazione:3,rivalry:-2}, free:{fama:2,reputazione:-1,rivalry:3} },
  defend: { defend:{fama:2,reputazione:0}, letpass:{fama:-1,reputazione:2} },
  enginemode: { push:{fama:1,reputazione:0}, save:{fama:0,reputazione:1} },
  mechanical: { nurse:{fama:0,reputazione:2}, push:{fama:2,reputazione:-1} },
};
function applyDriverCareerDecisionConsequences(type, choiceKey){
  if(!state.isDriverCareer) return;
  const d = driverCareerState.driver;
  reinforceArchetypeIfCoherent(type, choiceKey, d);
  checkAndScheduleChainConsequence(type, choiceKey);
  const delta = (DRIVER_DECISION_CONSEQUENCES[type]||{})[choiceKey];
  if(!delta) return;
  const ratingFactor = 0.6 + (d.rating/100)*0.8; // rating basso: 0.6x — rating alto: fino a 1.4x
  const famaDelta = delta.fama>0 ? Math.round(delta.fama*ratingFactor) : (delta.fama||0);
  d.fama = Math.max(0, Math.min(100, d.fama + famaDelta));
  d.reputazione = Math.max(0, Math.min(100, d.reputazione + (delta.reputazione||0)));
  if(delta.rivalry) driverCareerState.teammateRivalry = Math.max(0, Math.min(100, (driverCareerState.teammateRivalry||0) + delta.rivalry));
}

// V0.9.7.9.13: quali scelte in gara sono "coerenti" con ciascun archetipo — ogni volta che il
// giocatore ne fa una, l'archetipo si rafforza un po' verso l'effetto pieno (mai retrocede per
// scelte incoerenti, semplicemente non avanza quella volta — documento design, punto 1/4).
const ARCH_REINFORCE_MAP = {
  'Rain Master':     [{type:'weather',choice:'stay'}],
  'The Hunter':      [{type:'aggression',choice:'aggressive'},{type:'defend',choice:'defend'}],
  'The Machine':     [{type:'aggression',choice:'safe'},{type:'enginemode',choice:'save'}],
  'Tire Whisperer':  [{type:'enginemode',choice:'save'},{type:'mechanical',choice:'nurse'}],
  'Ice Man':         [{type:'aggression',choice:'safe'},{type:'defend',choice:'letpass'}],
  'Wild Card':       [{type:'aggression',choice:'aggressive'},{type:'teamorders',choice:'free'}],
  'Strategic Mind':  [{type:'pit',choice:'early'},{type:'pit',choice:'late'},{type:'weather',choice:'splitstrategy'}],
  'Comeback King':   [{type:'aggression',choice:'aggressive'},{type:'defend',choice:'defend'}],
  'Pole Specialist': [{type:'enginemode',choice:'push'}],
  'Street King':     [{type:'aggression',choice:'aggressive'}],
  'Rookie Wonder':   [{type:'aggression',choice:'safe'},{type:'defend',choice:'defend'}],
};
const ARCH_REINFORCE_STEP = 0.035;
function reinforceArchetypeIfCoherent(type, choiceKey, driver){
  if(driver.archStrength>=1) return;
  const matches = ARCH_REINFORCE_MAP[driver.arch] || [];
  const isCoherent = matches.some(m=>m.type===type && m.choice===choiceKey);
  if(isCoherent) driver.archStrength = Math.min(1, (driver.archStrength||0.2) + ARCH_REINFORCE_STEP);
}

const HIGH_STAKES_CHOICES = new Set(['try_overtake_desperate','lighten_fuel','all_or_nothing_push']);

// V0.9.7.9.24 — ridisegnato da capo dopo feedback: il battito-su-tutto-insieme era confuso e
// lasciava troppo poco tempo per leggere. Nuovo meccanismo: una "ruota" che rallenta, un SOLO
// elemento evidenziato alla volta (non tutti a lampeggiare insieme), atterra sempre sulla risposta
// vera, poi resta ferma e leggibile a lungo prima di chiudersi.
const REVEAL_SCHEDULE_NORMAL = [140,150,170,200,250,340];       // ~1250ms totali, ultimo step = esito vero
const REVEAL_SCHEDULE_HIGHSTAKES = [110,115,125,140,160,190,230,290,380,520]; // ~2260ms, piu' lunga e piu' scandita

function resolveLiveDecision(choiceKey){
  const dec = state.live.activeDecision;
  if(!dec) return;
  const outcomes = applyLiveDecision(dec.type, choiceKey);
  applyDriverCareerDecisionConsequences(dec.type, choiceKey);
  state.live.resolvedDecisions.push(dec.phase);
  state.live.activeDecision = null;
  state.live.decisionDeadline = null;

  const slotKeys = Object.keys(outcomes);
  // V0.9.7.9.25: se TUTTI gli esiti sono deterministici (un solo bucket possibile, 100%), non c'e'
  // niente da rivelare — saltiamo il ballottaggio del tutto e proseguiamo subito, niente teatro
  // inutile su una scelta che non aveva davvero incertezza.
  const isFullyDeterministic = slotKeys.every(k => outcomes[k].buckets.length===1);
  if(isFullyDeterministic){
    state.live.paused = false;
    render();
    return;
  }

  const isHighStakes = HIGH_STAKES_CHOICES.has(choiceKey);
  const schedule = isHighStakes ? REVEAL_SCHEDULE_HIGHSTAKES : REVEAL_SCHEDULE_NORMAL;
  state.live.pendingReveal = { outcomes, stage:'cycling', highStakes:isHighStakes, highlightIdx:{} };
  slotKeys.forEach(k=> state.live.pendingReveal.highlightIdx[k] = 0);
  render();

  let step = 0;
  function tick(){
    if(!state.live || !state.live.pendingReveal) return;
    const isLast = step===schedule.length-1;
    slotKeys.forEach(slotKey=>{
      const { bucketIdx, buckets } = outcomes[slotKey];
      state.live.pendingReveal.highlightIdx[slotKey] = isLast ? bucketIdx : (step % buckets.length);
    });
    if(isLast){
      state.live.pendingReveal.stage = 'settled';
      render();
      // suono + aptico proprio nel momento in cui la ruota si ferma sulla risposta vera
      const outcomeTypes = Object.values(outcomes).map(o=>{
        const label = o.buckets[o.bucketIdx].label;
        return label.startsWith('gain') ? 'gain' : label.startsWith('lose') ? 'lose' : 'hold';
      });
      const hasGain = outcomeTypes.includes('gain');
      const hasLose = outcomeTypes.includes('lose');
      if(hasGain) playSfx('upgrade_success');
      if(hasLose) setTimeout(()=> playSfx('upgrade_fail'), hasGain ? 180 : 0);
      if(navigator.vibrate && audioSettings.hapticEnabled!==false){
        try{ navigator.vibrate(isHighStakes ? (hasGain&&!hasLose?[18,35,18,35,90]:[130]) : [35]); }catch(e){}
      }
      // V0.9.7.9.25: tempo di lettura DINAMICO in base a quanto testo c'e' davvero da leggere —
      // i risultati brevi restano come prima, quelli con piu' testo (nomi lunghi, piu' colonne)
      // ottengono automaticamente piu' tempo, invece di un valore fisso identico per tutti.
      let readLen = 0;
      slotKeys.forEach(slotKey=>{
        const { bucketIdx, buckets, shift, timeBonus } = outcomes[slotKey];
        // V0.9.9.102: BUG CORRETTO — il segno di "shift" ha convenzione OPPOSTA tra scelte
        // narrative (bucket: negativo=guadagno) e scelte a meccanica reale (positivo=guadagno,
        // stabilito quando ho corretto il calcolo del risultato vero). Usare qui shift<0 come
        // controllo universale era sbagliato per le scelte a meccanica reale, causando testo
        // "guadagni"/"perdi" scambiato rispetto al colore vero (segnalato da un tester con
        // screenshot). Corretto derivando guadagno/perdita dall'etichetta del bucket GIA' scelto
        // correttamente (buckets[bucketIdx].label), sempre coerente qualunque sia la provenienza.
        const eraDavveroGuadagno = buckets[bucketIdx].label.startsWith('gain');
        const label = shift!==0 ? t(eraDavveroGuadagno ? 'bkt_gain_exact' : 'bkt_lose_exact', Math.abs(shift))
          : (timeBonus ? t(timeBonus<0 ? 'bkt_gain_seconds' : 'bkt_lose_seconds', Math.abs(timeBonus).toFixed(1)) : t('bkt_hold'));
        readLen += label.length;
      });
      const baseMs = isHighStakes ? 3200 : 2400;
      const dynamicMs = baseMs + Math.max(0, readLen-30)*38;
      setTimeout(()=>{
        if(!state.live) return;
        state.live.pendingReveal = null;
        state.live.paused = false;
        render();
      }, dynamicMs);
      return;
    }
    render();
    if(navigator.vibrate && audioSettings.hapticEnabled!==false){
      try{ navigator.vibrate(6); }catch(e){} // piccolo "tick" meccanico ad ogni scatto della ruota
    }
    step++;
    setTimeout(tick, schedule[step]);
  }
  setTimeout(tick, schedule[0]);
}

function startLiveRace(timeline){
  state.live = {
    timeline, phaseIndex: -1, elapsedInPhase: 0, phaseDuration: randomPhaseDuration(),
    paused:false, speed: (typeof defaultRaceSpeed!=='undefined' ? defaultRaceSpeed : 1), domReady:false, visibleLog:[],
    weather: timeline.weatherBefore, trackStatus:'Regolare', sunFlashPlayed:false,
    pendingDecisions: computeLiveDecisions(timeline), resolvedDecisions: [], activeDecision: null
  };
  state.phase = 'race_live';
  advanceLivePhase();
  render();
  startLiveTicker();
}

function advanceLivePhase(){
  // V0.9.9.52: sostituisce il vecchio sistema "stessa velocità, tempo dimezzato" — ora X1 mostra
  // il doppio dei momenti (24 invece di 12), interpolando un fotogramma intermedio tra una fase
  // vera e la successiva; X2 resta il comportamento originale (12 fasi, un passo alla volta).
  // Gli effetti REALI (log, meteo, Safety Car, decisioni) scattano solo sui passaggi interi — un
  // mezzo passo è puramente un fotogramma interpolato, non una fase vera della simulazione.
  // il primissimo avanzamento (da -1, prima che la gara sia partita) atterra sempre sulla fase
  // intera 0 — non esiste una "fase -1" con cui interpolare, quindi qui il passo e' sempre 1
  const step = state.live.phaseIndex < 0 ? 1 : (state.live.speed===1 ? 0.5 : 1);
  state.live.phaseIndex += step;
  state.live.elapsedInPhase = 0;
  state.live.phaseDuration = randomPhaseDuration();
  const t = state.live.phaseIndex;
  if(!Number.isInteger(t)) return; // fotogramma interpolato: nessun evento reale, solo display
  const timeline = state.live.timeline;
  const newLines = buildPhaseLog(t, timeline);
  newLines.forEach(l=>{ if(l.sfx) playSfx(l.sfx); if(l.realSfx) playRealSfx(l.realSfx); }); // V0.9.7.8.2 / V0.9.7.8.14
  state.live.visibleLog = [...newLines.slice().reverse(), ...state.live.visibleLog].slice(0,40);
  if(timeline.weatherChangePhase===t) state.live.weather = timeline.weatherAfter;
  if(timeline.safetyCarPhase===t) state.live.trackStatus = 'Safety Car';
  if(timeline.safetyCarPhase!==null && t===timeline.safetyCarPhase+1) state.live.trackStatus = 'Regolare';

  const dec = state.live.pendingDecisions.find(d=>d.phase===t && !state.live.resolvedDecisions.includes(d.phase));
  if(dec){
    state.live.activeDecision = dec;
    state.live.paused = true;
    state.live.decisionDeadline = decisionTimerEnabled ? (Date.now()+DECISION_TIME_MS) : null;
    triggerTensionHaptic(); // V0.9.7.8.10
    playRealSfx('audio/sfx_race_action.mp3'); // V0.9.7.8.19: suono all'apparire della scheda decisione, non al click
    // V0.9.9.112: DECISIONE COME EVENTO — richiesto da Gio ("le decisioni live vanno enfatizzate,
    // magari solo le più rischiose"). Se almeno una delle opzioni disponibili è ad alto rischio
    // (HIGH_STAKES_CHOICES), suona un secondo effetto più urgente sopra quello normale, e il
    // rendering (liveDecisionHTML) applicherà anche il trattamento visivo drammatico.
    const infoDec = LIVE_DECISION_INFO[dec.type];
    if(infoDec && infoDec.choices.some(c=>HIGH_STAKES_CHOICES.has(c.key))){
      playRealSfx('audio/sfx_error_disabled.mp3'); // suono più "allarme", riusato per l'urgenza
    }
  }
}

const DECISION_TIME_MS = 12000; // V0.9.3.2: durata del countdown per le decisioni in gara, se attivo

function liveTick(){
  if(!state.live || state.phase!=='race_live'){ if(window._liveTimer) clearInterval(window._liveTimer); return; }
  if(state.live.activeDecision){
    if(state.live.decisionDeadline!=null && Date.now() >= state.live.decisionDeadline){
      const info = LIVE_DECISION_INFO[state.live.activeDecision.type];
      resolveLiveDecision(info.choices[0].key); // tempo scaduto: si applica la prima opzione, la piu' prudente
    }
    return;
  }
  if(state.live.paused) return;
  state.live.elapsedInPhase += 200*state.live.speed;
  if(state.live.elapsedInPhase >= state.live.phaseDuration){
    if(state.live.phaseIndex >= PHASES.length-1){
      clearInterval(window._liveTimer);
      finishLiveRace();
      return;
    }
    advanceLivePhase();
    render();
  }
}

function startLiveTicker(){
  if(window._liveTimer) clearInterval(window._liveTimer);
  window._liveTimer = setInterval(liveTick, 200);
}

function pauseLive(){
  if(!state.live) return;
  state.live.paused = !state.live.paused;
  render();
}
function toggleSpeedLive(){
  if(!state.live) return;
  const goingTo2x = state.live.speed===1;
  state.live.speed = state.live.speed===1 ? 2 : 1;
  render();
  // V0.9.7.9.28: contiamo solo il PRIMO passaggio a x2 dentro questa gara (non ogni click avanti
  // e indietro), cosi' "seconda volta di fila" significa davvero "in due gare diverse".
  if(goingTo2x && !state.live.speed2xCountedThisRace){
    state.live.speed2xCountedThisRace = true;
    const count = loadSpeed2xCount()+1;
    saveSpeed2xCount(count);
    if(count===2 && defaultRaceSpeed!==2 && !hasSpeed2xPromptShown()){
      markSpeed2xPromptShown();
      setTimeout(()=>{
        gameConfirm(t('speed2x_prompt_desc'), ()=>{
          defaultRaceSpeed = 2;
          saveDefaultRaceSpeed(2);
        }, t('speed2x_prompt_title'));
      }, 500); // piccolo ritardo, non interrompe di scatto il click appena fatto
    }
  }
}
function skipLiveRace(){
  if(window._liveTimer) clearInterval(window._liveTimer);
  const timeline = state.live.timeline;
  __suppressSfx = true; // V0.9.7.8.2: evita una raffica di suoni sovrapposti quando si salta l'animazione
  while(state.live.phaseIndex < PHASES.length-1){
    advanceLivePhase();
    if(state.live.activeDecision){
      // in modalita' salta-alla-fine si sceglie sempre l'opzione piu' prudente, senza rischi
      const safeChoice = { weather:'box', safetycar:'box', pit:'early', aggression:'safe' }[state.live.activeDecision.type] || 'box';
      resolveLiveDecisionSilent(safeChoice);
    }
  }
  __suppressSfx = false;
  finishLiveRace();
}
function resolveLiveDecisionSilent(choiceKey){
  const dec = state.live.activeDecision;
  if(!dec) return;
  applyLiveDecision(dec.type, choiceKey);
  applyDriverCareerDecisionConsequences(dec.type, choiceKey);
  state.live.resolvedDecisions.push(dec.phase);
  state.live.activeDecision = null;
  state.live.paused = false;
}
function finishLiveRace(){
  finalizeRaceScoring(state.live.timeline);
  // V0.9.7.8.2: SFX #12/#13 — in base al miglior risultato del giocatore in questa gara
  const playerEntries = state.live.timeline.entries.filter(e=>e.isPlayerTeam && !e.dnf);
  const bestPos = playerEntries.length ? Math.min(...playerEntries.map(e=>e.pos)) : null;
  if(bestPos===1) playSfx('victory_fanfare');
  else if(bestPos!==null && bestPos<=3) playSfx('podium');
  // V0.9.9.58: su richiesta di Gio, niente transizione tra gara e risultato in caso di vittoria —
  // l'esultanza deve arrivare subito, senza un'animazione di passaggio che la rallenti.
  if(bestPos===1) window._skipNextTransition = true;
  state.phase = 'race_result';
  render();
}

/* ---------------- V0.4 rendering: board live con righe animate ---------------- */
const ROW_H = 34;

// V0.9.9.52: unico helper di interpolazione, riusato per qualunque valore per-fase (usura gomme,
// e implicitamente il tempo cumulato in computeLiveRows) — cosi' non serve duplicare la logica.
function interpolatePerPhaseValue(byPhaseArray, tLow, tHigh, frac, key){
  const a = byPhaseArray[tLow] ? byPhaseArray[tLow][key] : undefined;
  if(a==null) return 0;
  const bRaw = byPhaseArray[tHigh] ? byPhaseArray[tHigh][key] : undefined;
  const b = bRaw!=null ? bRaw : a;
  // V0.9.9.179: BUG CORRETTO — segnalato da Gio: "l'usura su pc a volte sembra diminuire, succede
  // solo su pc". Causa probabile: questa interpolazione lineare, usata per l'animazione fluida
  // dell'usura durante la gara live, mostrava una discesa GRADUALE e visibile quando in mezzo c'era
  // un pit stop (le gomme nuove resettano correttamente l'usura a un valore basso — dato corretto,
  // ma l'interpolazione la faceva scendere lentamente frame per frame invece che di scatto, dando
  // l'impressione di un calo "innaturale" durante l'animazione — più notabile su schermi PC dove i
  // fotogrammi intermedi sono più facili da percepire rispetto a un rapido sguardo su smartphone).
  // Ora, se il valore scende tra una fase e l'altra (segno di un pit stop, mai di usura naturale che
  // aumenta sempre), passiamo di scatto al nuovo valore invece di interpolare gradualmente.
  if(b < a) return frac < 1 ? a : b;
  return a + (b-a)*frac;
}
function computeLiveRows(){
  const t = state.live.phaseIndex;
  const timeline = state.live.timeline;
  const isInterpolated = !Number.isInteger(t);
  let order, cumSnap;
  if(isInterpolated){
    // V0.9.9.52: fotogramma interpolato (velocità X1, il doppio dei momenti) — nessuna fase vera
    // qui, calcoliamo un tempo cumulato "a meta' strada" tra le due fasi vere adiacenti, e ne
    // deriviamo l'ordine (chi ha tempo piu' basso e' davanti), invece di leggere un ordine che a
    // questo indice non esiste.
    const tLow = Math.floor(t), tHigh = Math.ceil(t), frac = t-tLow;
    const snapLow = timeline.cumTimeByPhase[tLow], snapHigh = timeline.cumTimeByPhase[tHigh];
    cumSnap = {};
    Object.keys(snapLow).forEach(key=>{
      const a = snapLow[key], b = (snapHigh[key]!=null) ? snapHigh[key] : a;
      cumSnap[key] = a + (b-a)*frac;
    });
    // V0.9.9.54: fix segnalato da Gio — i ritirati finivano mescolati per tempo cumulato (spesso
    // "congelato" basso da quando si sono fermati) e potevano risultare DAVANTI a chi corre ancora.
    // La simulazione vera li separa sempre e li mette in fondo (i piu' recenti prima) — replichiamo
    // la stessa logica qui invece di un ordinamento unico per tutti.
    const retiredKeys = Object.keys(cumSnap).filter(k => timeline.retiredAtPhase[k]!==null && t>=timeline.retiredAtPhase[k]);
    const activeKeys = Object.keys(cumSnap).filter(k => !retiredKeys.includes(k));
    activeKeys.sort((k1,k2)=> cumSnap[k1]-cumSnap[k2]);
    retiredKeys.sort((k1,k2)=> (timeline.retiredAtPhase[k2]||0) - (timeline.retiredAtPhase[k1]||0));
    order = [...activeKeys, ...retiredKeys];
  } else {
    order = timeline.phaseOrders[t];
    cumSnap = timeline.cumTimeByPhase && timeline.cumTimeByPhase[t];
  }
  const prevOrder = (!isInterpolated && t>0) ? timeline.phaseOrders[t-1] : null; // niente frecce durante un fotogramma interpolato
  const byKey = {}; timeline.entries.forEach(e=> byKey[e.slotKey]=e);
  const isFinalPhase = t === PHASES.length-1;
  return order.map((key,i)=>{
    const e = byKey[key];
    const prevIdx = prevOrder ? prevOrder.indexOf(key) : -1;
    const delta = prevIdx>=0 ? (prevIdx - i) : 0;
    const statusRaw = statusFor(key, t, timeline); // V0.9.7.8.31: valore interno, mai tradotto, usato solo per confronti
    let status = statusLabel(statusRaw);
    if(isFinalPhase){
      status = statusRaw==='RITIRATO' ? window.t('status_retired_short') : '<img class=ico src=assets/icons/checkered_flag.png>';
    }
    // V0.9.9.12: distacco VERO, dal tempo cumulato reale della simulazione (non piu' una formula
    // finta legata solo alla posizione) — fallback alla vecchia formula solo se i dati non ci sono.
    let gap;
    if(i===0){
      gap = window.t('status_leader');
    } else if(statusRaw==='RITIRATO'){
      gap = '—';
    } else if(cumSnap && cumSnap[key]!=null && cumSnap[order[0]]!=null){
      gap = '+'+Math.max(0, cumSnap[key]-cumSnap[order[0]]).toFixed(1)+'s';
    } else {
      gap = '+'+(i*0.55 + (i%3)*0.2).toFixed(1)+'s';
    }
    return { key, index:i, pos:i+1, carNumber:e.carNumber, driverName:e.driverName, teamName:e.teamName, teamId:e.teamId, isPlayerTeam:e.isPlayerTeam, status, statusRaw, gap, delta };
  });
}

// V0.9.7.9.20: testo probabilita'/effetto sotto ogni scelta, in termini da corsa (non "resti fermo"
// ma "mantieni la posizione" ecc.) — cosi' il giocatore sa esattamente su cosa sta scommettendo.
function bucketsSummaryHTML(choiceKey){
  if(choiceKey==='splitstrategy'){
    const b1 = bucketsSummaryHTML('box'), b2 = bucketsSummaryHTML('stay');
    return `<div class="decision-split-row"><span class="dim mono" style="font-size:9.5px;">P1</span>${b1}</div><div class="decision-split-row"><span class="dim mono" style="font-size:9.5px;">P2</span>${b2}</div>`;
  }
  const buckets = DECISION_OUTCOME_BUCKETS[choiceKey];
  if(!buckets) return '';
  return buckets.map(b=>{
    const pct = Math.round(b.prob*100);
    const cls = b.label.startsWith('gain') ? 'bkt-gain' : (b.label.startsWith('lose') || b.label==='retired') ? 'bkt-lose' : 'bkt-hold';
    return `<span class="decision-bucket-chip ${cls}">${pct}% ${t('bkt_'+b.label)}</span>`;
  }).join('');
}

function liveDecisionRevealHTML(){
  const reveal = state.live.pendingReveal;
  const settled = reveal.stage==='settled';
  const highStakes = !!reveal.highStakes;
  const slotNames = {
    'PLAYER-1': state.team.pilotMain.nome,
    'PLAYER-2': state.isDriverCareer ? null : state.team.pilotSecond.nome,
  };
  const columnsHTML = Object.keys(reveal.outcomes).map(slotKey=>{
    const { bucketIdx, buckets, shift, timeBonus } = reveal.outcomes[slotKey];
    const activeIdx = reveal.highlightIdx[slotKey];
    const chipsHTML = buckets.map((b,i)=>{
      const cls = b.label.startsWith('gain') ? 'bkt-gain' : (b.label.startsWith('lose') || b.label==='retired') ? 'bkt-lose' : 'bkt-hold';
      let stateCls, text;
      if(settled){
        stateCls = i===bucketIdx ? 'reveal-winner' : 'reveal-dimmed';
        // V0.9.7.9.26: sulla chip vincente mostriamo il numero ESATTO uscito (es. "Guadagni 2
        // posizioni"), non piu' il range generico ("1-2") — quello serve solo prima di sapere.
        text = (i===bucketIdx) ? (shift!==0 ? t(buckets[bucketIdx].label.startsWith('gain') ? 'bkt_gain_exact' : 'bkt_lose_exact', Math.abs(shift))
          : (timeBonus ? t(timeBonus<0 ? 'bkt_gain_seconds' : 'bkt_lose_seconds', Math.abs(timeBonus).toFixed(1)) : t('bkt_hold'))) : t('bkt_'+b.label);
      } else {
        stateCls = i===activeIdx ? 'reveal-active' : 'reveal-idle';
        text = t('bkt_'+b.label);
      }
      return `<div class="decision-reveal-chip ${cls} ${stateCls}">${text}</div>`;
    }).join('');
    return `
    <div class="decision-reveal-col">
      <div class="decision-reveal-driver">${slotNames[slotKey] ? shortName(slotNames[slotKey]) : ''}</div>
      ${chipsHTML}
    </div>`;
  }).join('');
  const eyebrowText = highStakes ? t('dec_reveal_title_risky') : t('dec_reveal_title');
  return `
  <div class="decision-modal">
    <div class="decision-card decision-reveal-card ${highStakes?'decision-reveal-highstakes':''} ${settled?'decision-reveal-settled':''}">
      <div class="eyebrow ${highStakes && !settled?'reveal-eyebrow-risky':''}">${settled ? t('dec_reveal_title_done') : eyebrowText}</div>
      <div class="decision-reveal-row">${columnsHTML}</div>
    </div>
  </div>`;
}

function liveDecisionHTML(){
  if(state.live.pendingReveal) return liveDecisionRevealHTML();
  const dec = state.live.activeDecision;
  if(!dec) return '';
  const info = LIVE_DECISION_INFO[dec.type];
  // V0.9.9.112: DECISIONE COME EVENTO — stesso identico controllo usato per il suono, così testo e
  // trattamento visivo sono sempre coerenti tra loro.
  const isEvento = info.choices.some(c=>HIGH_STAKES_CHOICES.has(c.key));
  const choicesHTML = info.choices.map(c=>`
        <button class="ghost decision-btn" data-action="resolve-live-decision" data-choice="${c.key}">
          <div class="decision-btn-label">${c.label}</div>
          <div class="decision-btn-desc">${c.desc}</div>
          <div class="decision-bucket-row">${bucketsSummaryHTML(c.key)}</div>
        </button>`).join('');
  const timerEnabled = state.live.decisionDeadline!==null && state.live.decisionDeadline!==undefined;
  const timerHTML = timerEnabled ? `<div class="decision-timer-track"><div class="decision-timer-fill" id="decisionTimerFill"></div></div>` : '';
  return `
  <div class="decision-modal ${isEvento?'decision-modal-evento':''}">
    <div class="decision-card ${isEvento?'decision-card-evento':''}">
      <div class="eyebrow ${isEvento?'decision-eyebrow-evento':''}">${isEvento ? t('dec_evento_badge') : info.title}</div>
      ${isEvento ? `<div class="dim" style="font-size:10.5px;margin-top:-4px;margin-bottom:6px;">${info.title}</div>` : ''}
      <h3 class="hdr" style="font-size:20px;margin-top:6px;">${info.question}</h3>
      ${timerHTML}
      <div class="decision-choices">${choicesHTML}</div>
    </div>
  </div>`;
}

// V0.9.9.51: tempo sul giro plausibile, derivato dalla lunghezza del circuito (non e' il vero
// tempo usato dalla simulazione interna, e' una lettura pensata per il giocatore) + penalita' da
// usura gomme, cosi' la barra usura ha un effetto visibile e concreto, non solo estetico.
function liveLapTimeDisplay(circuit, tireWear){
  const baseSeconds = (circuit.lunghezza/205)*3600; // ~205km/h di passo medio, plausibile
  const wearPenalty = tireWear * 2.6; // fino a +2.6s col pieno consumo
  const total = baseSeconds + wearPenalty;
  const mins = Math.floor(total/60);
  const secs = (total%60).toFixed(3).padStart(6,'0');
  return `${mins}:${secs}`;
}
// V0.9.9.66: l'usura gomme in pratica non supera quasi mai il 50% — segnalato da Gio. La barra ora
// rappresenta visivamente l'intervallo 0-50% (50% di usura reale = barra piena), non 0-100%, e le
// soglie colore sono ricalibrate sullo stesso intervallo pratico (prima quasi sempre verde, perché
// le soglie 45%/75% erano tarate sul range teorico 0-100 mai davvero raggiunto).
function tireWearVisual(wear){
  const barWidthPct = Math.min(100, Math.round(wear*200)); // 50% di usura reale = barra piena
  const wearCls = wear>=0.35 ? 'tire-wear-high' : wear>=0.20 ? 'tire-wear-mid' : 'tire-wear-low';
  return { barWidthPct, wearCls };
}
function tireCardHTML(slotKey, timeline, phaseIdx, rows){
  const row = rows.find(r=>r.key===slotKey);
  if(!row) return '';
  const wear = timeline.tireWearByPhase
    ? interpolatePerPhaseValue(timeline.tireWearByPhase, Math.floor(phaseIdx), Math.ceil(phaseIdx), phaseIdx-Math.floor(phaseIdx), slotKey)
    : 0;
  const wearPct = Math.round(wear*100);
  const { barWidthPct, wearCls } = tireWearVisual(wear);
  const lapTime = liveLapTimeDisplay(timeline.circuit, wear);
  return `
  <div class="tire-card" id="tirecard-${slotKey}">
    <div class="tire-card-head">
      <span class="tire-card-pos">P${row.pos}</span>
      <span class="tire-card-name">${shortName(row.driverName)}</span>
      <span class="tire-card-lap mono">${lapTime}</span>
    </div>
    <div class="tire-wear-track">
      <div class="tire-wear-fill ${wearCls}" id="tirewear-${slotKey}" style="width:${barWidthPct}%;"></div>
    </div>
    <div class="tire-card-foot dim">${window.t('live_tire_wear_label')} ${wearPct}%</div>
  </div>`;
}
function tireCardsRowHTML(timeline, phaseIdx, rows){
  const slots = pedalSlotsForRun();
  return `<div class="tire-cards-row">${slots.map(s=>tireCardHTML(s,timeline,phaseIdx,rows)).join('')}</div>`;
}
