// V0.9.9.83: DAILY SEASON — pagina hub, raggiunta cliccando la carta dalla scelta modalità.
// Countdown + trofei del giorno, pulsante avvio (rispetta il limite gratuito/premium), accesso
// alle due classifiche (giornaliera e ponderata).
// V0.9.9.83: DAILY SEASON — classifica, sia giornaliera che ponderata. Le due viste SQL arrivano
// gia' ordinate con lo spareggio corretto — qui ci limitiamo a disegnarle.
// V0.9.9.115: SISTEMA AMICI — schermata principale: codice invito da condividere, campo per
// aggiungere un amico, lista amici con le 5 statistiche al click (stesso schema già collaudato
// della classifica Daily).
let __friendsListCache = [];
function renderFriendsHub(){
  app.innerHTML = `
  <div class="topbar">
    <div class="topbar-left-group">
      ${backChevronBtnHTML('friends-hub-back')}
      <div class="brand hdr">RACING DYNASTY<small>AMICI</small></div>
    </div>
  </div>
  <div class="wrap">
    <div class="panel">
      <div style="font-weight:700;margin-bottom:6px;">${t('friends_my_code_title')}</div>
      <div class="dim" style="font-size:12px;margin-bottom:10px;">${t('friends_my_code_desc')}</div>
      <div style="display:flex;gap:8px;align-items:center;">
        <div class="mono" id="myFriendCodeDisplay" style="flex:1;background:var(--panel2);border:1px solid var(--line);border-radius:6px;padding:10px 12px;font-size:16px;letter-spacing:0.05em;text-align:center;">···</div>
        <button class="ghost" data-action="copy-friend-code" style="flex-shrink:0;">${t('friends_copy_code')}</button>
        <button class="primary" data-action="share-friend-code" style="flex-shrink:0;">${t('friends_share_btn')}</button>
      </div>
    </div>
    <div class="panel" style="margin-top:12px;">
      <div style="font-weight:700;margin-bottom:6px;">${t('friends_add_title')}</div>
      <div style="display:flex;gap:8px;">
        <input type="text" id="friendCodeInput" maxlength="12" autocomplete="off" spellcheck="false"
          placeholder="RD-XXXXXX" style="flex:1;background:var(--panel2);border:1px solid var(--line);border-radius:6px;padding:10px 12px;color:var(--text);font-family:var(--font-mono);text-transform:uppercase;">
        <button class="primary" data-action="submit-friend-code" style="flex-shrink:0;">${t('friends_add_btn')}</button>
      </div>
      <div class="dim" id="friendCodeError" style="font-size:12px;color:var(--danger);margin-top:8px;min-height:16px;"></div>
    </div>
    <div class="panel" style="margin-top:12px;">
      <div style="font-weight:700;margin-bottom:10px;">${t('friends_list_title')}</div>
      <div id="friendsListContent" class="dim" style="text-align:center;padding:20px 0;">${t('friends_list_loading')}</div>
    </div>
  </div>`;
  bindActions();
  getOrCreateMyFriendCode().then(codice=>{
    const el = document.getElementById('myFriendCodeDisplay');
    if(el) el.textContent = codice || t('friends_code_error');
  });
  loadMyFriendsList().then(lista=>{
    __friendsListCache = lista;
    const el = document.getElementById('friendsListContent');
    if(!el) return;
    if(lista.length===0){ el.innerHTML = `<div class="dim">${t('friends_list_empty')}</div>`; return; }
    el.innerHTML = lista.map((f,i)=>`
      <div class="daily-leaderboard-row" data-action="toggle-friend-detail" data-friend-idx="${i}" style="cursor:pointer;">
        <span class="daily-leaderboard-nick">${f.nickname || t('friends_unknown_nick')}${premiumBadgeHTML(f.is_premium)}</span>
        <span class="daily-leaderboard-score">${f.rating_medio!=null ? Math.round(f.rating_medio).toLocaleString('it-IT') : '—'}</span>
      </div>
      <div class="daily-leaderboard-detail" id="friendDetail${i}" style="display:none;"></div>
    `).join('');
    bindActions();
  });
}
// V0.9.9.127: SCHERMATA "IL MIO PROFILO" — richiesto da Gio ("una tessera come quella degli amici
// con tutte le statistiche con una icona matita per modificare il nick, max una volta ogni 30
// giorni"). Le 5 statistiche sono le STESSE della scheda amico, ma calcolate direttamente dai dati
// locali (non serve interrogare il cloud, sono già qui).
function renderMyProfile(){
  const stats = computePublicStats();
  const nickname = dailyNicknameCache?.nickname || t('friends_unknown_nick');
  const nazioneAttuale = Object.keys(COUNTRY_FLAG).find(c => COUNTRY_FLAG[c] === (dailyNicknameCache?.flag_code)) || null;
  const giorniAttesa = daysUntilNicknameCanChange();
  app.innerHTML = `
  <div class="topbar">
    <div class="topbar-left-group">
      ${backChevronBtnHTML('my-profile-hub-back')}
      <div class="brand hdr">RACING DYNASTY<small>${t('profile_title')}</small></div>
    </div>
  </div>
  <div class="wrap">
    <div class="panel">
      <div style="display:flex;align-items:center;justify-content:center;gap:10px;">
        ${nazioneAttuale ? `<span style="font-size:20px;flex-shrink:0;">${flag(nazioneAttuale)}</span>` : ''}
        <div style="font-size:22px;font-weight:800;">${nickname}</div>
        <button class="ghost" data-action="open-edit-nickname" style="padding:6px 10px;flex-shrink:0;" aria-label="${t('profile_edit_nickname')}">✏️</button>
      </div>
      ${giorniAttesa>0 ? `<div class="dim" style="text-align:center;font-size:11px;margin-top:6px;">${t('profile_nickname_cooldown', giorniAttesa)}</div>` : ''}
    </div>
    <div class="panel" style="margin-top:12px;">
      <div class="daily-detail-row"><span class="dim">${t('friends_stat_wins')}</span><span>${stats.circuiti_vinti}</span></div>
      <div class="daily-detail-row"><span class="dim">${t('friends_stat_missing_trophies')}</span><span>${Math.max(0, stats.circuiti_totali - stats.circuiti_vinti)}</span></div>
      <div class="daily-detail-row"><span class="dim">${t('friends_stat_museum')}</span><span>${stats.completamento_museo_pct}%</span></div>
      <div class="daily-detail-row"><span class="dim">${t('friends_stat_achievements')}</span><span>${stats.obiettivi_sbloccati}/${stats.obiettivi_totali}</span></div>
    </div>
  </div>`;
  bindActions();
}
// V0.9.9.131: badge premium (moneta D) — richiesto da Gio, "sia nelle classifiche che nella lista
// amici usiamo la moneta D come badge per chi ha premium". Funzione unica riusata ovunque serva.
function premiumBadgeHTML(isPremium){
  return isPremium ? `<img class="dynasty-dollar-icon premium-badge-icon" src="assets/currency/dynasty_dollar.png" alt="Premium" title="${t('premium_badge_tooltip')}">` : '';
}
function friendDetailHTML(f){
  if(f.nonSincronizzato){
    return `<div class="dim" style="text-align:center;padding:10px 6px;font-size:12.5px;line-height:1.5;">${t('friends_not_synced_yet')}</div>
    <div class="btnrow" style="margin-top:8px;"><button class="ghost" data-action="remove-friend" data-friend-user-id="${f.user_id}" style="width:100%;font-size:11.5px;color:var(--danger);border-color:var(--danger);">${t('friends_remove_btn')}</button></div>`;
  }
  const righe = [
    [t('friends_stat_wins'), `${f.circuiti_vinti}`],
    [t('friends_stat_missing_trophies'), `${Math.max(0, f.circuiti_totali - f.circuiti_vinti)}`],
    [t('friends_stat_museum'), `${f.completamento_museo_pct}%`],
    [t('friends_stat_achievements'), `${f.obiettivi_sbloccati}/${f.obiettivi_totali}`],
    [t('friends_stat_rating'), f.rating_medio!=null ? Math.round(f.rating_medio).toLocaleString('it-IT') : '—'],
  ];
  return righe.map(([label,val])=>`<div class="daily-detail-row"><span class="dim">${label}</span><span>${val}</span></div>`).join('')
    + `<div class="btnrow" style="margin-top:8px;"><button class="ghost" data-action="remove-friend" data-friend-user-id="${f.user_id}" style="width:100%;font-size:11.5px;color:var(--danger);border-color:var(--danger);">${t('friends_remove_btn')}</button></div>`;
}

function renderDailyLeaderboard(tab){
  tab = tab || state.dailyLeaderboardTab || 'daily';
  state.dailyLeaderboardTab = tab;
  const titoloTab = tab==='daily' ? t('daily_hub_leaderboard_live') : tab==='yesterday' ? t('daily_hub_leaderboard_yesterday') : t('daily_hub_leaderboard_weighted');
  app.innerHTML = `
  <div class="topbar">
    <div class="topbar-left-group">
      ${backChevronBtnHTML('open-daily-season-hub')}
      <div class="brand hdr">RACING DYNASTY<small>DAILY SEASON — ${titoloTab}</small></div>
    </div>
  </div>
  <div class="wrap">
    <div class="btnrow" style="margin-bottom:14px;">
      <button class="${tab==='daily'?'primary':'ghost'}" data-action="open-daily-leaderboard" data-tab="daily" style="flex:1;font-size:12px;"><span class="live-dot"></span>${t('daily_hub_leaderboard_live')}</button>
      <button class="${tab==='yesterday'?'primary':'ghost'}" data-action="open-daily-leaderboard" data-tab="yesterday" style="flex:1;font-size:12px;">${t('daily_hub_leaderboard_yesterday')}</button>
      <button class="${tab==='weighted'?'primary':'ghost'}" data-action="open-daily-leaderboard" data-tab="weighted" style="flex:1;font-size:12px;">${t('daily_hub_leaderboard_weighted')}</button>
    </div>
    <div id="dailyLeaderboardContent" class="dim" style="text-align:center;padding:30px 0;">${t('daily_leaderboard_loading')}</div>
  </div>`;
  bindActions();
  loadAndRenderDailyLeaderboard(tab);
}
async function loadAndRenderDailyLeaderboard(tab){
  const contentEl = document.getElementById('dailyLeaderboardContent');
  if(!contentEl) return; // schermata gia' cambiata
  if(!supabaseClient){ contentEl.innerHTML = `<div class="dim">${t('daily_leaderboard_error')}</div>`; return; }
  try{
    const idAmiciSet = await loadMyFriendIdsSet(); // V0.9.9.117: per evidenziare gli amici in viola
    let rows;
    let mioBloccoSeparatoHTML = ''; // V0.9.9.206: riempito sotto solo se il giocatore non rientra nella top 100 mostrata
    if(tab==='daily' || tab==='yesterday'){
      const dataRiferimento = tab==='daily' ? todayDateStringUTC() : previousDailyDateString(todayDateStringUTC());
      // V0.9.9.206: D7 (audit tecnico) — richiesto da Gio in vista del lancio pubblico: "top 100 +
      // la mia posizione evidenziata separatamente" invece di scaricare sempre tutta la classifica,
      // che con molti giocatori potrebbe crescere senza limite.
      let { data, error } = await supabaseClient.from('daily_leaderboard_view')
        .select('user_id, nickname, flag_code, points, budget_saved, components_sum, rerolls_left, completed_at, driver_position, constructor_position, gap_from_rival, initial_rating, platinum_parts, attempt_number, final_score')
        .eq('daily_date', dataRiferimento)
        .order('final_score', { ascending:false })
        .limit(100);
      if(error){
        console.warn('Lettura classifica col nuovo punteggio non riuscita, riprovo con quello vecchio:', error.message);
        const retry = await supabaseClient.from('daily_leaderboard_view')
          .select('user_id, nickname, flag_code, points, budget_saved, components_sum, rerolls_left, completed_at')
          .eq('daily_date', dataRiferimento)
          .order('points', { ascending:false }).order('budget_saved', { ascending:false })
          .order('components_sum', { ascending:false }).order('rerolls_left', { ascending:false })
          .order('completed_at', { ascending:true })
          .limit(100);
        data = retry.data; error = retry.error;
      }
      if(error) throw error;
      // V0.9.9.104: mescoliamo i giocatori veri con i 50 bot del giorno (tutti visibili se e' "ieri",
      // solo quelli il cui orario di comparsa e' gia' passato se e' "oggi/live") — poi riordiniamo
      // tutti insieme per punteggio finale, cosi' i bot si intrecciano nella classifica vera invece
      // di stare per forza in fondo o in cima.
      const bot = visibleDailyBotsForDate(dataRiferimento);
      rows = [...(data||[]), ...bot].sort((a,b)=> computeDailyFinalScore(b) - computeDailyFinalScore(a)).slice(0,100);
      // se il giocatore loggato non rientra tra i primi 100 mostrati, calcoliamo la sua vera
      // posizione separatamente (stesso metodo efficiente di loadDailyBestResultToday, mai
      // scaricando l'intera classifica) e la mostriamo in un blocco a parte sotto la lista
      if(currentUser && !rows.some(r=>r.user_id===currentUser.id)){
        const mioRisultato = await loadDailyBestResultToday();
        if(mioRisultato && mioRisultato.daily_date===dataRiferimento){
          mioBloccoSeparatoHTML = `
            <div class="dim" style="text-align:center;font-size:11px;letter-spacing:0.06em;margin:14px 0 6px;">${t('daily_your_position_label')}</div>
            <div class="daily-leaderboard-row daily-leaderboard-row-mine">
              <span class="daily-leaderboard-rank">${mioRisultato.rank}</span>
              <span class="daily-leaderboard-nick">${dailyNicknameCache?.nickname || t('friends_unknown_nick')}</span>
              <span class="daily-leaderboard-stat daily-leaderboard-score">${computeDailyFinalScore(mioRisultato).toLocaleString('it-IT')}</span>
            </div>`;
        }
      }
    } else {
      const { data, error } = await supabaseClient.from('daily_weighted_leaderboard_view')
        .select('user_id, nickname, flag_code, giorni_giocati, rating_medio')
        .order('rating_medio', { ascending:false });
      if(error) throw error;
      rows = (data||[]);
    }
    const el = document.getElementById('dailyLeaderboardContent'); // ricontrolla, l'attesa potrebbe averla rimossa
    if(!el) return;
    const isDettagliata = tab==='daily' || tab==='yesterday';
    if(rows.length===0){ el.innerHTML = `<div class="dim">${t(isDettagliata ? 'daily_leaderboard_empty' : 'daily_leaderboard_weighted_empty')}</div>`; return; }
    el.className = '';
    // V0.9.9.131: badge premium (moneta D) — escludiamo i bot (mai premium reale, e non hanno un
    // vero user_id da cercare nel database).
    const idVeriMostrati = rows.filter(r=>!r.isBot).map(r=>r.user_id);
    const idPremiumSet = await loadPremiumUserIdsSet(idVeriMostrati);
    // V0.9.9.103: righe della classifica giornaliera cliccabili — al tocco mostrano i valori
    // "splittati" (tutti i 7 fattori separati) invece del solo totale, richiesto da Gio.
    __dailyLeaderboardRowsCache = rows;
    el.innerHTML = rows.map((r,i)=>{
      const posizione = i+1;
      const mio = currentUser && r.user_id===currentUser.id;
      const statoText = isDettagliata
        ? computeDailyFinalScore(r).toLocaleString('it-IT')
        : `${Math.round(r.rating_medio).toLocaleString('it-IT')} · ${r.giorni_giocati}g`;
      const clickAttr = isDettagliata ? `data-action="toggle-daily-row-detail" data-row-idx="${i}"` : '';
      // V0.9.9.111: più risalto allo score (non più "dim", ora grassetto e colorato), coccarda per
      // i primi 3, sfondo distinto per la top 10 — richiesto da Gio dopo i test dal vivo.
      const coccarda = posizione===1?'🥇':posizione===2?'🥈':posizione===3?'🥉':'';
      const classeTop10 = posizione<=10 ? 'daily-leaderboard-row-top10' : '';
      // V0.9.9.117: badge "AMICI" in viola (stesso colore già usato per i rivali), richiesto da Gio
      const badgeAmico = idAmiciSet.has(r.user_id) ? `<span class="friend-badge">${t('friends_badge_label')}</span>` : '';
      const badgePremium = premiumBadgeHTML(idPremiumSet.has(r.user_id));
      return `<div class="daily-leaderboard-row ${classeTop10} ${mio?'daily-leaderboard-row-mine':''}" ${clickAttr} style="${isDettagliata?'cursor:pointer;':''}">
        <span class="daily-leaderboard-rank">${coccarda || posizione}</span>
        ${flag(nationFromFlagCode(r.flag_code))}
        <span class="daily-leaderboard-nick">${r.nickname}${badgeAmico}${badgePremium}</span>
        <span class="daily-leaderboard-stat daily-leaderboard-score">${statoText}</span>
      </div>
      <div class="daily-leaderboard-detail" id="dailyRowDetail${i}" style="display:none;"></div>`;
    }).join('') + mioBloccoSeparatoHTML;
    if(isDettagliata) bindActions(); // V0.9.9.103: le righe sono ora cliccabili, servono i listener veri
  }catch(e){
    const el = document.getElementById('dailyLeaderboardContent');
    if(el) el.innerHTML = `<div class="dim">${t('daily_leaderboard_error')}</div>`;
    console.warn('Caricamento classifica Daily non riuscito:', e);
  }
}
let __dailyLeaderboardRowsCache = [];
function dailyRowDetailHTML(r){
  const righe = [
    [t('daily_detail_points'), `${r.points ?? '—'} pt`],
    [t('daily_detail_driver_pos'), r.driver_position ? `P${r.driver_position}/20` : '—'],
    [t('daily_detail_constructor_pos'), r.constructor_position ? `P${r.constructor_position}/10` : '—'],
    [t('daily_detail_gap'), r.gap_from_rival!=null ? (r.gap_from_rival>0?'+':'')+r.gap_from_rival+' pt' : '—'],
    [t('daily_detail_budget'), r.budget_saved!=null ? fmtM(r.budget_saved) : '—'],
    [t('daily_detail_rating'), (r.initial_rating!=null && r.components_sum!=null) ? `${r.initial_rating} → ${r.components_sum}` : '—'],
    [t('daily_detail_platinum'), r.platinum_parts!=null ? `${r.platinum_parts}/5` : '—'],
  ];
  return righe.map(([label,val])=>`<div class="daily-detail-row"><span class="dim">${label}</span><span>${val}</span></div>`).join('');
}
function nationFromFlagCode(code){
  const entry = Object.entries(COUNTRY_FLAG).find(([nome,c])=>c===code);
  return entry ? entry[0] : 'Sconosciuta';
}
