// V0.9.7.8.27: seleziona titolo/descrizione dell'obiettivo nella lingua corrente — fallback
// automatico all'italiano se manca la traduzione per quella lingua (non dovrebbe succedere, tutti
// e 50 sono tradotti, ma e' una sicurezza).
function achText(ach){
  if(!ach) return { title:'', desc:'' };
  if(currentLang!=='it' && ach[currentLang]) return ach[currentLang];
  return { title:ach.title, desc:ach.desc };
}
const ACHIEVEMENT_SAVE_KEY = 'racingDynastyAchievementsV1';
const ACHIEVEMENT_DATA_DEFAULTS = {
  unlockedIds:[], circuitsRaced:[],
  goatObtainedViaDraft:false, goatObtainedViaScouting:false, // V0.9.7.9: fortuna-sfacciata
  hardcoreWinStreak:0,                                        // V0.9.7.9: dinastia (stagioni Hardcore vinte di fila)
  rivalsThatBeatMe:[],                                        // V0.9.7.9: rivincita (nomi scuderie rivali che ci hanno battuto)
  circuitTypesWon:[],                                         // V0.9.7.9: padrone-di-ogni-asfalto
  synergyHighlightShown:false,                                 // V0.9.7.8.6: highlight semaforo alla prima sinergia
};
function loadAchievementData(){
  try{
    const raw = localStorage.getItem(ACHIEVEMENT_SAVE_KEY);
    // V0.9.8.16: copia PROFONDA dei default (non superficiale) — con lo spread semplice gli array
    // annidati (unlockedIds ecc.) restavano condivisi per riferimento tra tutte le chiamate,
    // mutando permanentemente il modello di default stesso alla prima .push()
    const freshDefaults = JSON.parse(JSON.stringify(ACHIEVEMENT_DATA_DEFAULTS));
    return raw ? { ...freshDefaults, ...JSON.parse(raw) } : freshDefaults;
  }catch(e){ return JSON.parse(JSON.stringify(ACHIEVEMENT_DATA_DEFAULTS)); }
}
function saveAchievementData(){
  if(state && (state.isTutorialRun || state.isDailySeason)) return; // V0.9.9.71: il tutorial non scrive nessun progresso vero
  try{ localStorage.setItem(ACHIEVEMENT_SAVE_KEY, JSON.stringify(achievementData)); }catch(e){ /* ignorato */ }
  touchLocalProgress(); pushSaveToCloud(); pushPublicStatsToCloud();
}
let achievementData = loadAchievementData();
// V0.9.7.8.7: FIX — un obiettivo gia' sbloccato PRIMA che esistesse questo aggancio (partite
// precedenti, o semplicemente ottenuto prima di aprire il Garage nella stessa sessione) non faceva
// mai scattare lo sblocco della livrea, perche' il codice sotto (in unlockAchievement) reagisce solo
// al MOMENTO in cui un obiettivo diventa nuovo. Qui invece riconciliamo sempre tutto lo stato
// gia' esistente, cosi' non conta quando l'obiettivo e' stato ottenuto.
function syncLiveryUnlocksFromAchievements(){
  let changed = false;
  LIVERY_PATTERNS.forEach(p=>{
    if(achievementData.unlockedIds.includes(p.achievementId) && !liveryData.unlockedPatternIds.includes(p.id)){
      liveryData.unlockedPatternIds.push(p.id);
      changed = true;
    }
  });
  if(changed) saveLiveryData();
}
syncLiveryUnlocksFromAchievements();
let __lastUnlockedAchievements = []; // per mostrare un piccolo avviso dopo l'ultimo sblocco
function unlockAchievement(id){
  if(state && (state.isTutorialRun || state.isDailySeason)) return; // V0.9.9.70: il tutorial non scrive nessun progresso vero
  if(!achievementData.unlockedIds.includes(id)){
    achievementData.unlockedIds.push(id);
    __lastUnlockedAchievements.push(id);
    saveAchievementData();
    showAchievementToast(id);
    // V0.9.7.8.5: se questo obiettivo sblocca anche un pattern livrea nel Garage, lo sblocchiamo
    // permanentemente qui, un colpo solo, cosi' resta valido qualsiasi punto del codice lo scateni.
    const liveryPattern = LIVERY_PATTERNS.find(p=>p.achievementId===id);
    if(liveryPattern && !liveryData.unlockedPatternIds.includes(liveryPattern.id)){
      liveryData.unlockedPatternIds.push(liveryPattern.id);
      saveLiveryData();
    }
    // V0.9.7.9: enciclopedia-vivente si sblocca da sola quando tutti gli altri 49 sono stati ottenuti
    if(id!=='enciclopedia-vivente'){
      const others = ACHIEVEMENTS.filter(a=>a.id!=='enciclopedia-vivente');
      if(others.every(a=> achievementData.unlockedIds.includes(a.id))) unlockAchievement('enciclopedia-vivente');
    }
  }
}
// V0.9.7.2: notifica "Obiettivo Sbloccato" in basso a destra — funziona indipendentemente dalla
// schermata su cui ci si trova (appesa a document.body, fuori dal normale ciclo di render, si
// rimuove da sola dopo qualche secondo con la sua animazione CSS: non serve alcuna pulizia manuale).
function showAchievementToast(id){
  const ach = ACHIEVEMENTS.find(a=>a.id===id);
  if(!ach) return;
  const achLoc = achText(ach);
  playSfx('notify_generic'); // V0.9.7.8.2
  let container = document.getElementById('achievementToastContainer');
  if(!container){
    container = document.createElement('div');
    container.id = 'achievementToastContainer';
    document.body.appendChild(container);
  }
  const toast = document.createElement('div');
  toast.className = 'achievement-toast';
  const iconSrc = `<img src="assets/achievements/${id}.webp" alt="">`;
  toast.innerHTML = `
    <div class="achievement-toast-icon">${iconSrc}</div>
    <div class="achievement-toast-body">
      <div class="achievement-toast-eyebrow">${t('achievement_unlocked_label')}</div>
      <div class="achievement-toast-title">${achLoc.title}</div>
    </div>`;
  container.appendChild(toast);
  // V0.9.7.9: click sul banner -> apre la schermata Obiettivi scrollata sulla card appena sbloccata
  toast.addEventListener('click', ()=>{
    if(toast.parentNode) toast.parentNode.removeChild(toast);
    openAchievements(id);
  });
  setTimeout(()=>{ if(toast.parentNode) toast.parentNode.removeChild(toast); }, 5100);
}
function isAchievementUnlocked(id){ return achievementData.unlockedIds.includes(id); }
function recordCircuitRaced(circuitName){
  if(!achievementData.circuitsRaced.includes(circuitName)){
    achievementData.circuitsRaced.push(circuitName);
    saveAchievementData();
  }
}

// V0.9.7.9: obiettivi legati alle sinergie — controllati ogni volta che la squadra cambia composizione
function checkSynergyAchievements(){
  if(state && (state.isTutorialRun || state.isDailySeason)) return; // V0.9.9.71: il tutorial non scrive nessun progresso vero
  const t = state.team;
  if(!t) return;
  const pairs = activeSynergyPairs();
  if(pairs.length>0){
    unlockAchievement('prima-scintilla');
    // V0.9.7.8.6: la primissima volta in assoluto che una sinergia si attiva, il semaforo si
    // evidenzia per qualche secondo — dopo va tolto per non richiamare l'attenzione ogni volta.
    if(!achievementData.synergyHighlightShown){
      achievementData.synergyHighlightShown = true;
      saveAchievementData();
      state._synergyJustUnlocked = true;
    }
  }
  const groups = {};
  pairs.forEach(([a,b])=>{ groups[a.mentId] = (groups[a.mentId]||0)+1; });
  if(Object.values(groups).some(n=>n>=2)) unlockAchievement('coro-a-due-voci');
  if(t._synergyDiverseFire) unlockAchievement('scintilla-collettiva');
  if((t._synergyStackPct||0) >= 0.90) unlockAchievement('risonanza-totale');
}

// V0.9.7: obiettivo "Cenerentola" — controllato subito al momento della vittoria, non a fine stagione
function checkCenerentolaAchievement(){
  if(isAchievementUnlocked('cenerentola')) return;
  if(computeTeamStrength(state.team) <= 60) unlockAchievement('cenerentola');
}

// V0.9.7: obiettivi di Maestria — controllati ogni volta che museo/trofei/circuiti cambiano,
// cosi' si sbloccano nel momento esatto in cui la condizione diventa vera, non solo a fine stagione
function checkMasteryAchievements(){
  if(state && (state.isTutorialRun || state.isDailySeason)) return; // V0.9.9.71: il tutorial non scrive nessun progresso vero
  if(!isAchievementUnlocked('turista-instancabile')){
    if(achievementData.circuitsRaced.length >= 10) unlockAchievement('turista-instancabile');
  }
  if(!isAchievementUnlocked('meta-sala-trofei')){
    const wonCount = Object.values(trophyData).filter(t=>t.won>0).length;
    if(wonCount >= 5) unlockAchievement('meta-sala-trofei');
  }
  if(!isAchievementUnlocked('collezionista-assoluto')){
    const allGold = DATA.circuiti.every(c=> trophyData[c.nome] && trophyData[c.nome].won>0);
    if(allGold) unlockAchievement('collezionista-assoluto');
  }
  if(!isAchievementUnlocked('anima-della-scuderia')){
    const totalPiloti = DATA.piloti.length;
    const totalComponenti = DATA.motori.length + DATA.telai.length + DATA.aero.length + DATA.gomme.length + DATA.strategi.length;
    const havePiloti = Object.keys(museumData.piloti||{}).length;
    const haveComponenti = Object.keys(museumData.componenti||{}).length;
    if(havePiloti>=totalPiloti && haveComponenti>=totalComponenti) unlockAchievement('anima-della-scuderia');
  }
  if(!isAchievementUnlocked('padrone-di-ogni-asfalto')){
    const allTypes = Array.from(new Set(DATA.circuiti.map(c=>c.tipo)));
    if(allTypes.every(t=> achievementData.circuitTypesWon.includes(t))) unlockAchievement('padrone-di-ogni-asfalto');
  }
}

// V0.9.7: obiettivi legati alla fine di una stagione — un solo controllo, alla transizione verso 'season_end'
function checkSeasonEndAchievements(){
  const dstd = driverStandingsSorted();
  const cstd = constructorStandingsSorted();
  const isDriverChamp = dstd[0] && dstd[0].isPlayerTeam;
  const isConstructorChamp = cstd[0] && cstd[0].teamId==='PLAYER';
  const isHardcore = state.difficulty==='hardcore';
  const isFullSeason = state.seasonLength===20;
  const wonEveryRace = (state.playerRaceWinsCount||0) >= state.calendar.length;
  const startRating = state.initialTeamRatingAtDraft;

  // completamento carriera / traguardi base
  if(state.seasonLength===10) unlockAchievement('traguardo-raggiunto');
  if(isFullSeason && isDriverChamp) unlockAchievement('maratoneta');
  if(!isDriverChamp && !isConstructorChamp) unlockAchievement('partecipazione-onesta');

  // stagione / dominio
  if(isDriverChamp && isConstructorChamp) unlockAchievement('doppietta-perfetta');
  // V0.9.9.96: DAILY SEASON — tracciamento separato dei due titoli, indipendenti tra loro (non serve
  // più vincerli nella stessa stagione, come chiarito da Gio: "posso farle anche tutte e due insieme"
  // implicava che farle insieme fosse un modo IN PIÙ, non l'unico). Usato sia per lo sblocco della
  // Daily Season sia per i due indicatori rapidi mostrati sulla carta.
  if(!state.isTutorialRun && !state.isDailySeason){
    if(isConstructorChamp && !achievementData.everWonConstructorTitle){
      achievementData.everWonConstructorTitle = true; saveAchievementData();
    }
    if(isDriverChamp && !achievementData.everWonDriverTitle){
      achievementData.everWonDriverTitle = true; saveAchievementData();
    }
  }
  if(wonEveryRace) unlockAchievement('dominio-assoluto');
  if(isConstructorChamp && typeof startRating==='number' && startRating<55) unlockAchievement('dal-nulla-all-olimpo');
  if(isConstructorChamp && state.budget < 5) unlockAchievement('ultimo-centesimo');
  if(isConstructorChamp && !state.everLedDriverStandingsP1) unlockAchievement('lavoro-di-squadra');

  // Hardcore
  if(isDriverChamp && isHardcore) unlockAchievement('senza-rete-di-sicurezza');
  if(isDriverChamp && isConstructorChamp && isHardcore) unlockAchievement('il-migliore-che-ci-sia');
  if(isHardcore && !state.everUsedScouting && !state.everSwappedPilot) unlockAchievement('osso-duro');
  if(isHardcore && isFullSeason && !state.everFinishedOffPodium) unlockAchievement('costanza-chirurgica');
  if(isHardcore && isFullSeason && isDriverChamp && isConstructorChamp && typeof startRating==='number' && startRating<60) unlockAchievement('l-impossibile-fatto-possibile');
  if(isHardcore && wonEveryRace && !state.everLostLeadInFinalPhase) unlockAchievement('terrore-della-griglia');
  if(isHardcore && isConstructorChamp && !state.everUsedEpicOrHigher) unlockAchievement('con-quello-che-c-e');

  // stile
  if(!state.everUsedScoutingOnComponent) unlockAchievement('fedele-alla-linea-di-partenza');
  if(state.everUsedMaxRiskOnly && (state.upgradesPurchasedCount||0)>0) unlockAchievement('tutto-o-niente');

  // THE GOAT
  const goatIsChampDriver = isDriverChamp && dstd[0].nome==='THE GOAT';
  if(goatIsChampDriver && !state.goatMalusTriggeredThisSeason) unlockAchievement('infallibile');

  // il mito assoluto: tutto insieme, nella stessa stagione — "sempre primi in entrambe le classifiche"
  // e' approssimato con "non ha mai perso una gara" (wonEveryRace), la condizione piu' vicina e verificabile
  // con i dati che teniamo davvero: se vinci ogni gara, sei stato in testa a entrambe le classifiche per l'intera stagione.
  const hasGoatInTeam = (state.team.pilotMain && state.team.pilotMain.nome==='THE GOAT') || (state.team.pilotSecond && state.team.pilotSecond.nome==='THE GOAT');
  if(isHardcore && isFullSeason && isDriverChamp && isConstructorChamp && hasGoatInTeam && !state.everSwappedPilot && wonEveryRace){
    unlockAchievement('il-mito-assoluto');
  }

  // dinastia: streak di stagioni Hardcore vinte consecutivamente (persistente tra carriere)
  if(isHardcore){
    if(isDriverChamp || isConstructorChamp) achievementData.hardcoreWinStreak = (achievementData.hardcoreWinStreak||0) + 1;
    else achievementData.hardcoreWinStreak = 0;
    if(achievementData.hardcoreWinStreak >= 5) unlockAchievement('dinastia');
  }

  // rivincita: una rivale che in una carriera precedente ci aveva battuto, ora viene battuta
  const playerConstructorPoints = (cstd.find(c=>c.teamId==='PLAYER')||{points:0}).points;
  (state.rivals||[]).forEach(rid=>{
    const rt = state.constructorStandings[rid];
    if(!rt) return;
    if(rt.points > playerConstructorPoints){
      if(!achievementData.rivalsThatBeatMe.includes(rt.nome)) achievementData.rivalsThatBeatMe.push(rt.nome);
    } else if(isConstructorChamp && achievementData.rivalsThatBeatMe.includes(rt.nome)){
      unlockAchievement('rivincita');
      achievementData.rivalsThatBeatMe = achievementData.rivalsThatBeatMe.filter(n=>n!==rt.nome);
    }
  });
  saveAchievementData();
}



const SAVE_KEY = 'racingDynastySaveV09';

// ============================================================
// V0.9.8.2 — SALVATAGGIO CLOUD. Attivo solo se loggati (currentUser valorizzato). Il salvataggio
// locale resta sempre la fonte "immediata" (mai bloccare il gioco per una chiamata di rete);
// quello cloud e' una copia di sicurezza che si aggiorna con un piccolo ritardo, e viene
// confrontato per data ad ogni login per capire quale versione tenere.
// ============================================================
// ============================================================
// V0.9.8.3 — GETTONI GRATUITI + STATO PREMIUM.
// Gettoni: 2x Stagione Scuderia 10 gare + 1x da 20 gare, tracciati sul dispositivo (localStorage,
// come deciso — chi bara cancellando i dati perde anche trofei/obiettivi/progressi, deterrente
// naturale). Al primo utilizzo di un gettone parte un conto di 12h; allo scadere si ricarica tutto
// insieme, non gettone per gettone.
// Premium: letto dal server (tabella 'profiles'), mai scrivibile dal gioco stesso — solo un
// pagamento confermato lato server puo' cambiarlo. Se premium, i gettoni non contano piu': tutto
// illimitato.
// ============================================================
const TOKEN_STATE_KEY = 'racingDynastyTokensV1';
const TOKEN_REFILL_MS = 12*60*60*1000; // 12 ore
const FULL_TOKENS = { t10:2, t20:1 };
let isPremiumUser = false; // aggiornato dopo il login, leggendo la tabella 'profiles'
// V0.9.9.95: DAILY SEASON — sblocco richiesto da Gio: 10 obiettivi diversi vinti in qualunque
// modalità, E almeno una doppietta (titolo pilota + titolo scuderia insieme, anche nella stessa
// stagione) in una Stagione Scuderia normale. Riusa l'obiettivo 'doppietta-perfetta' già esistente
// — ora che achievement/museo/trofei sono bloccati anche durante la Daily (appena corretto), non
// può mai essere vinto DENTRO una Daily, quindi la condizione resta sempre "stagione scuderia vera".
const DAILY_UNLOCK_TROPHY_COUNT = 10;
// V0.9.9.123: BUG CORRETTO — segnalato da un tester con screenshot (13/10 pur avendo vinto solo 3
// gare su 10). Questa funzione contava achievementData.unlockedIds.length (OBIETTIVI generali
// sbloccati, es. "prima gara giocata"), non i trofei VINTI come dice esplicitamente il testo
// mostrato ("Ti mancano N trofei vinti"). Corretto contando i circuiti dove trophyData[nome].won
// è almeno 1 — il vero significato di "trofeo vinto".
function dailySeasonTrophiesUnlockedCount(){
  return Object.values(trophyData).filter(c => (c.won||0) > 0).length;
}
function hasWonConstructorTitle(){ return !!achievementData.everWonConstructorTitle || achievementData.unlockedIds.includes('doppietta-perfetta'); }
function hasWonDriverTitle(){ return !!achievementData.everWonDriverTitle || achievementData.unlockedIds.includes('doppietta-perfetta'); }
function isDailySeasonUnlocked(){
  // V0.9.9.126: richiesto anche il login — richiesto da Gio ("senza login nessun accesso alla
  // scheda daily, la si vede grigia, senza obiettivi per sbloccarla"). Prima i requisiti si
  // basavano solo su dati locali (trofei/obiettivi), che esistono anche senza account, mostrando
  // progressi che poi comunque non bastavano a giocare davvero (serve il login per salvare i
  // risultati Daily).
  if(!currentUser) return false;
  return dailySeasonTrophiesUnlockedCount() >= DAILY_UNLOCK_TROPHY_COUNT
    && hasWonConstructorTitle() && hasWonDriverTitle();
}
function dailySeasonLockedMessageHTML(){
  if(!currentUser){
    return `<div>${t('daily_locked_need_login')}</div>`;
  }
  const missingTrophies = Math.max(0, DAILY_UNLOCK_TROPHY_COUNT - dailySeasonTrophiesUnlockedCount());
  const missingConstructor = !hasWonConstructorTitle();
  const missingDriver = !hasWonDriverTitle();
  const parti = [];
  if(missingTrophies>0) parti.push(t('daily_locked_trophies', missingTrophies));
  if(missingConstructor || missingDriver) parti.push(t('daily_locked_titles_v2'));
  return parti.map(p=>`<div style="margin-top:8px;">${p}</div>`).join('');
}

function getTokenState(){
  try{
    const raw = localStorage.getItem(TOKEN_STATE_KEY);
    if(!raw) return { t10:FULL_TOKENS.t10, t20:FULL_TOKENS.t20, refillAt:null };
    const parsed = JSON.parse(raw);
    return { t10: parsed.t10 ?? FULL_TOKENS.t10, t20: parsed.t20 ?? FULL_TOKENS.t20, refillAt: parsed.refillAt ?? null };
  }catch(e){ return { t10:FULL_TOKENS.t10, t20:FULL_TOKENS.t20, refillAt:null }; }
}
function saveTokenState(s){
  try{ localStorage.setItem(TOKEN_STATE_KEY, JSON.stringify(s)); }catch(e){ /* ignorato */ }
}
// Se il conto delle 12h e' scaduto, ricarica tutto insieme e cancella il conto. Va chiamata prima
// di ogni controllo/consumo, cosi' lo stato e' sempre aggiornato.
function checkAndApplyTokenRefill(){
  const s = getTokenState();
  if(s.refillAt && Date.now() >= s.refillAt){
    const refilled = { t10:FULL_TOKENS.t10, t20:FULL_TOKENS.t20, refillAt:null };
    saveTokenState(refilled);
    return refilled;
  }
  return s;
}
function hasTokenFor(length){
  if(isPremiumUser) return true;
  const s = checkAndApplyTokenRefill();
  return length===20 ? s.t20>0 : s.t10>0;
}
// Consuma un gettone (se non premium) e, se e' il PRIMO consumato da quando tutto era pieno,
// avvia il conto delle 12h. Da chiamare solo quando la stagione parte davvero (start-run), non
// alla semplice selezione della lunghezza.
function consumeToken(length){
  if(isPremiumUser) return;
  const s = checkAndApplyTokenRefill();
  const wasFull = s.refillAt===null;
  if(length===20) s.t20 = Math.max(0, s.t20-1);
  else s.t10 = Math.max(0, s.t10-1);
  if(wasFull) s.refillAt = Date.now() + TOKEN_REFILL_MS;
  saveTokenState(s);
}
function getTokenRefillCountdownMs(){
  const s = checkAndApplyTokenRefill();
  if(!s.refillAt) return 0;
  return Math.max(0, s.refillAt - Date.now());
}

// V0.9.8.3: stato premium — SOLO lettura dal gioco, mai scrittura (nessuna policy di insert/update
// sulla tabella, di proposito: solo il server, dopo un pagamento vero confermato, puo' cambiarlo).
async function fetchPremiumStatus(){
  if(!currentUser || !supabaseClient) { isPremiumUser = false; return; }
  try{
    const { data, error } = await supabaseClient
      .from('profiles')
      .select('is_premium')
      .eq('user_id', currentUser.id)
      .maybeSingle();
    if(error){ console.warn('Lettura stato premium non riuscita:', error.message); return; }
    isPremiumUser = !!(data && data.is_premium);
    // V0.9.9.131: sincronizza subito lo stato premium nelle statistiche pubbliche — cosi' il badge
    // (moneta D) nelle classifiche/lista amici si aggiorna appena il premium viene sbloccato,
    // qualunque sia il punto che ha chiamato questa funzione (login, dopo acquisto, dopo codice).
    if(typeof pushPublicStatsToCloud==='function') pushPublicStatsToCloud();
  }catch(e){ console.warn('Lettura stato premium non riuscita:', e); }
}

// V0.9.8.5: chiede al server di aprire una vera sessione di pagamento Stripe, poi ci porta li'.
async function startPremiumCheckout(){
  if(!currentUser){
    gameConfirm(t('premium_need_login_desc'), ()=>{ signInWithGoogle(); }, t('premium_need_login_title'));
    return;
  }
  if(!supabaseClient) return;
  try{
    const returnUrl = window.location.href.split('?')[0];
    const { data, error } = await supabaseClient.functions.invoke('create-checkout', {
      body: { returnUrl },
    });
    if(error || !data || !data.url){
      console.error('Errore avvio pagamento:', error || data);
      gameConfirm(t('premium_checkout_error_desc'), ()=>{}, t('premium_checkout_error_title'));
      return;
    }
    window.location.href = data.url; // reindirizza alla pagina di pagamento Stripe vera
  }catch(e){
    console.error('Errore avvio pagamento:', e);
    gameConfirm(t('premium_checkout_error_desc'), ()=>{}, t('premium_checkout_error_title'));
  }
}

// V0.9.9.98: al ritorno da Stripe (dopo il pagamento), l'indirizzo contiene ?premium_success=1 o
// ?premium_cancelled=1. Puliamo l'indirizzo e, se e' andata bene, ricontrolliamo lo stato premium
// (con un piccolo ritardo: il webhook di conferma potrebbe metterci un attimo ad arrivare) — solo
// quando e' davvero confermato mostriamo la schermata di ringraziamento vera, non prima.
function handlePremiumCheckoutReturn(){
  const params = new URLSearchParams(window.location.search);
  if(params.has('premium_success')){
    window.history.replaceState({}, '', window.location.pathname);
    setTimeout(async ()=>{
      await fetchPremiumStatus();
      if(isPremiumUser){
        state.premiumThankYouResumePhase = state.phase;
        state.phase = 'premium-thank-you';
        render();
      } else {
        // il webhook a volte impiega qualche secondo in piu': un secondo tentativo
        setTimeout(async ()=>{
          await fetchPremiumStatus();
          if(isPremiumUser){ state.premiumThankYouResumePhase = state.phase; state.phase = 'premium-thank-you'; }
          render();
        }, 4000);
      }
    }, 1500);
  } else if(params.has('premium_cancelled')){
    window.history.replaceState({}, '', window.location.pathname);
  }
}
function renderPremiumThankYou(){
  app.innerHTML = `
  <div class="wrap" style="padding:0;">
    <img src="assets/premium/thank-you.webp" alt="" style="width:100%;height:60vh;object-fit:cover;object-position:top;display:block;">
    <div style="padding:24px;text-align:center;">
      <h2 class="hdr" style="font-size:26px;margin-bottom:10px;">${t('premium_thankyou_title')}</h2>
      <div class="dim" style="font-size:14.5px;line-height:1.6;margin-bottom:24px;">${t('premium_thankyou_desc')}</div>
      <button class="primary" data-action="premium-thankyou-continue" style="width:100%;">${t('premium_thankyou_continue')}</button>
    </div>
  </div>`;
  bindActions();
}

const CLOUD_SAVE_TABLE = 'saves';
// V0.9.8.16: FIX IMPORTANTE — prima il salvataggio cloud copriva solo la partita in corso, non i
// progressi PERMANENTI (Museo, Sala Trofei Scuderia, Sala Trofei Pilota, Obiettivi). Cancellando
// la cache del browser, quei progressi andavano persi per sempre perche' non esisteva nessuna copia
// di sicurezza per loro. Ora tutti e 5 i pezzi viaggiano insieme, in un unico salvataggio cloud.
const LOCAL_PROGRESS_TOUCHED_KEY = 'racingDynastyProgressTouchedV1';
function touchLocalProgress(){
  try{ localStorage.setItem(LOCAL_PROGRESS_TOUCHED_KEY, String(Date.now())); }catch(e){ /* ignorato */ }
}
function getLocalProgressTouchedAt(){
  try{ return Number(localStorage.getItem(LOCAL_PROGRESS_TOUCHED_KEY)||0); }catch(e){ return 0; }
}
let __cloudSyncDebounceTimer = null;

// V0.9.9.115: SISTEMA AMICI — le 5 statistiche pubbliche vengono calcolate qui dai dati già
// tracciati in locale (trofei, museo, obiettivi), e sincronizzate verso una piccola tabella
// dedicata leggibile dagli amici — non l'intero salvataggio (che resta privato).
function computePublicStats(){
  const circuitiVinti = Object.values(trophyData).reduce((s,c)=>s+(c.won||0), 0);
  const circuitiTotali = DATA.circuiti.length;
  const totalPiloti = DATA.piloti.length;
  const totalComponenti = DATA.motori.length + DATA.telai.length + DATA.aero.length + DATA.gomme.length + DATA.strategi.length;
  const unlockedPiloti = Object.keys(museumData.piloti).length;
  const unlockedComponenti = Object.keys(museumData.componenti).length;
  const totalMuseo = totalPiloti + totalComponenti;
  const unlockedMuseo = unlockedPiloti + unlockedComponenti;
  const pctMuseo = totalMuseo>0 ? Math.round(unlockedMuseo/totalMuseo*100) : 0;
  return {
    circuiti_vinti: circuitiVinti,
    circuiti_totali: circuitiTotali,
    completamento_museo_pct: pctMuseo,
    obiettivi_sbloccati: achievementData.unlockedIds.length,
    obiettivi_totali: ACHIEVEMENTS.length,
  };
}
function pushPublicStatsToCloud(){
  if(!currentUser || !supabaseClient) return;
  clearTimeout(__publicStatsSyncDebounceTimer);
  __publicStatsSyncDebounceTimer = setTimeout(async ()=>{
    try{
      const stats = computePublicStats();
      const { error } = await supabaseClient.from('player_public_stats').upsert({
        user_id: currentUser.id,
        // V0.9.9.184: BUG CORRETTO — segnalato da Gio: "vedo nome e cognome su alcuni amici al
        // posto del nickname, sul gioco in generale deve uscire Player per tutti quelli che non
        // hanno ancora scelto un nick". Causa: il nome Google veniva salvato QUI, nel database
        // stesso, al posto di un nickname mancante — non solo mostrato temporaneamente. Tolto il
        // ripiego: ora salviamo null se non c'è un vero nickname scelto, lasciando che la lista
        // amici mostri l'etichetta generica "Giocatore"/"Player" già esistente e già corretta.
        nickname: dailyNicknameCache?.nickname || null,
        is_premium: !!isPremiumUser,
        ...stats,
        updated_at: new Date().toISOString(),
      });
      if(error) console.warn('Sincronizzazione statistiche pubbliche non riuscita:', error.message);
    }catch(e){ console.warn('Sincronizzazione statistiche pubbliche non riuscita:', e); }
  }, 2500);
}
let __publicStatsSyncDebounceTimer = null;

// V0.9.9.115: SISTEMA AMICI — codice invito personale. Generato in modo casuale al primo bisogno
// (non serve una funzione server per QUESTO passaggio: creare il PROPRIO codice non è unesima
// operazione sensibile, la sicurezza vera sta nel RISCATTO del codice di qualcun altro, che invece
// passa sempre dalla funzione server).
let myFriendCodeCache = undefined; // undefined = non ancora controllato
async function getOrCreateMyFriendCode(){
  if(myFriendCodeCache !== undefined) return myFriendCodeCache;
  if(!currentUser || !supabaseClient){ myFriendCodeCache = null; return null; }
  try{
    const { data: esistente } = await supabaseClient.from('friend_invite_codes')
      .select('code').eq('user_id', currentUser.id).maybeSingle();
    if(esistente){ myFriendCodeCache = esistente.code; return myFriendCodeCache; }
    const nuovoCodice = 'RD-' + Array.from({length:6}, ()=> '23456789ABCDEFGHJKMNPQRSTUVWXYZ'[Math.floor(Math.random()*31)]).join('');
    const { error } = await supabaseClient.from('friend_invite_codes').insert({ user_id: currentUser.id, code: nuovoCodice });
    if(error){ console.warn('Creazione codice invito non riuscita:', error.message); myFriendCodeCache = null; return null; }
    myFriendCodeCache = nuovoCodice;
    return myFriendCodeCache;
  }catch(e){ console.warn('Creazione codice invito non riuscita:', e); myFriendCodeCache = null; return null; }
}
// V0.9.9.118: immagine condivisibile del codice invito — posa pilota casuale (stessa fascia usata
// a fine stagione), codice in grande tematizzato col colore della fascia, logo di sfondo. Stesso
// schema già collaudato di buildShareCardCanvas/shareResultCard, qui semplificato per un'immagine
// quadrata (formato social) invece della carta verticale.
async function buildFriendCodeShareCanvas(code){
  // V0.9.9.122: RIMOSSE le pose vittoria (trofeo in mano), richiesto da Gio — "la scheda che si
  // condivide per il codice amico non deve avere pose vittoria". Sostituite con scene neutre di
  // squadra/allenamento (stessa cartella assets/driver-scenes usata altrove nel gioco per momenti
  // di carriera), tono adatto a un invito di amicizia, non a un trionfo.
  const sceneCasuali = ['team-event', 'training'];
  const sceneScelta = sceneCasuali[Math.floor(Math.random()*sceneCasuali.length)];
  const sceneSrc = `assets/driver-scenes/${sceneScelta}.webp`;

  const [logoImg, sceneImg] = await Promise.all([loadImg(LOGO_DATA_URI), loadImg(sceneSrc)]);

  const S = 1080; // immagine quadrata, formato social
  const cv = document.createElement('canvas');
  cv.width = S; cv.height = S;
  const ctx = cv.getContext('2d');

  // la scena riempie tutto il quadrato (cover, ritagliata al centro se le proporzioni non combaciano)
  const scala = Math.max(S/sceneImg.width, S/sceneImg.height);
  const sw = sceneImg.width*scala, sh = sceneImg.height*scala;
  ctx.drawImage(sceneImg, (S-sw)/2, (S-sh)/2, sw, sh);

  // scurita dall'alto (per il logo) e soprattutto in basso (per il codice, ben leggibile)
  const scrim = ctx.createLinearGradient(0, 0, 0, S);
  scrim.addColorStop(0, 'rgba(5,6,8,0.55)'); scrim.addColorStop(0.35, 'rgba(5,6,8,0.05)');
  scrim.addColorStop(0.7, 'rgba(5,6,8,0.15)'); scrim.addColorStop(1, 'rgba(5,6,8,0.94)');
  ctx.fillStyle = scrim; ctx.fillRect(0, 0, S, S);

  // logo in alto, centrato
  const logoW = S*0.4, logoH = logoImg.height*(logoW/logoImg.width);
  ctx.globalAlpha = 0.95;
  ctx.drawImage(logoImg, (S-logoW)/2, 44, logoW, logoH);
  ctx.globalAlpha = 1;

  // codice in grande, arancione (colore firma del gioco, non legato a una fascia specifica dato
  // che non c'è più un componente/pilota a cui riferirsi), in basso
  ctx.textAlign = 'center';
  ctx.fillStyle = '#ff6a1a';
  ctx.font = '900 66px -apple-system,sans-serif';
  ctx.shadowColor = '#ff6a1a'; ctx.shadowBlur = 26;
  ctx.fillText(code, S/2, S*0.90);
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#e4e4e8';
  ctx.font = '600 21px -apple-system,sans-serif';
  ctx.fillText(t('friends_share_cta'), S/2, S*0.945);
  ctx.textAlign = 'left';

  return cv;
}
async function shareFriendCode(code){
  try{
    const cv = await buildFriendCodeShareCanvas(code);
    const blob = await new Promise(res=>cv.toBlob(res,'image/png'));
    const fileName = 'racing-dynasty-amico.png';
    const gameUrl = `https://racingdynasty.fuoriscala.xyz/?friend=${encodeURIComponent(code)}`;
    const shareText = t('friends_share_text', gameUrl, code);
    if(navigator.share && navigator.canShare && navigator.canShare({ files:[new File([blob], fileName, {type:'image/png'})] })){
      await navigator.share({ files:[new File([blob], fileName, {type:'image/png'})], text: shareText });
    } else {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = fileName; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=>URL.revokeObjectURL(url), 2000);
      alert(t('friends_share_fallback', shareText));
    }
  }catch(e){
    console.warn('Generazione immagine condivisibile codice amico non riuscita:', e);
    alert(t('friends_share_error'));
  }
}
async function redeemFriendCode(code){
  if(!currentUser || !supabaseClient) return { ok:false, error:'not_authenticated' };
  try{
    const { data, error } = await supabaseClient.functions.invoke('add-friend-by-code', { body:{ code } });
    if(error){ console.warn('Chiamata add-friend-by-code non riuscita (problema di invocazione):', error); return { ok:false, error:'invocation_error' }; }
    if(!data || !data.ok){ console.warn('add-friend-by-code ha risposto con un errore vero:', data); return { ok:false, error: data?.error || 'unknown' }; }
    return { ok:true, alreadyFriends: !!data.alreadyFriends };
  }catch(e){ console.warn('Riscatto codice amico non riuscito:', e); return { ok:false, error:'exception' }; }
}
// V0.9.9.117: insieme leggero dei soli ID amici (senza statistiche) — usato per evidenziare le
// righe amico nelle classifiche, dove non servono i dettagli completi.
// V0.9.9.131: recupera lo stato premium (per il badge moneta D) di un insieme di giocatori — usato
// nelle classifiche, dove serve sapere chi ha premium tra TUTTI i giocatori mostrati, non solo gli amici.
async function loadPremiumUserIdsSet(userIds){
  if(!supabaseClient || userIds.length===0) return new Set();
  // V0.9.9.205: D8 (audit tecnico) — con tanti giocatori in classifica, un'unica richiesta con
  // tutti gli ID nell'URL potrebbe diventare troppo lunga. Dividiamo in blocchi da 200 alla volta,
  // uniamo i risultati — stesso identico risultato finale, solo più sicuro su larga scala.
  const BLOCCO = 200;
  const risultato = new Set();
  try{
    for(let i=0; i<userIds.length; i+=BLOCCO){
      const blocco = userIds.slice(i, i+BLOCCO);
      const { data, error } = await supabaseClient.from('player_public_stats')
        .select('user_id, is_premium').in('user_id', blocco).eq('is_premium', true);
      if(!error && data) data.forEach(r => risultato.add(r.user_id));
    }
    return risultato;
  }catch(e){ return risultato; }
}
async function loadMyFriendIdsSet(){
  if(!currentUser || !supabaseClient) return new Set();
  try{
    const { data, error } = await supabaseClient.from('friendships')
      .select('user_id_a, user_id_b')
      .or(`user_id_a.eq.${currentUser.id},user_id_b.eq.${currentUser.id}`);
    if(error || !data) return new Set();
    return new Set(data.map(r => r.user_id_a===currentUser.id ? r.user_id_b : r.user_id_a));
  }catch(e){ return new Set(); }
}
// V0.9.9.124: SISTEMA AMICI — eliminazione, richiesta da Gio. L'amicizia è una singola riga
// condivisa (non due separate per i due utenti), quindi eliminarla la rimuove per entrambi i lati
// — comportamento corretto per "rimuovi amico" (diversamente da un blocco unilaterale, che qui non
// esiste). Prova a eliminare in entrambi i possibili ordinamenti della coppia, dato che non
// sappiamo a priori se l'amico è "A" o "B" nella riga.
async function removeFriend(amicoUserId){
  if(!currentUser || !supabaseClient) return { ok:false };
  try{
    const [uidA, uidB] = [currentUser.id, amicoUserId].sort();
    const { error } = await supabaseClient.from('friendships')
      .delete().eq('user_id_a', uidA).eq('user_id_b', uidB);
    if(error){ console.warn('Eliminazione amicizia non riuscita:', error.message); return { ok:false }; }
    return { ok:true };
  }catch(e){ console.warn('Eliminazione amicizia non riuscita:', e); return { ok:false }; }
}
async function loadMyFriendsList(){
  if(!currentUser || !supabaseClient) return [];
  try{
    const { data: amicizie, error } = await supabaseClient.from('friendships')
      .select('user_id_a, user_id_b')
      .or(`user_id_a.eq.${currentUser.id},user_id_b.eq.${currentUser.id}`);
    if(error || !amicizie){ console.warn('Caricamento amici non riuscito:', error?.message); return []; }
    const idAmici = amicizie.map(r => r.user_id_a===currentUser.id ? r.user_id_b : r.user_id_a);
    if(idAmici.length===0) return [];

    // V0.9.9.121: BUG CORRETTO — segnalato da Gio, un amico con amicizia vera (confermata dal
    // badge in classifica) non compariva nella lista amici. Causa: la lista partiva dalle
    // statistiche pubbliche (player_public_stats), che un amico ottiene solo dopo aver sbloccato
    // qualcosa (trofeo/museo/obiettivo) — se non l'ha ancora fatto, la sua riga li' non esiste
    // affatto, e spariva del tutto dalla lista anche se l'amicizia era reale. Ora la lista parte
    // SEMPRE dagli amici veri (idAmici), con le statistiche unite quando ci sono e zero/sconosciuto
    // quando mancano — un amico non sparisce mai solo perche' non ha ancora sincronizzato nulla.
    const { data: stats, error: statsError } = await supabaseClient.from('player_public_stats')
      .select('user_id, nickname, circuiti_vinti, circuiti_totali, completamento_museo_pct, obiettivi_sbloccati, obiettivi_totali, is_premium')
      .in('user_id', idAmici);
    if(statsError) console.warn('Caricamento statistiche amici non riuscito (proseguo con valori di default):', statsError.message);
    const statsPerUtente = {};
    (stats||[]).forEach(s => { statsPerUtente[s.user_id] = s; });

    // V0.9.9.173: BUG CORRETTO — segnalato da Gio: "in lista amici vedo nome e cognome (nome
    // Google), in classifica li vedo giusti, voglio il nickname in ogni parte del gioco". Causa:
    // la priorità era invertita — player_public_stats.nickname (che poteva restare bloccato sul
    // nome Google se mai risincronizzato dopo la scelta di un vero nickname, corretto qui sopra
    // alla radice) veniva controllato PER PRIMO, le viste basate su daily_nicknames (la vera fonte
    // scelta dall'utente, sempre aggiornata) solo come ripiego. Ora l'ordine è invertito: le viste
    // daily_nicknames-based vengono controllate prima, player_public_stats resta l'ultima risorsa
    // per chi non ha mai giocato la Daily nemmeno una volta (unico caso in cui è l'unica fonte
    // disponibile).
    let nicknamePerUtente = {}, ratingPerUtente = {};
    // nickname E rating vivono insieme nella vista classifica generale già esistente e già
    // verificata funzionante per mostrare nickname di ALTRI giocatori (non solo il proprio) —
    // più sicuro che interrogare direttamente daily_nicknames, dove i permessi non sono verificati
    try{
      const { data: ratingData } = await supabaseClient.from('daily_weighted_leaderboard_view')
        .select('user_id, nickname, rating_medio').in('user_id', idAmici);
      (ratingData||[]).forEach(r => { ratingPerUtente[r.user_id] = r.rating_medio; nicknamePerUtente[r.user_id] = r.nickname; });
    }catch(e){ /* silenzioso: la lista amici funziona comunque senza rating/nickname da qui */ }
    // ripiego 1: se un amico non ha ancora 15 run Daily (non compare nella vista sopra, che li
    // richiede), proviamo comunque a recuperare almeno il nickname da una qualunque sua Daily
    // passata, non solo quella di oggi
    const mancantiNickname1 = idAmici.filter(uid => !nicknamePerUtente[uid]);
    if(mancantiNickname1.length>0){
      try{
        const { data: nickData } = await supabaseClient.from('daily_leaderboard_view')
          .select('user_id, nickname').in('user_id', mancantiNickname1).limit(mancantiNickname1.length);
        (nickData||[]).forEach(n => { nicknamePerUtente[n.user_id] = n.nickname; });
      }catch(e){ /* silenzioso */ }
    }
    // ripiego 2 (ULTIMA risorsa): per chi non ha mai giocato la Daily nemmeno una volta, usiamo
    // player_public_stats — potrebbe essere il vero nickname (se sincronizzato dopo averlo scelto)
    // o il nome Google di ripiego (se non ha ancora scelto un nickname): comunque meglio di niente.
    (stats||[]).forEach(s => { if(s.nickname && !nicknamePerUtente[s.user_id]) nicknamePerUtente[s.user_id] = s.nickname; });

    return idAmici.map(uid => {
      const s = statsPerUtente[uid];
      return {
        user_id: uid,
        nickname: nicknamePerUtente[uid] || null,
        nonSincronizzato: !s, // V0.9.9.122: mai sincronizzato (nessuna riga trovata), non "zero vero"
        circuiti_vinti: s?.circuiti_vinti ?? 0,
        circuiti_totali: s?.circuiti_totali ?? DATA.circuiti.length,
        completamento_museo_pct: s?.completamento_museo_pct ?? 0,
        obiettivi_sbloccati: s?.obiettivi_sbloccati ?? 0,
        obiettivi_totali: s?.obiettivi_totali ?? ACHIEVEMENTS.length,
        is_premium: !!s?.is_premium,
        rating_medio: ratingPerUtente[uid] ?? null,
      };
    });
  }catch(e){ console.warn('Caricamento amici non riuscito:', e); return []; }
}

function pushSaveToCloud(){
  if(!currentUser || !supabaseClient) return;
  const userIdAlMomento = currentUser.id; // V0.9.9.201: catturato QUI, non dentro il setTimeout —
  // se l'account attivo cambia prima che il salvataggio differito parta davvero, i dati restano
  // comunque attribuiti al proprietario giusto (chi ha davvero generato questo salvataggio), non a
  // chi risulta loggato al momento dell'invio effettivo 2.5s dopo.
  clearTimeout(__cloudSyncDebounceTimer);
  __cloudSyncDebounceTimer = setTimeout(async ()=>{
    try{
      // V0.9.8.16: tutti e 5 i pezzi insieme — la partita in corso da sola non basta piu'.
      const runRaw = localStorage.getItem(SAVE_KEY);
      const bundle = {
        run: runRaw ? JSON.parse(runRaw) : null,
        museum: museumData,
        trophies: trophyData,
        driverTrophies: driverTrophyData,
        achievements: achievementData,
      };
      const { error } = await supabaseClient.from(CLOUD_SAVE_TABLE).upsert({
        user_id: userIdAlMomento,
        save_data: bundle,
        updated_at: new Date().toISOString(),
      });
      if(error) console.warn('Salvataggio cloud non riuscito:', error.message);
    }catch(e){ console.warn('Salvataggio cloud non riuscito:', e); }
  }, 2500);
}

async function pullSaveFromCloud(){
  if(!currentUser || !supabaseClient) return;
  try{
    const { data, error } = await supabaseClient
      .from(CLOUD_SAVE_TABLE)
      .select('save_data, updated_at')
      .eq('user_id', currentUser.id)
      .maybeSingle();
    if(error){ console.warn('Caricamento cloud non riuscito:', error.message); return; }
    if(!data || !data.save_data) return; // nessun salvataggio cloud ancora, niente da fare
    const cloudTime = new Date(data.updated_at).getTime();
    // V0.9.8.16: confrontiamo col timestamp unificato (tocca ad ogni modifica di uno qualsiasi
    // dei 5 pezzi), non piu' solo con la data della partita in corso.
    const localTime = getLocalProgressTouchedAt();
    const bundle = data.save_data;
    const isNewBundleFormat = bundle && typeof bundle==='object' && ('museum' in bundle || 'trophies' in bundle || 'run' in bundle);
    if(cloudTime > localTime){
      // il salvataggio cloud e' piu' recente: lo adottiamo, per tutti e 5 i pezzi
      if(isNewBundleFormat){
        if(bundle.run) localStorage.setItem(SAVE_KEY, JSON.stringify(bundle.run));
        if(bundle.museum){ museumData = bundle.museum; localStorage.setItem(MUSEUM_SAVE_KEY, JSON.stringify(museumData)); }
        if(bundle.trophies){ trophyData = bundle.trophies; localStorage.setItem(TROPHY_SAVE_KEY, JSON.stringify(trophyData)); }
        if(bundle.driverTrophies){ driverTrophyData = bundle.driverTrophies; localStorage.setItem(DRIVER_TROPHY_SAVE_KEY, JSON.stringify(driverTrophyData)); }
        if(bundle.achievements){ achievementData = { ...ACHIEVEMENT_DATA_DEFAULTS, ...bundle.achievements }; localStorage.setItem(ACHIEVEMENT_SAVE_KEY, JSON.stringify(achievementData)); }
      } else {
        // formato vecchio (solo partita, da prima di questo fix) — compatibilita' con salvataggi gia' esistenti
        localStorage.setItem(SAVE_KEY, JSON.stringify(bundle));
      }
      localStorage.setItem(LOCAL_PROGRESS_TOUCHED_KEY, String(cloudTime));
      if(state && (state.phase==='title' || state.phase==='studio-splash')) render();
    } else if(localTime > 0 && localTime > cloudTime){
      // il dispositivo ha qualcosa di piu' recente del cloud (es. giocato offline): spingiamolo su
      pushSaveToCloud();
    }
  }catch(e){ console.warn('Caricamento cloud non riuscito:', e); }
}
const NO_SAVE_PHASES = new Set(['studio-splash','lang-select','title','difficulty','season-length','naming','race_live','start_lights','upgrade_suspense','trophy-room','museum-dynasty','garage','mode-select','driver-creation','driver-creation-done','driver-trophy-room','driver-hub','driver-season-end','driver-retirement','driver-activity','driver-activity-result','driver-contract','driver-media-event','streamer-question','streamer-name-input','streamer-continue-check','out-of-tokens','pedal-tutorial','tutorial-first-launch-prompt','tutorial-intro','tutorial-draft','tutorial-goat-reveal','tutorial-sponsor','tutorial-complete','daily-nickname-setup','daily-season-hub','daily-leaderboard','premium-thank-you','friends-hub','my-profile','edit-nickname','daily-score-reveal']);
function saveGame(){
  try{
    if(!state || NO_SAVE_PHASES.has(state.phase)) return;
    if(state.isDriverCareer) return; // V0.9.7.9.5: mai sovrascrivere il salvataggio Carriera Scuderia — salvataggio dedicato non ancora costruito (punto 4+)
    if(state.isTutorialRun) return; // V0.9.9.70: il tutorial non deve MAI sovrascrivere il salvataggio vero del giocatore
    if(state.isDailySeason) return; // V0.9.9.95: stesso motivo, mai per la Daily
    if(state.phase==='season_end'){ deleteSave(); return; }
    // V0.9.9.201: midSeasonSwappedCats era un Set nativo mai convertito — JSON.stringify lo
    // serializza come oggetto vuoto {}, e un .add() successivo dopo il ricaricamento lanciava
    // TypeError. Stesso trattamento già usato per usedIds.
    const snapshot = { ...state, live: null, usedIds: Array.from(state.usedIds||[]),
      midSeasonSwappedCats: Array.from(state.midSeasonSwappedCats||[]) };
    localStorage.setItem(SAVE_KEY, JSON.stringify({ saveVersion:'0.9', savedAt: Date.now(), state: snapshot }));
    touchLocalProgress();
    pushSaveToCloud(); // V0.9.8.2: no-op se non loggati
  }catch(e){ /* storage non disponibile: ignorato silenziosamente */ }
}
function loadGame(){
  try{
    const raw = localStorage.getItem(SAVE_KEY);
    if(!raw) return null;
    const parsed = JSON.parse(raw);
    if(!parsed || !parsed.state) return null;
    parsed.state.usedIds = new Set(parsed.state.usedIds||[]);
    parsed.state.midSeasonSwappedCats = new Set(parsed.state.midSeasonSwappedCats||[]); // V0.9.9.201
    return parsed;
  }catch(e){ return null; }
}
function deleteSave(){
  try{ localStorage.removeItem(SAVE_KEY); }catch(e){ /* ignorato */ }
}

// V0.9.9.132: SALVATAGGIO DEDICATO DAILY SEASON — richiesto da Gio: "durante la daily run sono
// uscito, se rientro c'è sempre il tasto per iniziarla, non per continuarla". Il salvataggio
// normale (saveGame) blocca deliberatamente la Daily per isolarla dalla carriera vera (V0.9.9.95)
// — questo è un sistema SEPARATO, dedicato solo a permettere di riprendere una Daily interrotta,
// su una chiave diversa, che non tocca mai il salvataggio della carriera normale.
const DAILY_SAVE_KEY = 'racingDynastyDailySaveV1';
function saveDailyGameState(){
  try{
    if(!state || !state.isDailySeason || NO_SAVE_PHASES.has(state.phase)) return;
    if(state.phase==='season_end'){ deleteDailyGameSave(); return; }
    const snapshot = { ...state, live: null, usedIds: Array.from(state.usedIds||[]),
      midSeasonSwappedCats: Array.from(state.midSeasonSwappedCats||[]) }; // V0.9.9.201
    localStorage.setItem(DAILY_SAVE_KEY, JSON.stringify({ savedAt: Date.now(), state: snapshot }));
  }catch(e){ /* storage non disponibile: ignorato silenziosamente */ }
}
function loadDailyGameSave(){
  try{
    const raw = localStorage.getItem(DAILY_SAVE_KEY);
    if(!raw) return null;
    const parsed = JSON.parse(raw);
    if(!parsed || !parsed.state) return null;
    // valido solo se è ancora la Daily di OGGI — quella di ieri è comunque finita, non ha senso
    // "continuarla" (e il countdown/calendario di un altro giorno non sarebbe più coerente)
    if(parsed.state.dailySeasonDate !== todayDateStringUTC()) { deleteDailyGameSave(); return null; }
    parsed.state.usedIds = new Set(parsed.state.usedIds||[]);
    parsed.state.midSeasonSwappedCats = new Set(parsed.state.midSeasonSwappedCats||[]); // V0.9.9.201
    return parsed;
  }catch(e){ return null; }
}
function deleteDailyGameSave(){
  try{ localStorage.removeItem(DAILY_SAVE_KEY); }catch(e){ /* ignorato */ }
}
// V0.9.7.8.6: export/import della run corrente come file .json — stesso oggetto gia' salvato in
// localStorage, nessuna trasformazione. Serve a chi vuole condividere una run particolare con
// qualcun altro (o a chi vuole semplicemente un backup fuori dal browser).
function exportRunSave(){
  const raw = localStorage.getItem(SAVE_KEY);
  if(!raw){ alert('Nessuna stagione in corso da esportare.'); return; }
  const blob = new Blob([raw], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const teamName = (state && state.team && state.team.nome) ? state.team.nome.replace(/[^a-z0-9]+/gi,'-') : 'run';
  a.href = url; a.download = `racing-dynasty-${teamName}.json`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
  playSfx('ui_confirm');
}
function importRunSaveFromText(text){
  let parsed;
  try{ parsed = JSON.parse(text); }
  catch(e){ alert('Il file non è un salvataggio valido (JSON non leggibile).'); return false; }
  // validazione minima: deve avere la stessa forma di cio' che saveGame() scrive davvero
  if(!parsed || typeof parsed!=='object' || !parsed.state || typeof parsed.saveVersion==='undefined'){
    alert('Il file non ha il formato di un salvataggio di Racing Dynasty. Import annullato.');
    return false;
  }
  try{
    localStorage.setItem(SAVE_KEY, JSON.stringify(parsed));
    playSfx('ui_confirm');
    state = { phase:'title', selectedDifficulty: (state&&state.difficulty) || 'medio' };
    render();
    return true;
  }catch(e){
    alert('Import fallito: impossibile scrivere il salvataggio.');
    return false;
  }
}

// V0.9.5: ripristino completo — cancella TUTTO (carriera, museo, trofei, obiettivi), per riportare
// il gioco esattamente allo stato di una primissima apertura. Utile soprattutto in fase di test.
function fullResetAll(){
  try{ localStorage.removeItem(SAVE_KEY); }catch(e){}
  try{ localStorage.removeItem(MUSEUM_SAVE_KEY); }catch(e){}
  try{ localStorage.removeItem(TROPHY_SAVE_KEY); }catch(e){}
  try{ localStorage.removeItem(ACHIEVEMENT_SAVE_KEY); }catch(e){}
  // pulizia chiavi legacy del vecchio tutorial (v0.9.5), ora rimosso
  ['Completed','Skipped','Version','CurrentStep','Started'].forEach(k=>{
    try{ localStorage.removeItem('racingDynastyTutorial'+k); }catch(e){}
  });
  museumData = { piloti:{}, componenti:{} };
  trophyData = {};
  achievementData = { ...ACHIEVEMENT_DATA_DEFAULTS };
}

// V0.9.7.8.15: lo splash NON avanza piu' da solo — resta finche' non si tocca, come richiesto.
// L'unica eccezione temporale e' un piccolo aiuto per chi non capisce di dover toccare: dopo 5s
// di inattivita' compare una scritta lampeggiante "premi per continuare".
function renderStudioSplash(){
  const reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  app.innerHTML = `
  <div class="studio-splash ${reduced?'reduced':''}" id="studioSplashRoot">
    <div class="studio-splash-stage">
      <img class="studio-splash-logo" id="splashLogoImg" src="assets/fuoriscala/fuoriscala_primary_white.svg" alt="FUORISCALA" style="opacity:0;">
    </div>
    <div class="studio-splash-tagline" id="splashTagline">${t('splash_presents')}</div>
    <div class="studio-splash-skip" id="splashSkipHint">${t('splash_tap_continue')}</div>
  </div>
  `;
  const root = document.getElementById('studioSplashRoot');
  const advance = ()=>{
    if(state.phase!=='studio-splash') return;
    if(root) root.classList.add('leaving');
    setTimeout(()=>{
      const fase = determinePhaseAfterSplash();
      state.phase = fase;
      if(fase==='title') playIntroOnce();
      render();
    }, 280);
  };
  if(root) root.addEventListener('click', advance, { once:true });

  // V0.9.8.11: RICOSTRUITO ANCORA — stavolta l'animazione e' guidata interamente da JavaScript
  // (requestAnimationFrame), non piu' affidata al motore CSS del browser. Controlliamo noi ogni
  // singolo fotogramma con la nostra matematica, invece di sperare che il browser interpoli bene
  // una keyframe complessa — elimina qualunque comportamento imprevedibile specifico del
  // dispositivo (probabile causa dello sfarfallio). Recupera lo zoom drammatico di prima, che
  // piaceva, ma con controllo totale sul risultato.
  const logo = document.getElementById('splashLogoImg');
  if(logo && !reduced){
    const duration = 900;
    function easeInOutCubic(t){ return t<0.5 ? 4*t*t*t : 1-Math.pow(-2*t+2,3)/2; }
    // V0.9.8.13: l'uscita dallo schermo e' VOLUTA — gioco di parole col nome "FUORISCALA" (esce
    // dalla scala/misura). Il picco resta drammatico. Il problema tecnico va cercato altrove:
    // probabilmente il costo di ritagliare (overflow:hidden) un elemento molto piu' grande del suo
    // contenitore, ricalcolato ad ogni fotogramma — vedi il cambiamento al contenitore piu' sotto.
    const overshootPeak = 3.6;
    function tick(now, startTime){
      const elapsed = now - startTime;
      const t = Math.min(1, elapsed/duration);
      const scale = t<0.5
        ? 0.3 + (overshootPeak-0.3) * easeInOutCubic(t/0.5)
        : overshootPeak - (overshootPeak-1) * easeInOutCubic((t-0.5)/0.5);
      const opacity = Math.min(1, elapsed/180); // dissolvenza in ingresso rapida e indipendente
      logo.style.transform = `scale(${scale.toFixed(4)})`;
      logo.style.opacity = String(opacity);
      if(t < 1) requestAnimationFrame((now2)=>tick(now2, startTime));
    }
    // V0.9.8.14: attesa esplicita di 100ms prima di far partire l'animazione — non piu' "parti
    // appena il codice viene eseguito", ma un momento fermo e deliberato prima del movimento.
    setTimeout(()=>{
      requestAnimationFrame((now)=>tick(now, now));
    }, 100);
  } else if(logo){
    logo.style.opacity = '1';
    logo.style.transform = 'scale(1)';
  }

  setTimeout(()=>{
    const hint = document.getElementById('splashSkipHint');
    if(hint && state.phase==='studio-splash') hint.classList.add('splash-hint-blink');
  }, 5000);
}

