let __slTokenRefillCheckTimer = null;
function renderSeasonLength(){
  const tokenState = checkAndApplyTokenRefill();
  const refillMs = getTokenRefillCountdownMs();
  // V0.9.9.110: messaggio con orario fisso invece del countdown live, richiesto da Gio — "nuovi
  // gettoni disponibili alle ore X" in base all'orario LOCALE del dispositivo, non un conto alla
  // rovescia che si aggiorna al secondo.
  const orarioRipristino = refillMs>0 ? new Date(Date.now()+refillMs) : null;
  const orarioTesto = orarioRipristino
    ? String(orarioRipristino.getHours()).padStart(2,'0')+':'+String(orarioRipristino.getMinutes()).padStart(2,'0')
    : '';
  const countdownHTML = (esaurito) => (!isPremiumUser && esaurito && refillMs>0)
    ? `<div class="dim mono" style="font-size:10.5px;margin-top:2px;color:var(--amber);">${t('sl_token_refill_at', orarioTesto)}</div>` : '';
  const tokenChip10 = isPremiumUser
    ? `<div class="dim mono" style="font-size:11px;color:var(--legendary);margin-top:4px;">${t('sl_unlimited')}</div>`
    : `<div class="dim mono" style="font-size:11px;margin-top:4px;">${t('sl_tokens_left', tokenState.t10, FULL_TOKENS.t10)}</div>${countdownHTML(tokenState.t10<=0)}`;
  const tokenChip20 = isPremiumUser
    ? `<div class="dim mono" style="font-size:11px;color:var(--legendary);margin-top:4px;">${t('sl_unlimited')}</div>`
    : `<div class="dim mono" style="font-size:11px;margin-top:4px;">${t('sl_tokens_left', tokenState.t20, FULL_TOKENS.t20)}</div>${countdownHTML(tokenState.t20<=0)}`;
  app.innerHTML = `
  <div class="topbar">
    <div class="topbar-left-group">
      ${backChevronBtnHTML('go-to-mode-select')}
      <div class="brand hdr">RACING DYNASTY<small>${t('sl_choose')}</small></div>
    </div>
  </div>
  <div class="panel">
    <div class="eyebrow">${t('diff_new_career')}</div>
    <h2 class="hdr" style="font-size:24px;">${t('sl_choose')}</h2>
    <div class="dim" style="font-size:12px;margin-top:6px;">${t('sl_subtitle')}</div>
  </div>
  <div class="grid grid-2">
    <div class="card pickable" data-rarity="Rare" data-action="choose-season-length" data-length="10">
      <span class="rarity-tag" data-rarity="Rare">${t('sl_quick')}</span>
      <div class="card-rating">10<span style="font-size:12px;color:var(--dim);"> ${t('sl_races_word')}</span></div>
      <div class="ability">${t('sl_quick_desc')}</div>
      ${tokenChip10}
      <div class="card-tap-hint">${t('sl_quick_hint')}</div>
    </div>
    <div class="card pickable" data-rarity="Legendary" data-action="choose-season-length" data-length="20">
      <span class="rarity-tag" data-rarity="Legendary">${t('sl_full')}</span>
      <div class="card-rating">20<span style="font-size:12px;color:var(--dim);"> ${t('sl_races_word')}</span></div>
      <div class="ability">${t('sl_full_desc')}</div>
      ${tokenChip20}
      <div class="card-tap-hint">${t('sl_full_hint')}</div>
    </div>
  </div>
  <div class="card" style="margin-top:10px;">
    <div style="display:flex; justify-content:space-between; align-items:center; gap:12px;">
      <div>
        <div style="font-weight:700;">${t('sl_riflessi_partenza')}</div>
        <div class="dim" style="font-size:11.5px; margin-top:3px; line-height:1.4;">${state.selectedRiflessiPartenza!==false ? t('sl_riflessi_partenza_desc_on') : t('sl_riflessi_partenza_desc_off')}</div>
      </div>
      <button type="button" class="toggle-switch ${state.selectedRiflessiPartenza!==false?'on':''}" data-action="toggle-riflessi-partenza" aria-label="${t('sl_riflessi_partenza')}"><span class="toggle-knob"></span></button>
    </div>
  </div>
  `;
  bindActions();
  clearInterval(__slTokenRefillCheckTimer);
  if(!isPremiumUser && (tokenState.t10<=0 || tokenState.t20<=0)){
    __slTokenRefillCheckTimer = setInterval(()=>{
      if(state.phase!=='season-length'){ clearInterval(__slTokenRefillCheckTimer); return; } // schermata cambiata
      if(getTokenRefillCountdownMs()<=0) render(); // ripristinati, ridisegna con i gettoni pieni
    }, 20000);
  }
}

function statBar(label, val){
  return `<div class="stat-row"><span class="label">${label}</span><div class="bar"><span style="width:${val}%"></span></div><span class="val">${val}</span></div>`;
}

function shortenText(text, maxLen){
  if(!text) return '';
  const cut = text.split(';')[0].trim();
  if(cut.length<=maxLen) return cut;
  return cut.slice(0,maxLen-1).trim()+'…';
}

function draftCardHTML(item, statKeys, extraLine, synergyCatKey){
  const stats = statKeys.map(k => item[k]!==undefined ? statBar(t('sk_'+k), item[k]) : '').join('');
  let synBadge = '', rowCls = '';
  // V0.9.9.180: PUNTI 9/10 — BUG CORRETTO, segnalato da Gio: "sinergie non tradotte e altre robe
  // nelle carte draft". Trovate 4 stringhe fisse in italiano in questa funzione, mai tradotte in
  // nessuna lingua indipendentemente da quella selezionata: l'etichetta mentalità/sinergia (usava
  // m.label direttamente invece della funzione mentaLabel() già esistente e già usata altrove nel
  // gioco), "Mentalità"/"Tipologia", "Dettagli", "Tocca il riquadro per scegliere". Corrette tutte.
  if(synergyCatKey && item.sinergia && state.team){
    const m = MENTALITA_DEFS[item.sinergia];
    const isPilotRole = synergyCatKey==='pilotMain' || synergyCatKey==='pilotSecond';
    const kl = isPilotRole ? t('comp_mentality') : t('comp_typology');
    const unpaired = unpairedMentalities(synergyCatKey);
    const wouldGain = unpaired.has(item.sinergia);
    synBadge = `<div class="syn-half-badge" title="${kl}: ${mentaLabel(item.sinergia)}" style="margin-bottom:6px;"><div class="sem-half" style="background:${m.color};"></div><div class="sem-half" style="background:rgba(255,255,255,0.05);"></div></div>`;
    if(wouldGain) rowCls = ' card-synergy-gain';
  }
  return `
  <div class="card pickable${rowCls}" data-rarity="${displayRarity(item)}" data-action="pick-draft" data-id="${item.id}" ${rowCls?`style="--syn-glow:${MENTALITA_DEFS[item.sinergia].color};"`:''}>
    ${synBadge}
    <span class="rarity-tag" data-rarity="${displayRarity(item)}">${displayRarityLabel(item)}</span>
    <div class="card-head-row">
      <div class="card-head-left">
        <div class="card-name">${item.naz? flag(item.naz)+' ':''}${item.nome}</div>
        ${item.arch? `<div class="card-arch-badge">${item.arch}</div>`:''}
        <div class="card-rating-secondary">${item.naz||''}</div>
      </div>
      <div class="card-rating-big">${item.rating}<span class="card-rating-big-label">RATING</span></div>
    </div>
    ${item.bonus? `<div class="tag-line bonus">▲ ${shortenText(td(item.bonus),48)}</div>`:''}
    ${item.malus? `<div class="tag-line malus">▼ ${shortenText(td(item.malus),48)}</div>`:''}
    <details class="card-details">
      <summary onclick="event.stopPropagation()">${t('pcard_details')}</summary>
      <div class="stat-bars">${stats}</div>
      ${item.bonus? `<div class="tag-line bonus">▲ ${td(item.bonus)}</div>`:''}
      ${item.malus? `<div class="tag-line malus">▼ ${td(item.malus)}</div>`:''}
      ${item.abilita? `<div class="ability">${td(item.abilita)}</div>`:''}
    </details>
    <div class="card-tap-hint">${t('pcard_tap_to_choose')}</div>
    ${extraLine||''}
  </div>`;
}

const STAT_KEYS = {
  pilotMain: ['qualifica','sorpassi','costanza','affidabilita'],
  pilotSecond: ['qualifica','sorpassi','costanza','affidabilita'],
  motore: ['potenza','affidabilita','accelerazione','consumo'],
  telaio: ['leggerezza','bilanciamento','sicurezza','affidabilita'],
  aero: ['velmax','curveveloci','curvelente','stabilita'],
  gomme: ['grip','durata','bagnato','degrado'],
  stratega: ['pitstop','letturagara','safetycar','pressione']
};

