// V0.9.3.3: card dei risultati da condividere — stesso principio del mockup approvato:
// altezza calcolata in sequenza (si adatta alla posa), logo grande, niente link scritto nei pixel.
function loadImg(src){
  return new Promise((resolve,reject)=>{
    const img = new Image();
    img.onload = ()=>resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

// V0.9.9.73: formato condiviso per le schermate finali — il FOCUS e' la scuderia, non il singolo
// pilota, come richiesto esplicitamente da Gio con 3 esempi precisi. Riusata sia dalla carta
// condivisibile (immagine) sia dalla schermata fine stagione a schermo, cosi' restano coerenti.
// V0.9.9.170: PUNTO 13 — schermata di rivelazione punteggio Daily con animazione, richiesta da
// Gio. Calcola il dettaglio completo del punteggio direttamente dai dati locali disponibili a fine
// gara (senza aspettare il salvataggio sul database) — riusa esattamente la stessa formula di
// computeDailyFinalScore (mai calcoli duplicati/divergenti che potrebbero disallinearsi in futuro),
// ma restituisce anche tutti i valori intermedi (i singoli fattori, non solo il totale) per poterli
// mostrare uno per uno nella rivelazione animata.
function computeDailyScoreBreakdown(){
  const cstd = constructorStandingsSorted();
  const myConstructorIdx = cstd.findIndex(c=>c.teamId==='PLAYER');
  const myConstructor = myConstructorIdx>=0 ? cstd[myConstructorIdx] : null;
  const points = myConstructor ? myConstructor.points : 0;
  const componentsSum = ['motore','telaio','aero','gomme','stratega']
    .reduce((sum,key)=> sum + (state.team[key] ? state.team[key].rating : 0), 0);
  const dstd = driverStandingsSorted().filter(d=>!d.isFormer);
  const myDriverIdx = dstd.findIndex(d=>d.isPlayerTeam);
  const driverPosition = myDriverIdx>=0 ? myDriverIdx+1 : null;
  const constructorPosition = myConstructorIdx>=0 ? myConstructorIdx+1 : null;
  let gapFromRival = 0;
  if(myConstructor && cstd.length>1){
    const rivali = cstd.filter(c=>c.teamId!=='PLAYER');
    let minAbsGap = Infinity;
    rivali.forEach(c=>{
      const g = myConstructor.points - c.points;
      if(Math.abs(g) < minAbsGap){ minAbsGap = Math.abs(g); gapFromRival = g; }
    });
  }
  const initialRating = state.initialComponentRatings
    ? Object.values(state.initialComponentRatings).reduce((s,v)=>s+v, 0) : null;
  const platinumParts = ['motore','telaio','aero','gomme','stratega']
    .filter(key => state.team[key] && state.team[key].rating>=100).length;
  const attemptNumber = state.dailySeasonAttemptNumber || 1;

  const r = { points, budget_saved: state.budget, components_sum: componentsSum,
    driver_position: driverPosition, constructor_position: constructorPosition,
    gap_from_rival: gapFromRival, initial_rating: initialRating, platinum_parts: platinumParts,
    attempt_number: attemptNumber };

  // stessi identici calcoli di computeDailyFinalScore, ma qui restiamo con i valori intermedi
  const driverScore = Math.max(0, (21 - (driverPosition ?? 20)) / 20 * 100);
  const ctorScore = Math.max(0, (11 - (constructorPosition ?? 10)) / 10 * 100);
  const ratingScore = Math.min(100, componentsSum / 500 * 100);
  const gapScore = Math.max(0, Math.min(100, 50 + gapFromRival / 2));
  const budgetScore = Math.min(100, state.budget / 60 * 100);
  const platinoScore = platinumParts / 5 * 100;
  const ratingIniScore = Math.min(100, (initialRating ?? 0) / 500 * 100);
  const secondario0a100 = 0.19*driverScore + 0.19*ctorScore + 0.19*ratingScore + 0.16*gapScore
    + 0.11*budgetScore + 0.11*platinoScore + 0.05*ratingIniScore;
  const puntiComponente = Math.min(1, points / DAILY_SCORE_POINTS_MAX) * (DAILY_SCORE_MAX - DAILY_SCORE_SECONDARY_MAX);
  const secondarioComponente = (secondario0a100/100) * DAILY_SCORE_SECONDARY_MAX;
  const fattorePenalita = 1 - Math.max(0, attemptNumber-1) * 0.01;
  const totale = Math.round((puntiComponente + secondarioComponente) * fattorePenalita);

  return {
    totale, puntiComponente: Math.round(puntiComponente), secondarioComponente: Math.round(secondarioComponente*10)/10,
    fattorePenalita, attemptNumber, points,
    // V0.9.9.172: valueLabel aggiunto per ciascun fattore — un valore leggibile ("1°", "400/500",
    // "+15 pt") da mostrare accanto al nome, non solo la percentuale. Nessuna modifica alla formula
    // di calcolo sopra, solo dati aggiuntivi per la visualizzazione.
    fattori: [
      { label:t('daily_score_factor_driver'), pct:driverScore, peso:19, valueLabel: driverPosition ? `${driverPosition}°` : '—' },
      { label:t('daily_score_factor_constructor'), pct:ctorScore, peso:19, valueLabel: constructorPosition ? `${constructorPosition}°` : '—' },
      { label:t('daily_score_factor_rating'), pct:ratingScore, peso:19, valueLabel: `${componentsSum}/500` },
      { label:t('daily_score_factor_gap'), pct:gapScore, peso:16, valueLabel: `${gapFromRival>=0?'+':''}${gapFromRival} pt` },
      { label:t('daily_score_factor_budget'), pct:budgetScore, peso:11, valueLabel: `${fmtM(state.budget)}` },
      { label:t('daily_score_factor_platino'), pct:platinoScore, peso:11, valueLabel: `${platinumParts}/5` },
      { label:t('daily_score_factor_initial'), pct:ratingIniScore, peso:5, valueLabel: `${initialRating ?? 0}/500` },
    ],
  };
}
function computeSeasonEndSummaryLines(){
  const dstd = driverStandingsSorted();
  const cstd = constructorStandingsSorted();
  const constructorPos = cstd.findIndex(c=>c.teamId==='PLAYER')+1;
  const isConstructorChamp = constructorPos===1;
  const driverChamp = dstd[0];

  const p1Pos = dstd.findIndex(d=>d.slotKey==='PLAYER-1' && !d.isFormer)+1;
  const p2Pos = state.team.pilotSecond ? dstd.findIndex(d=>d.slotKey==='PLAYER-2' && !d.isFormer)+1 : null;
  const p1IsChamp = driverChamp.isPlayerTeam && driverChamp.slotKey==='PLAYER-1';
  const p2IsChamp = driverChamp.isPlayerTeam && driverChamp.slotKey==='PLAYER-2';

  const drivers = [{ name: state.team.pilotMain.nome, pos: p1Pos, isChamp: p1IsChamp, slotKey:'PLAYER-1' }];
  if(state.team.pilotSecond){
    drivers.push({ name: state.team.pilotSecond.nome, pos: p2Pos, isChamp: p2IsChamp, slotKey:'PLAYER-2' });
  }
  return {
    teamName: teamDisplayName(),
    isConstructorChamp,
    constructorPos,
    drivers,
    anyDriverChamp: p1IsChamp || p2IsChamp,
  };
}
async function buildShareCardCanvas(){
  const dstd = driverStandingsSorted();
  const cstd = constructorStandingsSorted();
  const p1 = state.driverStandings['PLAYER-1'];
  const p2 = state.driverStandings['PLAYER-2'];
  const constructorPos = cstd.findIndex(c=>c.teamId==='PLAYER')+1;
  const driverChamp = dstd[0];
  const constructorChamp = cstd[0];
  const isDriverChamp = driverChamp.isPlayerTeam;

  const { points: totalPoints, wins: totalWins, podiums: totalPodiums, dnfs: totalDnfs } = playerSeasonTotals();

  const bestDriverRating = isDriverChamp
    ? (driverChamp.slotKey==='PLAYER-1' ? state.team.pilotMain.rating : state.team.pilotSecond.rating)
    : Math.max(state.team.pilotMain.rating, state.team.pilotSecond.rating);
  const band = ratingBandKey(bestDriverRating);

  const summary = computeSeasonEndSummaryLines();
  let title, subtitle;
  title = summary.teamName.toUpperCase();
  subtitle = summary.isConstructorChamp ? t('share_constructors_won_line') : t('share_team_position_line', summary.constructorPos);
  const metaLine = state.isDailySeason
    ? t('share_daily_meta', state.seasonLength)
    : `${state.seasonLength===20?t('share_full_season'):t('share_quick_season')}  ·  ${DIFFICULTY_LABEL[state.difficulty]}`;

  // V0.9.9.87: se e' una Daily Season, aggiungiamo la posizione vera in classifica — la carta resta
  // quella ricca standard (posa, statistiche, componenti, sponsor, trofei), non una a parte, come
  // chiarito da Gio: la classifica e' importante ma non l'unica cosa che deve comparire.
  let dailyRank = null, dailyWeightedRank = null, dailyWeightedTotal = null;
  if(state.isDailySeason){
    if(__dailySaveInFlight){ try{ await __dailySaveInFlight; }catch(e){} } // aspetta il salvataggio vero prima di leggere la classifica
    await loadDailyBestResultToday();
    dailyRank = dailyBestResultCache ? dailyBestResultCache.rank : null;
    if(currentUser && supabaseClient){
      try{
        const { data } = await supabaseClient.from('daily_weighted_leaderboard_view')
          .select('user_id').order('rating_medio', { ascending:false });
        if(data){
          const idx = data.findIndex(r=>r.user_id===currentUser.id);
          if(idx>=0){ dailyWeightedRank = idx+1; dailyWeightedTotal = data.length; }
        }
      }catch(e){ /* silenzioso: la carta funziona comunque senza questo dato */ }
    }
  }

  const poseNum = isDriverChamp ? 1 : (2+Math.floor(rnd()*4));
  const isGoatChamp = isDriverChamp && driverChamp.nome==='THE GOAT';
  const poseBand = isGoatChamp ? 'goat_ferrari' : band;
  const poseSrc = `assets/share-poses/pose${poseNum}_${poseBand}.webp`;
  const accent = isGoatChamp ? '#FF1801' : CAR_RARITY_COLOR[band];

  // V0.9.9.73: il FOCUS e' la scuderia (titolo+sottotitolo sopra), non piu' il singolo pilota — su
  // richiesta esplicita di Gio con esempi precisi. Una riga per ogni pilota, ciascuna col proprio
  // risultato individuale (campione del mondo o posizione), mostrate sotto le statistiche.
  const driverLines = summary.drivers.map(d => `${d.name}: ${d.isChamp ? t('share_champion_short') : 'P'+d.pos}`);

  const [logoImg, poseImg] = await Promise.all([loadImg(LOGO_DATA_URI), loadImg(poseSrc)]);
  const compRows = [
    { label:t('share_comp_motore'), init:state.initialComponentRatings?.motore, cur:state.team.motore.rating },
    { label:t('share_comp_telaio'), init:state.initialComponentRatings?.telaio, cur:state.team.telaio.rating },
    { label:t('share_comp_aero'), init:state.initialComponentRatings?.aero, cur:state.team.aero.rating },
    { label:t('share_comp_gomme'), init:state.initialComponentRatings?.gomme, cur:state.team.gomme.rating },
    { label:t('share_comp_stratega'), init:state.initialComponentRatings?.stratega, cur:state.team.stratega.rating },
  ];
  const sponsorImg = state.sponsor ? await loadImg(sponsorLogoSrc(state.sponsor.nome)).catch(()=>null) : null;
  const seasonTrophyNames = state.seasonTrophiesWon || [];
  const trophyImgs = (await Promise.all(seasonTrophyNames.map(name =>
    loadImg(`assets/circuit-trophies/${slugify(name)}_oro.webp`).catch(()=>null)
  ))).filter(Boolean);

  const W = 720, M = 36; // M = margine laterale, ridotto da 50 per un feel piu' denso
  const cv = document.createElement('canvas');
  let ctx = cv.getContext('2d');

  // --- passo 1: calcolo altezze in sequenza, tutto piu' stretto rispetto a prima ---
  let cursor = 28;
  // header: logo molto piu' piccolo (funziona da intestazione, non da hero)
  const logoW = Math.round(W*0.40), logoH = Math.round(logoImg.height*(logoW/logoImg.width));
  const logoY = cursor; cursor += logoH + 4;
  const subY = cursor; cursor += 24;
  cursor += 14; // spazio prima del divisore
  const dividerY = cursor; cursor += 18;

  // blocco risultato principale: titolo+sottotitolo+meta come un unico blocco coeso
  const resultY = cursor;
  cursor += 46 + 30 + 26 + 18;

  // V0.9.9.87: riga posizione Daily, solo se e' una Daily Season — un badge compatto, non un
  // blocco enorme, la carta resta quella ricca standard con questo in piu'.
  const dailyRankY = state.isDailySeason ? cursor : null;
  if(state.isDailySeason) cursor += 54;

  // hero pilota/podio — meno spazio vuoto sopra/sotto, leggermente piu' stretto
  const poseW = Math.round(W*0.40), poseH = Math.round(poseImg.height*(poseW/poseImg.width));
  const py = cursor; cursor += poseH + 18;

  // statistiche: pannello compatto a 3 colonne + riga campione/ritiri sotto
  const statsY = cursor;
  cursor += 92 + (driverLines.length*26 + 12) + 22;

  // componenti + sponsor, stessa riga
  const compY = cursor;
  const compRowH = 32;
  const compBlockH = 26 + compRows.length*compRowH;
  cursor += compBlockH + 20;

  // trofei stagione — V0.9.9.49: FIX segnalato da Gio, prima ogni trofeo veniva stirato in un
  // riquadro quadrato (deformandolo, dato che i trofei sono piu' alti che larghi, ~0.79 di rapporto)
  // e la fila era allineata a sinistra. Ora: altezza fissa, larghezza proporzionata per ognuno,
  // righe calcolate sulla larghezza VERA (non su una dimensione fissa), righe centrate.
  const trophyRowY = (trophyImgs.length>0) ? cursor : null;
  const trophySize = 64, trophyGap = 12;
  const trophyRowsPacked = [];
  if(trophyImgs.length>0){
    const availW = W-2*M;
    let curRow = [], curRowW = 0;
    for(const img of trophyImgs){
      const w = trophySize * (img.width/img.height);
      const addW = curRow.length===0 ? w : w+trophyGap;
      if(curRowW + addW > availW && curRow.length>0){
        trophyRowsPacked.push(curRow); curRow = []; curRowW = 0;
      }
      curRow.push({ img, w });
      curRowW += (curRow.length===1 ? w : w+trophyGap);
    }
    if(curRow.length>0) trophyRowsPacked.push(curRow);
    cursor += 26 + trophyRowsPacked.length*(trophySize+trophyGap) - trophyGap + 18;
  }

  // CTA finale, piu' basso di prima
  const boxY0 = cursor, boxY1 = boxY0 + 72; cursor = boxY1 + 28;
  const H = cursor;

  cv.width = W; cv.height = H;
  ctx = cv.getContext('2d');

  // V0.9.9.50: proviamo lo sfondo col colore VERO dello sponsor invece che del pilota — il resto
  // (titolo, statistiche, box finale) resta legato alla fascia del pilota come prima, solo il
  // bagliore di sfondo cambia fonte. Riserva al colore pilota se non c'e' uno sponsor attivo.
  const sponsorBrand = state.sponsor ? SPONSOR_BRAND[state.sponsor.nome] : null;
  const bgGlowColor = sponsorBrand ? sponsorBrand.accent : accent;
  ctx.fillStyle = '#08090c'; ctx.fillRect(0,0,W,H);
  const grad = ctx.createRadialGradient(W*0.62,H*0.5,0, W*0.62,H*0.5, H*0.75);
  grad.addColorStop(0, bgGlowColor+'50'); grad.addColorStop(1, '#08090c00');
  ctx.fillStyle = grad; ctx.fillRect(0,0,W,H);
  ctx.strokeStyle = 'rgba(255,255,255,0.045)';
  for(let i=-H;i<W;i+=34){ ctx.beginPath(); ctx.moveTo(i,0); ctx.lineTo(i+H,H); ctx.stroke(); }
  for(let cx=0; cx<W; cx+=16){ ctx.fillStyle = (cx/16)%2===0 ? '#ebebeb' : '#121318'; ctx.fillRect(cx,0,16,7); }

  // header: logo piccolo + sottotitolo + divisore sottile
  ctx.drawImage(logoImg, (W-logoW)/2, logoY, logoW, logoH);
  ctx.fillStyle = '#8c8c94'; ctx.font = '15px -apple-system,sans-serif'; ctx.textAlign='center';
  ctx.fillText(t('share_manager_tag'), W/2, subY+14);
  ctx.textAlign='left';
  ctx.strokeStyle = '#2a2c31'; ctx.beginPath(); ctx.moveTo(M,dividerY); ctx.lineTo(W-M,dividerY); ctx.stroke();

  // blocco risultato principale — un'unica composizione coesa, non tre righe scollegate
  ctx.fillStyle = accent; ctx.font = '900 40px -apple-system,sans-serif';
  ctx.fillText(title, M, resultY+40);
  ctx.fillStyle = '#e8e8ec'; ctx.font = '600 23px -apple-system,sans-serif';
  ctx.fillText(subtitle, M, resultY+72);
  ctx.fillStyle = '#83838b'; ctx.font = '17px -apple-system,sans-serif';
  ctx.fillText(metaLine, M, resultY+98);

  // V0.9.9.87: badge posizione Daily — compatto, si integra nella carta ricca esistente invece di
  // sostituirla, come chiarito da Gio ("la classifica è importante ma non l'unica cosa che conta").
  if(state.isDailySeason){
    ctx.fillStyle = accent+'18';
    roundRectPath(ctx, M, dailyRankY, W-2*M, 44, 10); ctx.fill();
    ctx.strokeStyle = accent+'70'; ctx.lineWidth = 1.5;
    roundRectPath(ctx, M, dailyRankY, W-2*M, 44, 10); ctx.stroke();
    ctx.fillStyle = accent; ctx.font = '900 21px -apple-system,sans-serif';
    ctx.fillText(dailyRank!==null ? '#'+dailyRank : '—', M+16, dailyRankY+29);
    ctx.fillStyle = '#c9c9d0'; ctx.font = '600 13px -apple-system,sans-serif';
    // V0.9.9.171: aggiunto il punteggio Daily vero e proprio accanto alla posizione — prima la
    // carta mostrava solo la classifica (#3, Generale #12/450), mai il numero del punteggio stesso,
    // nonostante il calcolo esistesse già (usato per la nuova schermata di rivelazione, punto 13).
    const punteggioDailyVero = computeDailyScoreBreakdown().totale;
    let badgeLabel = t('daily_share_badge_score', punteggioDailyVero.toLocaleString('it-IT'));
    badgeLabel += '   ·   ' + t('daily_share_badge_today');
    if(dailyWeightedRank!==null) badgeLabel += '   ·   ' + t('daily_share_badge_weighted', dailyWeightedRank, dailyWeightedTotal);
    ctx.fillText(badgeLabel, M+70, dailyRankY+29);
  }

  // hero: ombra morbida + posa, meno margine sopra/sotto
  ctx.save();
  ctx.filter = 'blur(14px)';
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.beginPath(); ctx.ellipse(W/2, py+poseH-8, poseW/2+16, 20, 0, 0, 2*Math.PI); ctx.fill();
  ctx.restore();
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(poseImg, (W-poseW)/2, py, poseW, poseH);

  // statistiche — pannello compatto a 3 colonne (numero grande + etichetta piccola), non piu'
  // quattro righe impilate. La quarta info (campione/ritiri) resta sotto come riga singola.
  const statsPanelX = M, statsPanelW = W-2*M;
  ctx.fillStyle = 'rgba(255,255,255,0.035)';
  roundRectPath(ctx, statsPanelX, statsY, statsPanelW, 92 + (driverLines.length*26 + 12), 14);
  ctx.fill();
  const threeStats = [ [totalWins, t('share_stat_wins')], [totalPodiums, t('share_stat_podiums')], [totalPoints, t('share_stat_points')] ];
  const colW = statsPanelW/3;
  threeStats.forEach(([val,label], i)=>{
    const cx = statsPanelX + colW*i + colW/2;
    ctx.textAlign = 'center';
    ctx.fillStyle = accent; ctx.font = '900 42px -apple-system,sans-serif';
    ctx.fillText(String(val), cx, statsY+52);
    ctx.fillStyle = '#93939b'; ctx.font = '600 14px -apple-system,sans-serif';
    ctx.fillText(label.toUpperCase(), cx, statsY+76);
    if(i>0){ ctx.strokeStyle='rgba(255,255,255,0.08)'; ctx.beginPath(); ctx.moveTo(statsPanelX+colW*i,statsY+18); ctx.lineTo(statsPanelX+colW*i,statsY+74); ctx.stroke(); }
  });
  ctx.textAlign = 'left';
  driverLines.forEach((line, i)=>{
    ctx.fillStyle = '#d5d5da'; ctx.font = '700 19px -apple-system,sans-serif'; ctx.textAlign='center';
    ctx.fillText(line, W/2, statsY+92+24+i*26);
    ctx.textAlign='left';
  });

  // componenti (sinistra, valore vicino all'etichetta) + sponsor (destra, logo grande) — stessa riga
  const compColW = statsPanelW*0.54;
  ctx.fillStyle = '#c9c9d0'; ctx.font = '700 17px -apple-system,sans-serif';
  ctx.fillText(t('share_components_title'), M, compY+16);
  let cyy = compY + 34;
  for(const row of compRows){
    ctx.fillStyle = '#83838b'; ctx.font = '600 17px -apple-system,sans-serif';
    ctx.fillText(row.label, M, cyy+14);
    const labelW = ctx.measureText(row.label).width;
    const hasInit = row.init!==undefined && row.init!==null;
    const valueText = hasInit ? `${row.init} → ${row.cur}` : `${row.cur}`;
    const improved = hasInit && row.cur > row.init;
    ctx.fillStyle = improved ? '#4CD97B' : '#c9c9d0';
    ctx.font = '700 18px -apple-system,sans-serif';
    ctx.fillText(valueText, M+labelW+12, cyy+15);
    cyy += compRowH;
  }
  if(state.sponsor && sponsorImg){
    const sponsorAreaX = M+compColW+16, sponsorAreaW = W-M-sponsorAreaX;
    const maxLogoH = 104, maxLogoW = sponsorAreaW; // V0.9.9.49: ingrandito, prima lasciava troppo vuoto (era 66)
    let logoW2 = maxLogoW, logoH2 = logoW2 * sponsorImg.height/sponsorImg.width;
    if(logoH2 > maxLogoH){ logoH2 = maxLogoH; logoW2 = logoH2 * sponsorImg.width/sponsorImg.height; }
    const logoX = sponsorAreaX + (sponsorAreaW-logoW2)/2;
    const logoTopY = compY + 12;
    ctx.drawImage(sponsorImg, logoX, logoTopY, logoW2, logoH2);
    ctx.fillStyle = '#83838b'; ctx.font = '14px -apple-system,sans-serif'; ctx.textAlign='center';
    ctx.fillText(t('share_sponsor_label'), sponsorAreaX+sponsorAreaW/2, logoTopY+logoH2+22);
    ctx.fillStyle = '#e1e1e6'; ctx.font = '700 19px -apple-system,sans-serif';
    ctx.fillText(state.sponsor.nome, sponsorAreaX+sponsorAreaW/2, logoTopY+logoH2+45);
    ctx.textAlign='left';
  }

  // trophy strip — righe centrate, ogni trofeo con la SUA proporzione (mai stirato)
  if(trophyImgs.length>0){
    ctx.fillStyle = '#c9c9d0'; ctx.font = '700 15px -apple-system,sans-serif'; ctx.textAlign='center';
    ctx.fillText(t('share_season_trophies_title', trophyImgs.length), W/2, trophyRowY+14);
    ctx.textAlign='left';
    let rowTopY = trophyRowY + 26;
    for(const row of trophyRowsPacked){
      const rowW = row.reduce((s,t)=>s+t.w, 0) + trophyGap*(row.length-1);
      let tx = (W-rowW)/2; // centrata, non piu' allineata a sinistra
      for(const {img,w} of row){
        ctx.drawImage(img, tx, rowTopY, w, trophySize);
        tx += w + trophyGap;
      }
      rowTopY += trophySize + trophyGap;
    }
  }

  // CTA finale — piu' basso di prima, larghezza quasi piena
  ctx.fillStyle = accent+'22'; roundRectPath(ctx, M, boxY0, W-2*M, boxY1-boxY0, 12); ctx.fill();
  ctx.strokeStyle = accent; ctx.lineWidth = 2.5; roundRectPath(ctx, M, boxY0, W-2*M, boxY1-boxY0, 12); ctx.stroke();
  ctx.fillStyle = accent; ctx.font = '900 26px -apple-system,sans-serif'; ctx.textAlign='center';
  ctx.fillText(t('share_beat_me'), W/2, boxY0+45);
  ctx.textAlign='left';

  // coriandoli statici, solo per il titolo piloti — densita' e range adattati alla card piu' corta
  if(isDriverChamp){
    const seedRnd = (n)=>{ const x = Math.sin(n*999)*10000; return x-Math.floor(x); };
    const confColors = ['#FFD700','#FFEE99','#F7B800','#FFFFFF','#FFAA00'];
    for(let i=0;i<36;i++){
      const cx = seedRnd(i)*W, cyp = seedRnd(i+500)*(H-subY-40)+subY+40;
      const size = 5+seedRnd(i+900)*7;
      const rot = seedRnd(i+50)*360;
      ctx.save();
      ctx.translate(cx,cyp); ctx.rotate(rot*Math.PI/180);
      ctx.fillStyle = confColors[i%confColors.length];
      ctx.fillRect(-size/2,-size*0.9,size,size*1.8);
      ctx.restore();
    }
  }

  return cv;
}
function roundRectPath(ctx, x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x+r, y);
  ctx.arcTo(x+w, y, x+w, y+h, r);
  ctx.arcTo(x+w, y+h, x, y+h, r);
  ctx.arcTo(x, y+h, x, y, r);
  ctx.arcTo(x, y, x+w, y, r);
  ctx.closePath();
}

async function buildTrophyRoomCanvas(){
  const circuits = DATA.circuiti;
  const total = circuits.length;
  const racedCount = circuits.filter(c=> trophyData[c.nome] && trophyData[c.nome].raced>0).length;
  const wonCount = circuits.filter(c=> trophyData[c.nome] && trophyData[c.nome].won>0).length;

  const logoImg = await loadImg(LOGO_DATA_URI);
  const W = 720;
  const cols = 8, cellSize = 78, gap = 6;
  const gridW = cols*cellSize + (cols-1)*gap;
  const rows = Math.ceil(total/cols);
  const gridH = rows*cellSize + (rows-1)*gap;

  let cursor = 50;
  const logoW = Math.round(W*0.8), logoH = Math.round(logoImg.height*(logoW/logoImg.width));
  const logoY = cursor; cursor += logoH + 30;
  const titleY = cursor; cursor += 60;
  const statsY = cursor; cursor += 50;
  const gridY = cursor; cursor += gridH + 40;
  const H = cursor;

  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const ctx = cv.getContext('2d');
  ctx.fillStyle = '#08090c'; ctx.fillRect(0,0,W,H);
  const grad = ctx.createRadialGradient(W*0.5,H*0.3,0, W*0.5,H*0.3, 500);
  grad.addColorStop(0,'#F7B80044'); grad.addColorStop(1,'#08090c00');
  ctx.fillStyle = grad; ctx.fillRect(0,0,W,H);

  ctx.drawImage(logoImg, (W-logoW)/2, logoY, logoW, logoH);
  ctx.fillStyle = '#F7B800'; ctx.font = '900 34px -apple-system,sans-serif'; ctx.textAlign='center';
  ctx.fillText(t('share_trophy_title'), W/2, titleY);
  ctx.fillStyle = '#c8c8ce'; ctx.font = '20px -apple-system,sans-serif';
  ctx.fillText(t('share_trophy_stats', racedCount, total, wonCount), W/2, statsY);
  ctx.textAlign='left';

  const gridX = (W-gridW)/2;
  const imgs = await Promise.all(circuits.map(c=>{
    const td = trophyData[c.nome] || {raced:0,won:0};
    if(td.won>0) return loadImg(`assets/circuit-trophies/${slugify(c.nome)}_oro.webp`);
    if(td.raced>0) return loadImg(`assets/circuit-trophies/${slugify(c.nome)}_bloccato.webp`);
    return Promise.resolve(null);
  }));
  circuits.forEach((c,i)=>{
    const col = i%cols, row = Math.floor(i/cols);
    const x = gridX + col*(cellSize+gap), y = gridY + row*(cellSize+gap);
    const td = trophyData[c.nome] || {raced:0,won:0};
    ctx.fillStyle = 'rgba(255,255,255,0.04)'; ctx.fillRect(x,y,cellSize,cellSize);
    if(td.won>0 || td.raced>0){
      const img = imgs[i];
      // V0.9.4.2.2: le icone trofeo sono alte e strette — vanno contenute su ENTRAMBE le dimensioni
      // (come "object-fit:contain"), non solo per larghezza, altrimenti sforano la cella e si sovrappongono.
      const boxSize = cellSize - 20;
      const fitScale = Math.min(boxSize/img.width, boxSize/img.height);
      const iw = img.width*fitScale, ih = img.height*fitScale;
      ctx.drawImage(img, x+(cellSize-iw)/2, y+(cellSize-ih)/2-4, iw, ih);
      if(td.won>0){
        ctx.fillStyle = '#F7B800'; ctx.font = '900 12px -apple-system,sans-serif'; ctx.textAlign='center';
        ctx.fillText(`${td.won}×`, x+cellSize/2, y+cellSize-6);
        ctx.textAlign='left';
      }
    } else {
      ctx.fillStyle = 'rgba(255,255,255,0.15)'; ctx.font = '900 22px -apple-system,sans-serif'; ctx.textAlign='center';
      ctx.fillText('?', x+cellSize/2, y+cellSize/2+8);
      ctx.textAlign='left';
    }
  });
  return cv;
}

async function shareTrophyRoomCard(){
  try{
    const cv = await buildTrophyRoomCanvas();
    const blob = await new Promise(res=>cv.toBlob(res,'image/png'));
    const fileName = 'racing-dynasty-sala-trofei.png';
    const gameUrl = 'https://racingdynasty.fuoriscala.xyz/';
    const shareText = `La mia Sala Trofei su Racing Dynasty — prova a battermi!\n${gameUrl}`;
    if(navigator.share && navigator.canShare && navigator.canShare({ files:[new File([blob], fileName, {type:'image/png'})] })){
      await navigator.share({ files:[new File([blob], fileName, {type:'image/png'})], text: shareText });
    } else {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = fileName; document.body.appendChild(a); a.click(); a.remove();
      setTimeout(()=>URL.revokeObjectURL(url), 2000);
      alert('Immagine salvata! Testo da condividere insieme:\n\n'+shareText);
    }
  }catch(e){
    alert('Non sono riuscito a generare la Sala Trofei da condividere. Riprova.');
  }
}

